function IsBoomMode(aiBrain)
    return aiBrain ~= nil and aiBrain[refbBoomMode] == true
end

function SetTeamBoomMode(iTeam, bEnabled)
    if iTeam then tbBoomModeByTeam[iTeam] = bEnabled == true end
end

function IsTeamBoomMode(iTeam)
    --A boom mode brain forces the whole team into economy priority mode
    --The cached value closes the initialization race where the admin toggles
    --boom before the human brain has been inserted into the active-brain list.
    if iTeam and tbBoomModeByTeam[iTeam] == true then return true end
    if iTeam and AiBotTeam.tTeamData[iTeam] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] then
        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
            if oBrain[refbBoomMode] == true then return true end
        end
    end
    return false
end

function GetNearestEnemyBrain(aiBrain)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetNearestEnemyBrain'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local oNearestBrainThatAreIgnoring
    if aiBrain[refoNearestEnemyBrain][AiBotMap.refbIgnoreForNearestPlayerIndexByTeam][aiBrain.AiBotTeam] and not(aiBrain[refoNearestEnemyBrain].AiBotIsDefeated) and not(aiBrain[refoNearestEnemyBrain]:IsDefeated()) then oNearestBrainThatAreIgnoring = aiBrain[refoNearestEnemyBrain] end
    if (aiBrain[refoNearestEnemyBrain] and not(aiBrain[refoNearestEnemyBrain].AiBotIsDefeated) and not(aiBrain[refoNearestEnemyBrain]:IsDefeated()) and not(aiBrain[refoNearestEnemyBrain][AiBotMap.refbIgnoreForNearestPlayerIndexByTeam][aiBrain.AiBotTeam])) or aiBrain.AiBotIsDefeated then
        if bDebugMessages == true then LOG(sFunctionRef..': Previously nearest enemy brain is still valid='..(aiBrain[refoNearestEnemyBrain].Nickname or 'nil')) end
        return aiBrain[refoNearestEnemyBrain]
    else
        if bDebugMessages == true then LOG(sFunctionRef..': aiBrain='..aiBrain.Nickname..'; GameTime='..GetGameTimeSeconds()..'; Is pathing complete='..tostring(AiBotMap.bMapLandSetupComplete)..'; Dont have a valid nearest enemy already recorded for aiBrain '..(aiBrain.Nickname or 'nil')..' with index '..aiBrain:GetArmyIndex()..' so will get a new one; are all enemies defeated for team '..aiBrain.AiBotTeam..'='..tostring(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefbAllEnemiesDefeated])) end
        local oNearestBrain
        if AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefbAllEnemiesDefeated] then
            --All enemies defeated so will consider civilians as enemy brains
            local oCivilianBrain
            if bDebugMessages == true then LOG(sFunctionRef..': All enemies defeated so will consider all brains including civilians') end
            for iCurBrain, oBrain in ArmyBrains do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering obrain '..(oBrain.Nickname or 'nil')..'; is enemy to us='..tostring(IsEnemy(oBrain:GetArmyIndex(), aiBrain:GetArmyIndex()))) end
                if IsEnemy(oBrain:GetArmyIndex(), aiBrain:GetArmyIndex()) then
                    oNearestBrain = oBrain
                    break
                elseif AiBotConditions.IsCivilianBrain(oBrain) then
                    oCivilianBrain = oBrain
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': All normal enemies defeated, oNearestBrain='..(oNearestBrain.Nickname or 'nil')..'; oCivilianBrain='..(oCivilianBrain.Nickname or 'nil')) end

            if not (oNearestBrain) then
                oNearestBrain = oCivilianBrain
            end
        else
            local iCurDist
            local iMinDistToEnemy = 10000000
            if bDebugMessages == true then LOG(sFunctionRef .. ': Start before looping through brains; aiBrain personality=' .. ScenarioInfo.ArmySetup[aiBrain.Name].AIPersonality .. '; brain.Name=' .. aiBrain.Name) end

            for iCurBrain, oBrain in ArmyBrains do
                if bDebugMessages == true then LOG(sFunctionRef .. ': Start of brain loop, iCurBrain=' .. iCurBrain .. '; brain personality=' .. ScenarioInfo.ArmySetup[oBrain.Name].AIPersonality .. '; brain Nickname=' .. oBrain.Nickname .. '; Brain index=' .. oBrain:GetArmyIndex() .. '; if brain isnt equal to our AI brain then will get its start position etc. IsCivilian='..tostring(AiBotConditions.IsCivilianBrain(oBrain))..'; IsEnemy='..tostring(IsEnemy(oBrain:GetArmyIndex(), aiBrain:GetArmyIndex()))..'; Is oBrain a .AiBotAI brain='..tostring(oBrain.AiBotAI or false)) end
                if not (oBrain == aiBrain) and (not (AiBotConditions.IsCivilianBrain(oBrain)) and IsEnemy(oBrain:GetArmyIndex(), aiBrain:GetArmyIndex())) and not(oBrain[AiBotMap.refbIgnoreForNearestPlayerIndexByTeam]) then
                    if bDebugMessages == true then LOG(sFunctionRef .. ': Brain is dif to aiBrain and a non civilian enemy so will record its start position number if it doesnt have one already') end

                    if not (oBrain:IsDefeated()) and not (oBrain.AiBotIsDefeated) then
                        --Redundancy for AI like DD that may not trigger the aibrain hook
                        if not(AiBotMap.PlayerStartPoints[oBrain:GetArmyIndex()]) then
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            AiBotMap.RecordBrainStartPoint(oBrain, (AiBotMap.bIsCampaignMap and GetGameTimeSeconds() >= 5 and not(AiBotConditions.DoesAINicknameContainAiBot(oBrain.Nickname)) and oBrain.BrainType == 'AI'))
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

                        end
                        if bDebugMessages == true then
                            LOG(sFunctionRef .. ': Considering nearest enemy for our brain index '..aiBrain:GetArmyIndex()..'; enemy brain with index' .. oBrain:GetArmyIndex() .. ' and nickname '..(oBrain.Nickname or 'nil')..' is not defeated and is an enemy; AiBotMap.PlayerStartPoints='..repru( AiBotMap.PlayerStartPoints))
                            local iX, iZ = AiBotMap.GetPlayerStartPosition(oBrain, true)
                            LOG(sFunctionRef..': Enemy Start iX='..(iX or 'nil')..'; Start iZ+'..(iZ or 'nil'))
                        end
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(AiBotMap.GetPlayerStartPosition(aiBrain), AiBotMap.GetPlayerStartPosition(oBrain))
                        if iCurDist < iMinDistToEnemy then
                            iMinDistToEnemy = iCurDist
                            oNearestBrain = oBrain
                        end
                    end

                    --Strange bug where still returns true for empty slot - below line to avoid this:
                    --[[if GetGameTimeSeconds() <= 5 or brain:GetCurrentUnits(categories.ALLUNITS) > 0 then
                        if bDebugMessages == true then
                            LOG(sFunctionRef .. ': brain has some units')
                        end
                        if AiBotMap.PlayerStartPoints[brain:GetArmyIndex()] then
                            iDistToCurEnemy = AiBotUtilities.GetDistanceBetweenPositions(AiBotMap.PlayerStartPoints[aiBrain:GetArmyIndex()], AiBotMap.PlayerStartPoints[brain:GetArmyIndex()])
                            if bDebugMessages == true then LOG(sFunctionRef..': Dist between brain and aibrain start points='..iDistToCurEnemy) end
                            if iDistToCurEnemy < iMinDistToEnemy then
                                iMinDistToEnemy = iDistToCurEnemy
                                iNearestEnemyIndex = brain:GetArmyIndex()
                                if bDebugMessages == true then
                                    LOG(sFunctionRef .. ': Current nearest enemy index=' .. iNearestEnemyIndex .. '; startp osition of this enemy=' .. repru(AiBotMap.PlayerStartPoints[iNearestEnemyIndex]))
                                end
                            end
                        else
                            if bDebugMessages == true then
                                LOG(sFunctionRef .. ': Map info doesnt have a start point for brain with index=' .. brain:GetArmyIndex()..' and nickanme='..(brain.Nickname or 'nil')..'; PlayerStartPoints='..repru(AiBotMap.PlayerStartPoints))
                            end
                        end
                    else
                        --Can have some cases where have an aibrain but no units, e.g. map Africa has ARMY_9 aibrain name, with no personality, that has no units; will flag the brain as being defeated to be safe if getgametimeseonds is more than 1min
                        if bDebugMessages == true then
                            LOG(sFunctionRef .. ': WARNING: brain isnt defeated but has no units; brain:ArmyIndex=' .. brain:GetArmyIndex())
                        end
                        if GetGameTimeSeconds() >= 60 then brain.AiBotIsDefeated = true end
                    end--]]
                end
            end
        end
        if oNearestBrainThatAreIgnoring and not(oNearestBrain) then
            if bDebugMessages == true then LOG(sFunctionRef..': Will go with brain that are ignoring afterall') end
            oNearestBrain = oNearestBrainThatAreIgnoring
        end
        if not(oNearestBrain) then
            AiBotUtilities.ErrorHandler('Couldnt find a nearest brain to aiBrain='..aiBrain.Nickname)
            if GetGameTimeSeconds() <= 10 then AiBotChat.SendMessage(aiBrain, 'NoEnemies', 'Unable to identify any enemies for '..(aiBrain.Nickname or 'a brain')..', AiBot may not function properly', 0, 10000, false) end
            AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefbAllEnemiesDefeated] = true
            --Set the nearest enemy as the furthest away other brain (even if it isnt an enemy) - i.e. if do as furthest enemy then more likely to have units passing enemy units
            local iFurthestDist = 0
            local iCurDist
            for iBrain, oBrain in ArmyBrains do
                if not(oBrain == aiBrain) then
                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(AiBotMap.GetPlayerStartPosition(aiBrain), AiBotMap.GetPlayerStartPosition(oBrain))
                    if iCurDist > iFurthestDist then
                        oNearestBrain = oBrain
                        iFurthestDist = iCurDist
                    end
                end
            end
        end
        aiBrain[refoNearestEnemyBrain] = oNearestBrain
    end
    return aiBrain[refoNearestEnemyBrain]
end

function GameSettingWarningsChecksAndInitialChatMessages(aiBrain)
    --Run once (i.e. no matter how many AiBot brains are present will run max of one time) at start of the game if an AiBot brain is present
    local sFunctionRef = 'GameSettingWarningsChecksAndInitialChatMessages'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then
        LOG(sFunctionRef .. ': Start of compatibility check.  Size of tAllActiveAiBotBrains=' .. table.getsize(tAllActiveAiBotBrains))
    end
    local sIncompatibleMessage = ''
    local bIncompatible = false
    local bHaveOtherAIMod = false


    if AiBotUtilities.IsTableEmpty(ScenarioInfo.Options.RestrictedCategories) == false then
        bIncompatible = true
        bUnitRestrictionsArePresent = true
        sIncompatibleMessage = sIncompatibleMessage .. ' Unit restrictions. '
    end
    --Check if we can build air factories
    local tFriendlyACU = aiBrain:GetListOfUnits(categories.COMMAND, false, true)
    if bDebugMessages == true then LOG(sFunctionRef..': Is table of friendly ACU empty='..tostring(AiBotUtilities.IsTableEmpty(tFriendlyACU))) end
    while AiBotUtilities.IsTableEmpty(tFriendlyACU) and GetGameTimeSeconds() < 20 do --UEF Campaign M1 - ACU spawns just after 10s
        WaitTicks(1)
        tFriendlyACU = aiBrain:GetListOfUnits(categories.COMMAND, false, true)
        if bDebugMessages == true then LOG(sFunctionRef..': Is tFriendlyACU empty='..tostring( AiBotUtilities.IsTableEmpty(tFriendlyACU))..'; Brain='..aiBrain.Nickname..'; Time='..GetGameTimeSeconds()..'; Is allunits empty='..tostring(AiBotUtilities.IsTableEmpty(aiBrain:GetListOfUnits(categories.ALLUNITS, false, true)))) end
    end
    if AiBotUtilities.IsTableEmpty(tFriendlyACU) == false then
        --GetBlueprintThatCanBuildOfCategory(aiBrain, iCategoryCondition,               oFactory, bGetSlowest, bGetFastest, bGetCheapest, iOptionalCategoryThatMustBeAbleToBuild, bIgnoreTechDifferences)
        local sBlueprint = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, AiBotUnitInfo.refCategoryAirFactory, tFriendlyACU[1])
        if bDebugMessages == true then LOG(sFunctionRef..': If ACU '..tFriendlyACU[1].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tFriendlyACU[1])..' tries to build an air factory, sBLueprint is '..(sBlueprint or 'nil')) end
        local bCantBuild
        if not(sBlueprint) then
            bCantBuild = true
            if bDebugMessages == true then LOG(sFunctionRef..': Blueprint is nil so will set that cant build') end
        else
            if bDebugMessages == true then LOG(sFunctionRef..': Is blueprint '..sBlueprint..' restricted for brain '..aiBrain.Nickname..'='..tostring(AiBotUnitInfo.IsUnitRestricted(sBlueprint, aiBrain:GetArmyIndex()))) end
            if AiBotUnitInfo.IsUnitRestricted(sBlueprint, aiBrain:GetArmyIndex()) then
                bCantBuild = true
            end
        end
        if bCantBuild then
            bAirFactoriesCantBeBuilt = true
            if not(bUnitRestrictionsArePresent) then
                bUnitRestrictionsArePresent = true
                sIncompatibleMessage = sIncompatibleMessage .. ' Custom map script or mod preventing air factories'
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Setting bAirFactoriesCantBeBuilt to true, bAirFactoriesCantBeBuilt='..tostring(bAirFactoriesCantBeBuilt)) end
        end
    end
    if not(bUnitRestrictionsArePresent) then
        --Check if campaign or map has any active restrictions
        if AiBotUtilities.bFAFActive then
            if bDebugMessages == true then LOG(sFunctionRef..': bUnitRestrictionsArePresent='..tostring(bUnitRestrictionsArePresent)..'; Is getrestrictions empty='..tostring(AiBotUtilities.IsTableEmpty(import("/lua/game.lua").GetRestrictions()))..'; reprs of this='..reprs(import("/lua/game.lua").GetRestrictions())..'; bIsCampaignMap='..tostring(AiBotMap.bIsCampaignMap)) end
        else
            if bDebugMessages == true then LOG(sFunctionRef..': Not in FAF so normal method of checking for unit restrictions wont work') end
        end
        if AiBotUtilities.bFAFActive and AiBotUtilities.IsTableEmpty(import("/lua/game.lua").GetRestrictions()) == false then
            bUnitRestrictionsArePresent = true
        end
        if AiBotMap.bIsCampaignMap then
            ForkThread(DelayedCampaignRestrictionsCheck)
        end
    end


    if not (ScenarioInfo.Options.NoRushOption == "Off") then
        bIncompatible = true
        sIncompatibleMessage = sIncompatibleMessage .. ' No rush timer. '
    end
    --Check for non-AI sim-mods.  Thanks to Softles for pointing me towards the __active_mods variable
    local tSimMods = __active_mods or {}
    local tAIModNameWhitelist = { 'M27AI', 'AI-Swarm', 'AI-Uveso', 'AI: DilliDalli', 'Dalli AI', 'Dilli AI', 'M20AI', 'Marlo\'s Sorian AI edit', 'RNGAI', 'SACUAI', 'AiBotAI', 'SorianAI-FAF'}

    local tAIModNameWhereExpectAI = { 'AI-Swarm', 'AI-Uveso', 'AI: DilliDalli', 'Dalli AI', 'Dilli AI', 'M20AI', 'Marlo\'s Sorian AI edit', 'RNGAI', 'M27AI' } --Dont include AiBot in this list, i.e. it shoudl be every AI except AiBot
    local tModIsOk = {}
    local bHaveOtherAI = false
    local sUnnecessaryAIMod
    local iUnnecessaryAIModCount = 0
    for iAI, sAI in tAIModNameWhitelist do
        tModIsOk[sAI] = true
    end
    tModIsOk['Player Modifier PCx'] = true
    local tModIsIncompatible = {}
    tModIsIncompatible['Unit Cap Removed'] = true


    local iSimModCount = 0
    local bFlyingEngineers
    local bM27InGame = false
    local sBlacklistModMessage
    for iMod, tModData in tSimMods do
        if tModIsIncompatible[tModData.name] then
            if not(sBlacklistModMessage) then
                sBlacklistModMessage = ' **WARNING** Incompatible mod detected: '..tModData.name
            else
                sBlacklistModMessage = sBlacklistModMessage ..'; '..tModData.name
            end
        elseif not (tModIsOk[tModData.name]) and tModData.enabled and not (tModData.ui_only) then
            iSimModCount = iSimModCount + 1
            bNonAISimModsActive = true
            if not(AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) then
                bIncompatible = true
                if iSimModCount == 1 then
                    sIncompatibleMessage = sIncompatibleMessage .. ' SIM mods '
                else
                    sIncompatibleMessage = sIncompatibleMessage .. '; '
                end
                sIncompatibleMessage = sIncompatibleMessage .. ' ' .. (tModData.name or 'UnknownName')
                if bDebugMessages == true then
                    LOG('Whitelist of mod names=' .. repru(tModIsOk))
                    LOG(sFunctionRef .. ' About to do reprs of the tModData for mod ' .. (tModData.name or 'nil')..': '..reprs(tModData))
                end

                if string.find(tModData.name, 'Flying engineers') then
                    bFlyingEngineers = true
                    if bDebugMessages == true then LOG(sFunctionRef..': Have flying engineers mod enabled so will adjust engineer categories') end
                elseif tModData.name == 'AI Wave Survival' then
                    --check for game setting that means AiBot can give orders
                    if not(ScenarioInfo.Options.WaveStyle == 'AI/Human Controlled') then
                        sIncompatibleMessage = sIncompatibleMessage .. ' AiBot is expected to be more challenging if you set the Wave Style to "AI/Human Controlled"'
                    end
                end
            end
        elseif tModIsOk[tModData.name] then
            if not(bHaveOtherAIMod) then
                for iAIMod, sAIMod in tAIModNameWhereExpectAI do
                    if sAIMod == tModData.name then
                        bHaveOtherAIMod = true
                        if sAIMod == 'M27AI' then bM27InGame = true end
                        break
                    end
                end
                if bHaveOtherAIMod then
                    --Do we have non-AiBot AI?
                    for iBrain, oBrain in ArmyBrains do
                        if bDebugMessages == true then LOG(sFunctionRef..': Have another AI mod enabled. reprs of oBrain='..reprs(oBrain)..'; is BrainType empty='..tostring(oBrain.BrainType == 'nil')..'; is brian type an empty string='..tostring(oBrain.BrainType == '')) end
                        if ((oBrain.BrainType == 'AI' and not(oBrain.AiBotAI)) or oBrain.DilliDalli) and not(AiBotConditions.IsCivilianBrain(oBrain)) then
                            bHaveOtherAI = true
                            if bDebugMessages == true then LOG('Have an AI for a brain') end
                            break
                        end
                    end
                end
            end
            if bHaveOtherAIMod and not(bHaveOtherAI) then
                local bUnnecessaryMod = false
                for iAIMod, sAIMod in tAIModNameWhereExpectAI do
                    if sAIMod == tModData.name then
                        bUnnecessaryMod = true
                        break
                    end
                end
                if bUnnecessaryMod then

                    iUnnecessaryAIModCount = iUnnecessaryAIModCount + 1
                    if iUnnecessaryAIModCount == 1 then
                        sUnnecessaryAIMod = tModData.name
                    else
                        sUnnecessaryAIMod = sUnnecessaryAIMod..', '..tModData.name
                    end
                end
            end
        end
    end

    if iSimModCount > 0 then
        sIncompatibleMessage = sIncompatibleMessage .. '. '
    end
    local bDontPlayWithM27 = false
    local iHumans = 0
    for iBrain, oBrain in ArmyBrains do
        if oBrain.BrainType == 'Human' then
            iHumans = iHumans + 1
        end
    end
    if bM27InGame then
        --Count how many players - if more than 1 then desync risk
        if iHumans > 1 then
            bDontPlayWithM27 = true --Azraeel came across desyncs when playing with M27 and AiBot together
            bIncompatible = true
        end
    end
    if bDebugMessages == true then
        LOG(sFunctionRef .. ': Finished checking compatibility; compatibility message=' .. sIncompatibleMessage .. '; iSimModCount=' .. iSimModCount..'; sBlacklistModMessage='..(sBlacklistModMessage or 'nil'))
    end

    if iSimModCount > 0 then
        --Basic compatibiltiy with flying engineers mod - allow air engineers to be treated as engineers; also work on mods with similar effect but different name
        if bDebugMessages == true then LOG(sFunctionRef..': Checking for flying engineer compatibility, is table empty of units for T1 engi='..tostring(AiBotUtilities.IsTableEmpty(EntityCategoryGetUnitList(AiBotUnitInfo.refCategoryEngineer * categories.TECH1)))) end
        if not(bFlyingEngineers) and AiBotUtilities.IsTableEmpty(EntityCategoryGetUnitList(AiBotUnitInfo.refCategoryEngineer * categories.TECH1)) then bFlyingEngineers = true end
        if bFlyingEngineers then
            AiBotUnitInfo.refCategoryEngineer = AiBotUnitInfo.refCategoryEngineer + categories.ENGINEER * categories.AIR * categories.CONSTRUCTION - categories.EXPERIMENTAL
            if bDebugMessages == true then LOG(sFunctionRef..': Including air engineers in the engineer category; is xsl0105 an engineer='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, 'xsl0105'))..'; Is it categories.ENGINEER='..tostring(EntityCategoryContains(categories.ENGINEER, 'xsl0105'))..'; is it categories.AIR='..tostring(EntityCategoryContains(categories.AIR, 'xsl0105'))..'; is it categories.construction='..tostring(EntityCategoryContains(categories.CONSTRUCTION, 'xsl0105'))) end
        end
        --BREWLAN compatibility - it adds the TRANSPORTATION category to units that cant transport, leading to errors when AiBot tries using them or getting their cargo
        if categories.TORPEDOBOMBER then AiBotUnitInfo.refCategoryTransport = AiBotUnitInfo.refCategoryTransport - categories.TORPEDOBOMBER end --thanks to Balthazaar who gave this tip for checking if a custom category exists
    end
    if sBlacklistModMessage then
        bIncompatible = true
        sIncompatibleMessage = sIncompatibleMessage..sBlacklistModMessage
    end

    if bIncompatible then
        if bDontPlayWithM27 then
            if sUnnecessaryAIMod and not(bHaveOtherAI) then
                --Disabled as seen a bunch of games with M27 enabled and AiBot active with no desync
                --AiBotChat.SendMessage(aiBrain, 'SendGameCompatibilityWarning', 'Sorry I don’t like it when M27AI is watching and adults are around - he teases me about how much better he is and sometimes the game desyncs.  Please disable the M27AI mod.', 15, 15)
            else
                --warning based on Az noting there were sometimes desyncs with M27 and AiBot playing together
                AiBotChat.SendMessage(aiBrain, 'SendGameCompatibilityWarning', 'Sorry I don’t get on well with my brother M27 when adults are around – he teases me about how much better he is and sometimes the game desyncs', 15, 15)
            end
        else
            local sMessageToSend = 'Detected'..sIncompatibleMessage .. ' (AiBot v'..import('/lua/AiBot/Version.lua').version..')'
            if sBlacklistModMessage then sMessageToSend = sIncompatibleMessage..'. It is recommended you disable incompatible mods for AiBot to function properly. AiBot v'..import('/lua/AiBot/Version.lua').version end
            AiBotChat.SendMessage(aiBrain, 'SendGameCompatibilityWarning', sMessageToSend, 0, 10)
        end
    end

    --If concern about memory give a warning
    ForkThread(CheckIfMemoryAConcern, aiBrain)

    if not(bDontPlayWithM27) and bHaveOtherAIMod and not(bHaveOtherAI) and sUnnecessaryAIMod then
        AiBotChat.SendMessage(aiBrain, 'UnnecessaryMods', 'No other AI detected, These AI mods can be disabled: '..sUnnecessaryAIMod, 1, 10)
    end
    if AiBotUtilities.bSteamActive then
        local bUsingForNormal = false
        local bUsingForEasy = false
        local sMessage
        for iBrain, oBrain in ArmyBrains do
            if oBrain.AiBotAI then
                if oBrain.AiBotEasy then
                    bUsingForEasy = true
                else
                    bUsingForNormal = true
                end
            end
        end
        if bUsingForEasy and bUsingForNormal then
            sMessage = 'AiBot active for AI: Normal and simplified AiBot for AI: Easy.'
        elseif bUsingForEasy then
            sMessage = 'AiBotEasyAI active for AI: Easy.'
        else
            sMessage = 'AiBot active for AI: Normal.'
        end
        sMessage = sMessage..' AiBot is embedded in this game patch.'
        AiBotChat.SendMessage(aiBrain, 'SteamCompatibility', sMessage, 2, 10)
    elseif AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive then
        --Probably done enough testing that can drop the warning now
        --AiBotChat.SendMessage(aiBrain, 'LOUDCompatibility', 'AiBotAI was originally developed for FAF.  It should be compatible with LOUD but less testing has been done - message maudlin27 on discord with the replay if you come across issues', 2, 10)
    end

    --Send log warning if have non-standard game options
    local tsNonStandardSettings = {}
    if not(tonumber(ScenarioInfo.Options.AiBotOvwR or tostring(0)) == 0) and ScenarioInfo.Options.AiBotOvwT then
        table.insert(tsNonStandardSettings, 'Overwhelm active, Rate='..tonumber(ScenarioInfo.Options.AiBotOvwR)..'; Time='..ScenarioInfo.Options.AiBotOvwT..'; Limit='..ScenarioInfo.Options.AiBotOvwC)
    end
    if AiBotMap.bIsCampaignMap then
        if not(ScenarioInfo.Options.CampAI == 4) then table.insert(tsNonStandardSettings, 'Campaign AiBot allies/enemies value='.. ScenarioInfo.Options.CampAI..' (1=none,2=allies,3=enemy,4=both)') end
        if not(tonumber(ScenarioInfo.Options.CmpAIDelay) == 300) then table.insert(tsNonStandardSettings, 'Campaign combat delay='..tonumber(ScenarioInfo.Options.CmpAIDelay)) end
        if ScenarioInfo.Options.CmApplyAIx == 1 then  table.insert(tsNonStandardSettings, 'Campaign is using AIx for AiBot') end
        if not(ScenarioInfo.Options.CmAiBotCampPers == 2) then table.insert(tsNonStandardSettings, 'Campaign is using custom personality '..ScenarioInfo.Options.CmAiBotCampPers..' (1=Easy, 2=Adaptive') end
    end
    if tonumber(ScenarioInfo.Options.AiBotTimeBetweenOrders) > 1 then table.insert(tsNonStandardSettings, 'Time between orders='..tonumber(ScenarioInfo.Options.AiBotTimeBetweenOrders)) end
    if not(tonumber(ScenarioInfo.Options.AiBotAggression or '1.0') == 1) then
        AiBotUnitInfo.iThreatFactor = tonumber(ScenarioInfo.Options.AiBotAggression or '1.0')
        AiBotUnitInfo.bCustomThreatFactor = true
        table.insert(tsNonStandardSettings, 'AiBot is using a custom aggression factor of '..AiBotUnitInfo.iThreatFactor)
    end
    if ScenarioInfo.Options.AiBotCPUPerformance == 1 then table.insert(tsNonStandardSettings, 'CPU performance mode active') end
    if ScenarioInfo.Options.AiBotPrioritiseBPs == 2 then table.insert(tsNonStandardSettings, 'Unit prioritisation disabled') end
    if not((ScenarioInfo.Options.AiBotDodgeMicro or 1) == 1) then table.insert(tsNonStandardSettings, 'Dodge micro limit='..tonumber(ScenarioInfo.Options.AiBotDodgeMicro)-2) end
    if not((ScenarioInfo.Options.AiBotHoverMicro or 1) == 1) then table.insert(tsNonStandardSettings, 'Hover micro limit='..tonumber(ScenarioInfo.Options.AiBotHoverMicro)-2) end
    if not(ScenarioInfo.Options.AiBotCombinedArmy == 2) then table.insert(tsNonStandardSettings, 'Combined army setting='..(ScenarioInfo.Options.AiBotCombinedArmy or 'Nil')..'; Inherit setting='..(ScenarioInfo.Options.AiBotCAInherit or 'Nil')..'; Engi setting='..(ScenarioInfo.Options.AiBotCAEngi or 'nil')) end
    if ScenarioInfo.Options.AiBotTeammate == 2 then table.insert(tsNonStandardSettings, 'Helpful teammate disabled') end
    if AiBotUtilities.IsTableEmpty(tsNonStandardSettings) == false then AiBotUtilities.ErrorHandler('Non standard settings='..reprs(tsNonStandardSettings), true) end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DelayedCampaignRestrictionsCheck()
    --Call via forked thread
    local sFunctionRef = 'DelayedCampaignRestrictionsCheck'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, bUnitRestrictionsArePresent='..tostring(bUnitRestrictionsArePresent)) end
    while not(bUnitRestrictionsArePresent) do
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(60)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        if bDebugMessages == true then LOG(sFunctionRef..': Checking at time='..GetGameTimeSeconds()..'; Is GetRestrictions empty='..tostring(AiBotUtilities.IsTableEmpty(import("/lua/game.lua").GetRestrictions()))) end
        if AiBotUtilities.IsTableEmpty(import("/lua/game.lua").GetRestrictions()) == false then bUnitRestrictionsArePresent = true break end
        if GetGameTimeSeconds() >= 600 then break end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function CheckIfMemoryAConcern(aiBrain)
    if AiBotMap.iMapSize > 512 then --larger than 10km
        WaitSeconds(1)
        if AiBotTeam.iTotalTeamCount >= 4 then
            local iTeamWithActiveAiBot = 0
            for iTeam = 1, AiBotTeam.iTotalTeamCount do
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 0 then
                    iTeamWithActiveAiBot = iTeamWithActiveAiBot + 1
                end
            end
            if iTeamWithActiveAiBot >= 4 and not(AiBotMap.bIsCampaignMap) then
                local iUnitCap = GetArmyUnitCap(aiBrain:GetArmyIndex())
                if iUnitCap > 500 then
                    AiBotChat.SendMessage(aiBrain, 'MemoryConcern', 'There is a risk the game runs out of memory with this many AiBot teams on a large map.  If the game crashes consider lowering the unit cap, the number of teams, using a smaller map, using the same faction, lowering graphics (solo), enabling CPU performance mode and AiBotEasy', 2, 10)
                end
            end
        end
    end
end

function SetPCxValuesForBrain(aiBrain)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'SetPCxValuesForBrain'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if not(AiBotConditions.IsCivilianBrain(aiBrain)) and (aiBrain.BrainType == 'Human' or (aiBrain.BrainType == 'AI' and aiBrain.Nickname and AiBotUtilities.DoesAINicknameContainAiBot(aiBrain.Nickname, false, false))) then
        local sBaseResource = 'PCxCheatMult'
        local sBaseBuild = 'PCxBuildMult'
        local iCurResource, iCurBuild
        local iCurPlayerIndex = aiBrain:GetArmyIndex()
        iCurResource = ScenarioInfo.Options[sBaseResource..iCurPlayerIndex]
        iCurBuild = ScenarioInfo.Options[sBaseBuild..iCurPlayerIndex]
        if not(iCurResource) then iCurResource = 1 else iCurResource = tonumber(iCurResource) end
        if not(iCurBuild) then iCurBuild = 1 else iCurBuild = tonumber(iCurBuild) end
        if iCurResource == 1 and iCurBuild == 1 then
            --Do nothing - default
        else
            aiBrain.CheatEnabled = true
            aiBrain.PCxModifier = true
            SetBuildAndResourceCheatModifiers(aiBrain, iCurBuild, iCurResource, true, nil, true, true, true)
            if bDebugMessages == true then LOG(sFunctionRef..': Have set resource and build values for brain '..aiBrain.Nickname..'; iCurBuild='..iCurBuild..'; iCurResource='..iCurResource) end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

local function StartOverseerManagerWhenMapIsReady(aiBrain)
    -- Do not create teams until land setup is complete.  TeamInitialisation
    -- (forked from CreateNewTeam via RecordAllPlayers, and from
    -- ActivateAdminBrainAfterTeamSetup) iterates tAllPlateaus to build the
    -- per-team land-zone data; running it early leaves those tables nil and
    -- floods GetACUOrder / RecordGroundThreatForLandZone / UpdateScoutingShortlist
    -- with 'arithmetic on nil'.  Subteam creation also needs the generated
    -- navmesh for start labels.  Water-zone team data is created separately by
    -- WaterZoneTeamInitialisation / RecordClosestAllyAndEnemyBaseForEachWaterZone,
    -- which have their own bWaterZoneInitialCreation waits, so there is no need
    -- to block on it here (doing so would also stall RecordPondToExpandTo in
    -- normal games until SetupWaterZones gives up its preferred-pond wait).
    while not(AiBotMap.bMapLandSetupComplete) do
        WaitTicks(1)
    end

    -- Teams are only created by RecordAllPlayers (forked from Initialisation,
    -- which is itself forked from OverseerManager below), so kick it off here
    -- first.  Otherwise the team wait below can never succeed on the startup
    -- path.  RecordAllPlayers is idempotent (guarded by bRecordedAllPlayers).
    ForkThread(AiBotTeam.RecordAllPlayers)

    -- Wait for the brain's team record instead of treating that short race as
    -- a permanent activation failure.  If the record never arrives (e.g. the
    -- brain was created after RecordAllPlayers already swept ArmyBrains), fall
    -- back to CreateNewTeam like Initialisation does.
    local iTeamWaitCount = 0
    while not(aiBrain.AiBotTeam)
        or not(AiBotTeam.tTeamData[aiBrain.AiBotTeam])
        or not(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) do
        WaitTicks(1)
        iTeamWaitCount = iTeamWaitCount + 1
        if iTeamWaitCount >= 10 then
            AiBotTeam.CreateNewTeam(aiBrain)
        end
    end

    -- Fill in the per-brain structures (active membership, air/land subteams)
    -- that CreateNewTeam only granted to brains already AiBot at team creation.
    local bTeamReady = AiBotTeam.ActivateAdminBrainAfterTeamSetup(aiBrain)
    if not(bTeamReady) then
        WARN('Unable to start late AiBot admin brain because subteam setup failed for '..(aiBrain.Nickname or 'unknown'))
        return
    end

    OverseerManager(aiBrain)
end

function AiBotBrainCreated(aiBrain)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AiBotBrainCreated'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    -- A human brain can only be created by the authenticated admin-hybrid
    -- path.  Keep this guard here as the final barrier for legacy callers,
    -- campaign checks, and cheat/CombinedArmy options.
    if aiBrain.BrainType == 'Human' then
        local adminPlayers = ScenarioInfo.Options and ScenarioInfo.Options.AiBotAdminPlayers
        if not(aiBrain.AiBotAdminRequested == true
            and type(adminPlayers) == 'table'
            and adminPlayers[aiBrain.Nickname] == true) then
            WARN('Rejected AiBotBrainCreated for unauthorized human brain '..tostring(aiBrain.Nickname))
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return false
        end
    end

    if bDebugMessages == true then LOG(sFunctionRef..': AiBot Brain has just been created for aiBrain '..aiBrain.Nickname..'; Index='..aiBrain:GetArmyIndex()..'; bInitialSetup='..tostring(bInitialSetup or false)..'; Is campaign AI='..tostring(aiBrain.CampaignAI or false)..'; Cheat enabled='..tostring(aiBrain.CheatEnabled or false)..'; Time='..GetGameTimeSeconds()) end

    aiBrain.AiBotAI = true
    AiBotUtilities.bAiBotAIInGame = true
    table.insert(tAllActiveAiBotBrains, aiBrain)

    --PCx mod support - AiBot loads this before PCx, so do a hardcopy here if the mod is active
    if not(aiBrain.CheatEnabled) or aiBrain.BrainType == 'Human' then
        local tSimMods = __active_mods or {}
        if AiBotUtilities.IsTableEmpty(tSimMods) == false then
            for iMod, tModData in tSimMods do
                if tModData.name == 'Player Modifier PCx' then
                    if tModData.enabled then
                        if bDebugMessages == true then LOG(sFunctionRef..': PCx mod is active so will set AIx values if relevant') end
                        SetPCxValuesForBrain(aiBrain)
                    end
                    break
                end
            end
        end
    end

    --SCFA recognition
    local tbSCTAPersonalities = {}
    tbSCTAPersonalities['aibottaarmai'] = true
    tbSCTAPersonalities['aibottacoreai'] = true
    tbSCTAPersonalities['aibottarandomai'] = true
    tbSCTAPersonalities['aibottaarmaicheat'] = true
    tbSCTAPersonalities['aibottacoreaicheat'] = true
    tbSCTAPersonalities['aibottarandomaicheat'] = true
    local sPersonality = ScenarioInfo.ArmySetup[(aiBrain.Name or 'nil')].AIPersonality
    if bDebugMessages == true then LOG(sFunctionRef..': sPersonality='..sPersonality..'; is this a tbSCTAPersonalities='..tostring(tbSCTAPersonalities[(sPersonality or 'nil')] or false)) end
    if sPersonality and tbSCTAPersonalities[sPersonality] then
        if bDebugMessages == true then LOG(sFunctionRef..': AiBotSCTA brain recognised') end
        aiBrain.AiBotSCTA = true
        if not(bSCTAPresent) then
            bSCTAPresent = true --Dont currently use this; note if want to change unit categories then do in AiBotUnitInfo not here
        end
    end

    --Set cheat mult if this is campaign (which doesnt allow in game options)
    if aiBrain.CheatEnabled and not(aiBrain.PCxModifier) then
        if AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive or aiBrain.CheatValue then
            if bDebugMessages == true then LOG(sFunctionRef..': Setting build and resource cheat modifiers based on aiBrain.CheatValue='..aiBrain.CheatValue) end
            SetBuildAndResourceCheatModifiers(aiBrain, (aiBrain.CheatValue or 1), (aiBrain.CheatValue or 1), false)
        elseif not(ScenarioInfo.Options.CheatMult) then
            if bDebugMessages == true then LOG(sFunctionRef..': No cheat mult in scenario options so will set to 1.5 for build and resource') end
            SetBuildAndResourceCheatModifiers(aiBrain, 1.5, 1.5)
        elseif aiBrain.CheatEnabled and (aiBrain.CampaignAI or AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and ScenarioInfo.Options.CmApplyAIx == 1 then
            if bDebugMessages == true then LOG(sFunctionRef..': Will apply AIx modifiers to brain '..aiBrain.Nickname) end
            SetBuildAndResourceCheatModifiers(aiBrain, tonumber(ScenarioInfo.Options.CheatMult), tonumber(ScenarioInfo.Options.BuildMult), true)
        elseif aiBrain.CheatEnabled then
            SetBuildAndResourceCheatModifiers(aiBrain, (aiBrain.CheatValue or tonumber(ScenarioInfo.Options.CheatMult) or 1), (aiBrain.CheatValue or tonumber(ScenarioInfo.Options.CheatMult) or 1), true, nil, true)
        end
    end

    --Set micro levels
    if not((ScenarioInfo.Options.AiBotDodgeMicro or 1) == 1) then
        local iDodgeMicroLimit
        if ScenarioInfo.Options.AiBotDodgeMicro == 2 then iDodgeMicroLimit = 0
        else iDodgeMicroLimit = tonumber(ScenarioInfo.Options.AiBotDodgeMicro) - 2
        end
        aiBrain[AiBotMicro.refiMaxUnitsToDodgeMicroAtOnce] = iDodgeMicroLimit
        aiBrain[AiBotMicro.refiCurUnitsDodging] = 0
    end
    if not((ScenarioInfo.Options.AiBotHoverMicro or 1) == 1) then
        if bDebugMessages == true then LOG(sFunctionRef..': ScenarioInfo.Options.AiBotHoverMicro='..(ScenarioInfo.Options.AiBotHoverMicro or 'nil')) end
        local iHoverMicroLimit
        if ScenarioInfo.Options.AiBotHoverMicro == 2 then iHoverMicroLimit = 0
        else iHoverMicroLimit = tonumber(ScenarioInfo.Options.AiBotHoverMicro) - 2
        end
        aiBrain[AiBotMicro.refiMaxUnitsToHoverMicroAtOnce] = iHoverMicroLimit
        aiBrain[AiBotMicro.refiCurUnitsHoverMicroing] = 0
    end

    --Setup AI personality for this
    AiBotChat.AssignAIPersonalityAndRating(aiBrain)

    -- On Dual Gap the slot role is more authoritative than the generic
    -- Adaptive personality. Keep the old flags unchanged on other maps.
    local dualGapProfile = AiBotDualGap.ApplyToBrainWhenReady(aiBrain)
    if dualGapProfile then
        aiBrain[refbPrioritiseLand] = dualGapProfile.prioritiseLand or false
        aiBrain[refbPrioritiseAir] = dualGapProfile.prioritiseAir or false
        aiBrain[refbPrioritiseNavy] = dualGapProfile.prioritiseNavy or false
        aiBrain[refbPrioritiseHighTech] = dualGapProfile.prioritiseHighTech or false
        LOG('AiBot Dual Gap role: army='..aiBrain:GetArmyIndex()..'; slot='..tostring(aiBrain.AiBotDualGapSlot)..'; side='..tostring(aiBrain.AiBotDualGapSide)..'; source='..tostring(aiBrain.AiBotDualGapPositionSource)..'; anchor army='..tostring(aiBrain.AiBotDualGapAnchorArmy)..'; start='..tostring(aiBrain.AiBotDualGapStartX)..','..tostring(aiBrain.AiBotDualGapStartZ)..'; role='..aiBrain.AiBotDualGapRole..'; primary='..aiBrain.AiBotDualGapPrimary..'; navy unlock='..aiBrain.AiBotDualGapNavyUnlock)
    end

    --Set easy flag
    if ScenarioInfo.ArmySetup[aiBrain.Name].AIPersonality == 'aibotaie' or ScenarioInfo.ArmySetup[aiBrain.Name].AIPersonality == 'aibotaiecheat' then
        aiBrain.AiBotEasy = true
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Finished considering if dealing with easy AI, AiBotEasy='..tostring(aiBrain.AiBotEasy or false)) end


    if not(bInitialSetup) then
        bInitialSetup = true
        local LoudCompatibility = import('/lua/AiBot/AI/LOUD/AiBotOtherLOUDCompatibility.lua')
        if not(AiBotUtilities.bFAFActive) or not(_G.reprs) then LoudCompatibility.AddReprCommands() end --If LOUD is active will have already called this
        if bDebugMessages == true then LOG(sFunctionRef..': About to do one-off setup for all brains, will also fork various threads including for overwhelm, Overwhelm rate='..tonumber(ScenarioInfo.Options.AiBotOvwR or tostring(0))..'; ScenarioInfo.Options.AiBotOvwT='..(ScenarioInfo.Options.AiBotOvwT or 'nil')..'; reprs of ScenarioInfo.Options='..reprs(ScenarioInfo.Options)) end
        AiBotUtilities.bAiBotAIInGame = true
        --Specify if performance mode enabled
        if ScenarioInfo.Options.AiBotCPUPerformance == 1 and not(AiBotUtilities.bCPUPerformanceMode) then
            AiBotUtilities.bCPUPerformanceMode = true
            AiBotUnitInfo.iLandThreatIgnoreHealthThreshold = 900
            AiBotUnitInfo.iLandThreatJustConsiderHealthThreshold = 500000
        end
        if import('/lua/AiBot/AiBotConfig.lua').AiBotRunProfiling then AiBotUtilities.ErrorHandler('Debut mode is enabled') end
        --LOG('AiBot in game 3')

        --Get the first non-human AiBotBrain
        local oChatBrain = aiBrain
        if aiBrain.BrainType == 'Human' then
            for iBrain, oBrain in ArmyBrains do
                if oBrain.AiBotAI and not(oBrain.BrainType == 'Human') then oChatBrain = oBrain break end
            end
        end

        -- A hotkey-controlled human army must activate silently. Standalone AI
        -- players retain the ordinary player-style greeting at game start.
        if not(aiBrain.BrainType == 'Human' and aiBrain.AiBotAdminRequested) then
            AiBotChat.SendMessage(oChatBrain, 'GameStartGreeting', AiBotChat.GetStartGreeting(), 0, 10000, false)
        end

        ForkThread(GameSettingWarningsChecksAndInitialChatMessages, oChatBrain)
        if bDebugMessages == true then LOG(sFunctionRef..': oChatBrain='..oChatBrain.Nickname..'; ScenarioInfo.Options.AiBotCombinedArmy='..(ScenarioInfo.Options.AiBotCombinedArmy or 'nil')..'; PerformanceMode='..tostring(AiBotUtilities.bCPUPerformanceMode)) end
        -- Hybrid activation can happen before the normal human-brain setup
        -- threads have recorded every spawn.  SetupMap needs all starts (also
        -- for players that are not bots yet), otherwise a later admin receives
        -- incomplete zone and enemy-base data.

        -- Fork navmesh generation so it doesn't block the sim thread while
        -- RecordBrainStartPoint waits for it below.  Generate() yields
        -- between phases via WaitTicks(1), keeping the sim responsive.
        if not(NavUtils.IsGenerated()) then
            ForkThread(NavUtils.Generate)
        end

        for _, oBrain in ArmyBrains do
            if not(AiBotConditions.IsCivilianBrain(oBrain)) then
                -- Admin activation can happen after the normal setup has
                -- already recorded all starts. Avoid doing the same pathing
                -- lookup a second time while the hotkey is being processed.
                if not(AiBotMap.PlayerStartPoints[oBrain:GetArmyIndex()]) then
                    AiBotMap.RecordBrainStartPoint(oBrain)
                end
                -- If admin activation is the first AiBot setup in a custom
                -- lobby, spread start-point work over ticks rather than doing
                -- every army in one simulation frame.
                if aiBrain.BrainType == 'Human' and aiBrain.AiBotAdminRequested then
                    WaitTicks(1)
                end
            end
        end
        ForkThread(AiBotMap.SetupMap)
        ForkThread(UpdateMaxUnitCapForRelevantBrains)
        ForkThread(AiBotBuilding.DetermineBuildingExpectedValues)
        ForkThread(AiBotUnitInfo.CalculateBlueprintThreatsByType) --Records air and ground threat values for every blueprint
        if not(tonumber(ScenarioInfo.Options.AiBotOvwR or tostring(0)) == 0) and ScenarioInfo.Options.AiBotOvwT then
            ForkThread(AiBotEconomy.AdjustAIxOverwhelmRate)
        end
        ForkThread(GlobalOverseer)
        ForkThread(SetAiBotActiveFlag)
        if not(tonumber(ScenarioInfo.Options.AiBotAggression or '1.0') == 1) then
            AiBotUnitInfo.iThreatFactor = tonumber(ScenarioInfo.Options.AiBotAggression or '1.0')
            AiBotUnitInfo.bCustomThreatFactor = true
        end
    end
    LOG('Calling overseer manager via a fork')
    ForkThread(StartOverseerManagerWhenMapIsReady, aiBrain)

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)

end

function SetupNoRushDetails(aiBrain)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'SetupNoRushDetails'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code') end

    if ScenarioInfo.Options.NoRushOption  and not(ScenarioInfo.Options.NoRushOption == 'Off') then
        if bDebugMessages == true then LOG(sFunctionRef..': No rush isnt active, will record details') end
        if not(bNoRushActive) then --This is the first time for any AI that this is run (redundancy)
            if bDebugMessages == true then LOG(sFunctionRef..': Log of ScenarioInfo='..repru(ScenarioInfo)) end
            bNoRushActive = true
            iNoRushTimer = tonumber(ScenarioInfo.Options.NoRushOption) * 60
            ForkThread(NoRushMonitor)
            if bDebugMessages == true then LOG(sFunctionRef..': First time have run this so ahve set bNoRushActive='..tostring(bNoRushActive)..' and started iNoRushTimer for '..iNoRushTimer..' to change norush back to false') end
        end
        --Setup details of norush range for each AiBotAI
        if bNoRushActive then
            local tMapInfo = ScenarioInfo
            aiBrain[reftNoRushCentre] = {AiBotMap.PlayerStartPoints[aiBrain:GetArmyIndex()][1], 0, AiBotMap.PlayerStartPoints[aiBrain:GetArmyIndex()][3]}
            local sXRef = 'norushoffsetX_ARMY_'..aiBrain:GetArmyIndex()
            local sZRef = 'norushoffsetY_ARMY_'..aiBrain:GetArmyIndex()
            if bDebugMessages == true then LOG(sFunctionRef..': Checking norush adjustments, sXRef='..sXRef..'; sZRef='..sZRef..'; MapInfoX='..(tMapInfo[sXRef] or 'nil')..'; MapInfoZ='..(tMapInfo[sZRef] or 'nil')..'; aiBrain[reftNoRushCentre] before adjustment='..repru(aiBrain[reftNoRushCentre])) end
            if tMapInfo[sXRef] then aiBrain[reftNoRushCentre][1] = aiBrain[reftNoRushCentre][1] + (tMapInfo[sXRef] or 0) end
            if tMapInfo[sZRef] then aiBrain[reftNoRushCentre][3] = aiBrain[reftNoRushCentre][3] + (tMapInfo[sZRef] or 0) end
            aiBrain[reftNoRushCentre][2] = GetTerrainHeight(aiBrain[reftNoRushCentre][1], aiBrain[reftNoRushCentre][3])
            iNoRushRange = tMapInfo.norushradius
            table.insert(reftNoRushAiBotStartPoints, aiBrain[reftNoRushCentre])
            if bDebugMessages == true then
                LOG(sFunctionRef..': Have recorded key norush details for the ai with index='..aiBrain:GetArmyIndex()..'; iNoRushRange='..iNoRushRange..'; aiBrain[reftNoRushCentre]='..repru(aiBrain[reftNoRushCentre])..'; will draw a circle now in white around the area')
                AiBotUtilities.DrawCircleAtTarget(aiBrain[reftNoRushCentre], 7, 500, iNoRushRange)
            end

        end
    else
        if bDebugMessages == true then LOG(sFunctionRef..': No rush isnt active') end
        bNoRushActive = false --(redundancy)
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function NoRushMonitor()
    local sFunctionRef = 'NoRushMonitor'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    WaitSeconds(iNoRushTimer)
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    bNoRushActive = false
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end


