function UpdateMaxUnitCapForRelevantBrains()
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateMaxUnitCapForRelevantBrains'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    for iBrain, oBrain in tAllAIBrainsByArmyIndex do
        if not(AiBotMap.bIsCampaignMap) or not(oBrain.BrainType == 'AI') or oBrain.AiBotAI or oBrain.M27AI then
            if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; About to update max unit cap for brian '..oBrain.Nickname..'; Brain type='..(oBrain.BrainType or 'nil')) end
            RefreshMaxUnitCap(oBrain)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RefreshMaxUnitCap(aiBrain)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RefreshUnitCap'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; About to set max unit cap for brain '..aiBrain.Nickname..'; Unit cap per scenarioInfo='..(ScenarioInfo.Options.UnitCap or 'nil')..'; Unit cap before update='..aiBrain:GetArmyStat("UnitCap_MaxCap", 0).Value) end
    if ScenarioInfo.Options.UnitCap then
        local iUnitCap = tonumber(ScenarioInfo.Options.UnitCap)
        local iIndex = aiBrain:GetArmyIndex()
        --SetIgnoreArmyUnitCap(iIndex, true) --Use this and below commented line to ignore unit cap altogther I think based on usage in base FAF code
        --aiBrain.IgnoreArmyCaps = true
        SetArmyUnitCap(iIndex, iUnitCap)
        if bDebugMessages == true then LOG(sFunctionRef..': Brian unit cap after update='..aiBrain:GetArmyStat("UnitCap_MaxCap", 0).Value) end
    else
        AiBotUtilities.ErrorHandler('No unit cap specified', true)
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end


function Initialisation(aiBrain)
    --Called after 1 tick has passed so all aibrains should hopefully exist now
    --v24 - delay as want to wait until onbeginsession has started for navmesh to generate properly
    local sFunctionRef = 'Initialisation'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    while not(bBeginSessionTriggered) and GetGameTimeSeconds() <= 4 do
        WaitTicks(1)
    end
    WaitTicks(1) --make sure brain setup will have run
    aiBrain[refbInitialised] = true
    if bDebugMessages == true then LOG('About to proceed with initialisation, aiBrain='..aiBrain.Nickname..'; bBeginSessionTriggered='..tostring(bBeginSessionTriggered or false)) end
    ForkThread(SetupNoRushDetails, aiBrain)
    ForkThread(AiBotTeam.RecordAllPlayers)
    local iWaitCount = 0
    while not(aiBrain.AiBotTeam) do
        if bDebugMessages == true then LOG(sFunctionRef..': Dont have a team assigned yet so will wait 1 tick') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitTicks(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        iWaitCount = iWaitCount + 1
        if iWaitCount >= 10 then
            AiBotUtilities.ErrorHandler('Dont have a team assigned for brain '..aiBrain.Nickname..'; will create a new team for it as a redundancy')
            AiBotTeam.CreateNewTeam(aiBrain)
        end
    end
    ForkThread(AiBotMap.CheckIfLowMexMap)
    ForkThread(AiBotEconomy.EconomyInitialisation, aiBrain)
    ForkThread(AiBotEngineer.EngineerInitialisation, aiBrain)
    ForkThread(AiBotACU.ManageACU, aiBrain)
    ForkThread(AiBotFactory.SetPriorityPreferredUnitsByCategory, aiBrain)
    ForkThread(AiBotFactory.IdleFactoryMonitor, aiBrain)
    ForkThread(AiBotMap.RecordPondToExpandTo, aiBrain)
    --ForkThread(RevealCiviliansToAI, aiBrain)
    ForkThread(RevealCivilainsToAIByGivingVision, aiBrain)
    ForkThread(RefreshMaxUnitCap, aiBrain) --This logic is  called from a number of palces to try and ensure it overrides things that might be set elsewhere
    ForkThread(DelayedCheckOfUnitsAtStartOfGame)
    ForkThread(DecideOnGeneralMapStrategy, aiBrain)
    ForkThread(AiBotChat.ConsiderPerTeamStartMessage, aiBrain)
    if bDebugMessages == true then LOG(sFunctionRef..': Finished initialisation') end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function CheckUnitCap(aiBrain)
    local sFunctionRef = 'CheckUnitCap'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if GetGameTimeSeconds() - (aiBrain[refiLastUnitCapTimeCheck] or -1) >= 0.5 then

        aiBrain[refiLastUnitCapTimeCheck] = GetGameTimeSeconds()
        --local iUnitCap = tonumber(ScenarioInfo.Options.UnitCap)
        --Use below method in case a mod has changed this
        local oArmy = aiBrain:GetArmyIndex()
        local iUnitCap = GetArmyUnitCap(oArmy)
        --local armies = ListArmies()
        --for i, army in armies do
        --end
        local iCurUnits = GetArmyUnitCostTotal(aiBrain:GetArmyIndex()) --aiBrain:GetCurrentUnits(categories.ALLUNITS - AiBotUnitInfo.refCategoryWall) + aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryWall) * 0.25
        local iCurFactories = aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFactory)
        local iThreshold = math.min(25, math.max(math.ceil(iUnitCap * 0.02), 10, iCurFactories * 0.5))
        if bUnitRestrictionsArePresent then
            if aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] < 3 then
                if aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] == 1 then iThreshold = iThreshold * 0.4
                else
                    iThreshold = iThreshold * 0.6
                end
            elseif AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiConstructedExperimentalCount] == 0 then iThreshold = iThreshold * 0.7
            end
        elseif AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiConstructedExperimentalCount] == 0 then iThreshold = iThreshold * 0.8
        end
        local iCurUnitsDestroyed = 0
        if bDebugMessages == true then LOG(sFunctionRef..': Start of code at time '..GetGameTimeSeconds()..'; iCurUnits='..iCurUnits..'; iUnitCap='..iUnitCap..'; iThreshold='..iThreshold) end
        if iCurUnits > (iUnitCap - iThreshold * 4) then --changed from *5 to *4 in v299
            aiBrain[refbCloseToUnitCap] = true
            AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiTimeLastNearUnitCap] = GetGameTimeSeconds()
            local iMaxToDestroy = math.max(5, math.ceil(iUnitCap * 0.01), math.max(20, iCurFactories) - (iUnitCap - iCurUnits))
            if iUnitCap - iCurUnits < 10 then iMaxToDestroy = math.max(10, iMaxToDestroy) end
            local bReconsiderShortly = false
            if iMaxToDestroy > 10 then
                iMaxToDestroy = 10
                bReconsiderShortly = true
            end
            local tUnitsToDestroy
            local tiCategoryToDestroy = {
                [-2] = AiBotUnitInfo.refCategoryAllAir * categories.TECH3 + AiBotUnitInfo.refCategoryStructure * categories.TECH1 + AiBotUnitInfo.refCategoryStructure * categories.TECH2 - AiBotUnitInfo.refCategoryMex - categories.EXPERIMENTAL - categories.COMMAND,
                [-1] = AiBotUnitInfo.refCategoryMobileLand + categories.NAVAL * categories.MOBILE - categories.EXPERIMENTAL - categories.COMMAND - categories.SUBCOMMANDER,
                [0] = categories.TECH1 - categories.COMMAND - AiBotUnitInfo.refCategoryAirStaging - AiBotUnitInfo.refCategoryT1Mex + AiBotUnitInfo.refCategoryAllAir * categories.TECH2 - AiBotUnitInfo.refCategoryTransport * categories.TECH2 - AiBotUnitInfo.refCategoryTorpBomber * categories.TECH2 -AiBotUnitInfo.refCategoryAllHQFactories + categories.TECH2 * AiBotUnitInfo.refCategoryMobileLandShield - categories.INSIGNIFICANTUNIT,
                [1] = AiBotUnitInfo.refCategoryAllAir * categories.TECH1 + categories.NAVAL * categories.MOBILE * categories.TECH1 - categories.INSIGNIFICANTUNIT,
                [2] = AiBotUnitInfo.refCategoryMobileLand * categories.TECH2 - categories.COMMAND - AiBotUnitInfo.refCategoryMobileLandShield - AiBotUnitInfo.refCategoryMAA + AiBotUnitInfo.refCategoryAirScout * categories.TECH1 + AiBotUnitInfo.refCategoryAirAA * categories.TECH1 - categories.INSIGNIFICANTUNIT,
                [3] = AiBotUnitInfo.refCategoryMobileLand * categories.TECH1 - categories.COMMAND - categories.INSIGNIFICANTUNIT,
                [4] = AiBotUnitInfo.refCategoryWall + AiBotUnitInfo.refCategoryEngineer - categories.TECH3 + AiBotUnitInfo.refCategoryMobileLand * categories.TECH1 - categories.COMMAND - AiBotUnitInfo.refCategoryLandScout - categories.INSIGNIFICANTUNIT,
            }
            --Adjust these categories for special cases
            if AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] == 1 and (AiBotMap.bIsCampaignMap or bUnitRestrictionsArePresent) then
                --exclude T1 land from category 4
                tiCategoryToDestroy[4] =  AiBotUnitInfo.refCategoryWall + AiBotUnitInfo.refCategoryEngineer - categories.TECH3 - categories.INSIGNIFICANTUNIT
            end
            if AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] < 3 or ((AiBotMap.bIsCampaignMap or bUnitRestrictionsArePresent) and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryEngineer * categories.TECH3) == 0) then
                if AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 1 then
                    tiCategoryToDestroy[4] = tiCategoryToDestroy[4] - AiBotUnitInfo.refCategoryEngineer
                else
                    tiCategoryToDestroy[4] = tiCategoryToDestroy[4] - AiBotUnitInfo.refCategoryEngineer * categories.TECH2
                end
            end
            if AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] == 2 and (AiBotMap.bIsCampaignMap or bUnitRestrictionsArePresent) and aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand] then
                --Exclude MML from category 2
                tiCategoryToDestroy[2] = AiBotUnitInfo.refCategoryMobileLand * categories.TECH2 - categories.COMMAND - AiBotUnitInfo.refCategoryMAA -AiBotUnitInfo.refCategoryMML + AiBotUnitInfo.refCategoryAirScout + AiBotUnitInfo.refCategoryAirAA * categories.TECH1 - categories.INSIGNIFICANTUNIT
            end
            --If have no T2+ power, then dont include T1 power in units to ctrlK (unless unit restrictions and ACU has RAS)
            if aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryPower - categories.TECH1) == 0 then
                if bUnitRestrictionsArePresent and aiBrain[AiBotEconomy.refiNetEnergyBaseIncome] >= 50 and AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiConstructedExperimentalCount] == 0 and AiBotUnitInfo.IsUnitValid(aiBrain[AiBotACU.refoPrimaryACU]) and (aiBrain[AiBotACU.refoPrimaryACU]:HasEnhancement('ResourceAllocation') or aiBrain[AiBotACU.refoPrimaryACU]:HasEnhancement('ResourceAllocationAdvanced')) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will still consider ctrlking t1 power as we have RAS on ACU') end
                else
                    tiCategoryToDestroy[3] = tiCategoryToDestroy[3] - AiBotUnitInfo.refCategoryPower
                end
            end

            --If have no asfs then exclude inties from cat 2
            if bDebugMessages == true then LOG(sFunctionRef..': Cur T2+ power='..aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryPower - categories.TECH1)..'; Cur ASFs='..aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirAA * categories.TECH3)) end
            if aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirAA * categories.TECH3) == 0 then
                tiCategoryToDestroy[2] = tiCategoryToDestroy[2] - AiBotUnitInfo.refCategoryAirAA
                tiCategoryToDestroy[1] = tiCategoryToDestroy[1] - AiBotUnitInfo.refCategoryAirAA
                if bDebugMessages == true then LOG(sFunctionRef..': Excluding inties from being ctrlkd from category 1 and 2') end
                if iUnitCap >= 500 and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirAA) <= 50 then
                    tiCategoryToDestroy[0] = tiCategoryToDestroy[1] - AiBotUnitInfo.refCategoryAirAA
                end
            end

            --If exp count is 0 then remove cat -1
            if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to include factories in the -2 category to destroy, Exp count='..AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiConstructedExperimentalCount]..'; Lowest unit cap adj level='..(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 'nil')..'; Mass%='..aiBrain:GetEconomyStoredRatio('MASS')..'; Energy%='..aiBrain:GetEconomyStoredRatio('ENERGY')..'; Cur land facs='..aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryLandFactory)..'; Current air facs='..aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirFactory)) end
            if AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiConstructedExperimentalCount] == 0 then
                --Include t3 land facs in cat-2 if too many of them (if likely overflowing)
                if (AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) < 0 and aiBrain:GetEconomyStoredRatio('MASS') >= 0.95 and aiBrain:GetEconomyStoredRatio('ENERGY') >= 0.99 then
                    local iCurLandFac = aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryLandFactory)
                    if AiBotUtilities.bLoudModActive then iCurLandFac = iCurLandFac * 3 end --Unit cap for loud is adjusted for different units
                    local iCurAirFac = aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirFactory)
                    if AiBotUtilities.bLoudModActive then iCurAirFac = iCurAirFac * 3 end --Unit cap for loud is adjusted for different units
                    if bDebugMessages == true then LOG(sFunctionRef..': No Exp built yet, iCurLandFac='..iCurLandFac..'; iCurAirFac='..iCurAirFac) end
                    if iCurLandFac >= 30 then
                        tiCategoryToDestroy[-2] = tiCategoryToDestroy[-2] + AiBotUnitInfo.refCategoryLandFactory
                        if bDebugMessages == true then LOG(sFunctionRef..': No exp but Including land factories in category to destroy') end
                    end
                    if iCurAirFac >= 40 then
                        tiCategoryToDestroy[-2] = tiCategoryToDestroy[-2] + AiBotUnitInfo.refCategoryAirFactory
                        if bDebugMessages == true then LOG(sFunctionRef..': No exp but Including air factories in category to destroy') end
                    end
                end
            else
                --If we have <35 T3 engis then exclude T3 engineers from cat -1
                if (AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) <= 0 then
                    if aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryEngineer) < iT3EngineerUnitCapThresholdCount then
                        tiCategoryToDestroy[-1] = tiCategoryToDestroy[-1] - AiBotUnitInfo.refCategoryEngineer * categories.TECH3
                    end
                end
                --Include T3 land factories if we have too many of them
                if (AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) < 0 then
                    if aiBrain:GetEconomyStoredRatio('MASS') >= 0.5 and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryLandFactory) >= 16 then
                        tiCategoryToDestroy[-2] = tiCategoryToDestroy[-2] + AiBotUnitInfo.refCategoryLandFactory
                        if bDebugMessages == true then LOG(sFunctionRef..': Including land factories in category to destroy') end
                    end
                    if aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirFactory) >= 20 then
                        tiCategoryToDestroy[-2] = tiCategoryToDestroy[-2] + AiBotUnitInfo.refCategoryAirFactory
                        if bDebugMessages == true then LOG(sFunctionRef..': Including air factories in category to destroy') end
                    end
                end
            end


            if (AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) <= 2 then
                --If have no t3 gunships then keep t2 in cat 0
                if aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryGunship * categories.TECH3) == 0 then
                    tiCategoryToDestroy[0] = tiCategoryToDestroy[0] - AiBotUnitInfo.refCategoryGunship
                end
                --Dont exclude T2 tanks if we have no t3 tanks
                if aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMobileLand * categories.TECH3) == 0 then
                    tiCategoryToDestroy[2] = AiBotUnitInfo.refCategoryMobileLand * categories.TECH1 - categories.COMMAND
                    if aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryGunship) > 0 then
                        tiCategoryToDestroy[2] = AiBotUnitInfo.refCategoryMobileLand * categories.TECH1 - categories.COMMAND + AiBotUnitInfo.refCategoryBomber * categories.TECH1
                    end
                else
                    --exclude t2 maa if we have t3 maa
                    if aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMAA * categories.TECH3) > 0 then
                        tiCategoryToDestroy[0] = tiCategoryToDestroy[0] + AiBotUnitInfo.refCategoryMAA * categories.TECH2
                    end
                end
                if (AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) <= -2 then
                    --Exclude SACUs unless we have lots (and in LOUD never exclude as loud has them increase unit cap)
                    if AiBotUtilities.bLoudModActive or aiBrain:GetCurrentUnits(categories.SUBCOMMANDER) < 20 then
                        tiCategoryToDestroy[-2] = tiCategoryToDestroy[-2] - categories.SUBCOMMANDER
                    end
                    if iCurUnits >= iUnitCap - 3 then
                        --Include mexes if we have lots of mexes (more than 30% of cur units and cur units exceed unit cap)
                        local iMaxMexes = iUnitCap * 0.35 * AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiActiveAiBotBrainCount]
                        local iCurMexes
                        if AiBotUtilities.bLoudModActive then
                            --Approximation as LOUD has wierd unit cap settings
                            iCurMexes = AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiMexCountByTech][3] * 3 + AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiMexCountByTech][2] * 2 + AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiMexCountByTech][1]
                        else
                            iCurMexes = AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiMexCountByTech][3]  + AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiMexCountByTech][2] + AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiMexCountByTech][1]
                        end

                        if bDebugMessages == true then LOG(sFunctionRef..': At adjustment -2 level or worse, T3 mex count='..AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiMexCountByTech][3]..'; iCurMexes='..iCurMexes..'; iMaxMexes='..iMaxMexes) end
                        if aiBrain:GetEconomyStoredRatio('MASS') >= 0.7 then iMaxMexes = iMaxMexes * (1.3 - aiBrain:GetEconomyStoredRatio('MASS')) end
                        if iCurMexes > iMaxMexes then
                            if iCurUnits >= iUnitCap then
                                tiCategoryToDestroy[-2] = tiCategoryToDestroy[-2] + AiBotUnitInfo.refCategoryMex
                                if bDebugMessages == true then LOG(sFunctionRef..': Including all mexes') end
                            elseif iCurUnits >= iUnitCap - 1 then
                                tiCategoryToDestroy[-2] = tiCategoryToDestroy[-2] + AiBotUnitInfo.refCategoryT2Mex + AiBotUnitInfo.refCategoryT1Mex
                                if bDebugMessages == true then LOG(sFunctionRef..': Including t1-t2 mexes only') end
                            else
                                tiCategoryToDestroy[-2] = tiCategoryToDestroy[-2] + AiBotUnitInfo.refCategoryT1Mex
                                if bDebugMessages == true then LOG(sFunctionRef..': Including t1 mexes only') end
                            end
                        end
                    end

                end
            end

            --Restrict T3 land combat units being built if we have experimental level units and are at the lowest level of unit cap
            if (AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) <= 0 and AiBotConditions.GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryExperimentalLevel) > 0 and aiBrain:GetCurrentUnits(tiCategoryToDestroy[0]) <= 10 and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryLandCombat * categories.TECH3 - categories.SUBCOMMANDER) >= 20 then
                tiCategoryToDestroy[0] = tiCategoryToDestroy[0] + AiBotUnitInfo.refCategoryLandCombat * categories.TECH3 - categories.SUBCOMMANDER
            end



            if bDebugMessages == true then LOG(sFunctionRef..': We are over the threshold for ctrlking units') end
            if aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryEngineer) > math.max(30, iUnitCap * 0.35) then tiCategoryToDestroy[0] = tiCategoryToDestroy[0] + AiBotUnitInfo.refCategoryEngineer end
            local iCumulativeCategory = tiCategoryToDestroy[4]
            local bKilledUnit = false
            for iAdjustmentLevel = 4, -2, -1 do
                if iAdjustmentLevel < 4 then
                    iCumulativeCategory = iCumulativeCategory + tiCategoryToDestroy[iAdjustmentLevel]
                end
                if bDebugMessages == true then LOG(sFunctionRef..': iCurUnitsDestroyed so far='..iCurUnitsDestroyed..'; iMaxToDestroy='..iMaxToDestroy..'; iAdjustmentLevel='..iAdjustmentLevel..'; iCurUnits='..iCurUnits..'; Unit cap='..iUnitCap..'; iThreshold='..iThreshold) end
                if tiCategoryToDestroy[iAdjustmentLevel] then
                    if iCurUnits > (iUnitCap - iThreshold * math.min(0.5, iAdjustmentLevel)) or iCurUnitsDestroyed == 0 then
                        tUnitsToDestroy = aiBrain:GetListOfUnits(tiCategoryToDestroy[iAdjustmentLevel], false, false)
                        if AiBotUtilities.IsTableEmpty(tUnitsToDestroy) == false then
                            AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] = math.min((AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100), iAdjustmentLevel)
                            if iAdjustmentLevel <= 1 then AiBotEngineer.tiActionCategory.refActionBuildAA = AiBotUnitInfo.refCategoryStructureAA end --allow experimental AA when close to unit cap
                            --Clear any prioritisation of bombers if we have penetration bombers, and instead prioritise penetration bombers
                            if categories.saa0314 and categories.saa0313 then
                                --We have penetration fighters - prioritise these over normal figheters and bombers
                                if (aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['saa0314'] or 0) <= 0 or (aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['saa0313'] or 0) <= 0 then
                                    --Penetration bombers
                                    aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['saa0314'] = 1
                                    aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['sea0314'] = 1
                                    aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['sra0314'] = 1
                                    aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['ssa0314'] = 1
                                    --Penetration fighters
                                    aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['saa0313'] = 1
                                    aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['sea0313'] = 1
                                    aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['sra0313'] = 1
                                    aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['ssa0313'] = 1
                                    --Normal bombers
                                    if (aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['uea0304'] or 0) > 0 then aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['uea0304'] = nil end
                                    if (aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['ura0304'] or 0) > 0 then aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['ura0304'] = nil end
                                    if (aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['uaa0304'] or 0) > 0 then aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['uaa0304'] = nil end
                                    if (aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['xsa0304'] or 0) > 0 then aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['xsa0304'] = nil end
                                    --Normal asfs
                                    if (aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['uea0303'] or 0) > 0 then aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['uea0303'] = nil end
                                    if (aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['ura0303'] or 0) > 0 then aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['ura0303'] = nil end
                                    if (aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['uaa0303'] or 0) > 0 then aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['uaa0303'] = nil end
                                    if (aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['xsa0303'] or 0) > 0 then aiBrain[AiBotFactory.reftBlueprintPriorityOverride]['xsa0303'] = nil end
                                end
                            end
                            --If we have a paragon, then consider transferring units to a teammate that hasnt suffered any issues under unit cap
                            if aiBrain[AiBotEconomy.refbBuiltParagon] and AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 1 and iAdjustmentLevel <= 1 then
                                local toBrainsWithBetterUnitCap = {}
                                local iBrainsToTransfer = 0
                                for iBrain, oBrain in AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                                    if not(oBrain[refiTimeOfLastUnitCapDeath]) then
                                        table.insert(toBrainsWithBetterUnitCap, oBrain)
                                        iBrainsToTransfer = iBrainsToTransfer + 1
                                    end
                                end
                                if iBrainsToTransfer > 0 then
                                    local toUnitsToTransferByBrainRef = {}
                                    local iCurBrainRef = 1
                                    for iUnit, oUnit in tUnitsToDestroy do
                                        if oUnit.Kill and (not(oUnit[AiBotUnitInfo.refbCampaignTriggerAdded]) or not(AiBotMap.bIsCampaignMap)) and not(oUnit.Parent) then
                                            if not(toUnitsToTransferByBrainRef[iCurBrainRef]) then toUnitsToTransferByBrainRef[iCurBrainRef] = {} end
                                            table.insert(toUnitsToTransferByBrainRef[iCurBrainRef], oUnit)
                                            iCurBrainRef = iCurBrainRef + 1
                                            if iCurBrainRef > iBrainsToTransfer then iCurBrainRef = 1 end
                                        end
                                    end
                                    if AiBotUtilities.IsTableEmpty( toUnitsToTransferByBrainRef) == false then
                                        for iBrainRef, tUnitsToTransfer in toUnitsToTransferByBrainRef do
                                            AiBotTeam.TransferUnitsToPlayer(tUnitsToTransfer, toBrainsWithBetterUnitCap[iBrainRef]:GetArmyIndex(), false)
                                        end
                                    end
                                    tUnitsToDestroy = {}
                                    aiBrain[refiTimeOfLastUnitCapDeath] = GetGameTimeSeconds() --Still record this to be safe so we dont transfer back for some reason and get in a cycle
                                end
                            end
                            if AiBotUtilities.IsTableEmpty(tUnitsToDestroy) == false then
                                local bKillUnit
                                --For walls, enable ctrlk if we have control of player ACU, as walls may have been gifted to player at start of game
                                if aiBrain.BrainType == 'Human' and AiBotMap.bIsCampaignMap and aiBrain[AiBotACU.refoPrimaryACU].AiBotActive then
                                    local toWallsToCtrlk = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryWall, tUnitsToDestroy)
                                    if AiBotUtilities.IsTableEmpty(toWallsToCtrlk) == false then
                                        for  iWall, oWall in toWallsToCtrlk do
                                            oWall.AiBotActive = true
                                        end
                                    end
                                end
                                for iUnit, oUnit in tUnitsToDestroy do
                                    if oUnit.Kill and (not(oUnit[AiBotUnitInfo.refbCampaignTriggerAdded]) or not(AiBotMap.bIsCampaignMap)) and not(oUnit.Parent) then
                                        --Dont kill an engineer that is building, reclaiming, repairing or capturing (unless it is building/repairing and not ap rimary engineer
                                        bKillUnit = true
                                        if EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oUnit.UnitId) then
                                            if  oUnit:IsUnitState('Reclaiming') or oUnit:IsUnitState('Capturing') then
                                                bKillUnit = false
                                            elseif oUnit[AiBotEngineer.refbPrimaryBuilder] and (oUnit:IsUnitState('Building') or oUnit:IsUnitState('Repairing')) then
                                                bKillUnit = false
                                            elseif AiBotUtilities.IsTableEmpty(oUnit[AiBotBuilding.reftArtiTemplateRefs]) == false and not(AiBotMap.tAllPlateaus[oUnit[AiBotBuilding.reftArtiTemplateRefs][1]][AiBotMap.subrefPlateauLandZones][oUnit[AiBotBuilding.reftArtiTemplateRefs][2]][AiBotMap.subrefLZTeamData][oUnit:GetAIBrain().AiBotTeam][AiBotMap.reftActiveGameEnderTemplates][oUnit[AiBotBuilding.reftArtiTemplateRefs][3]][AiBotMap.subrefGEbDontNeedEngineers]) then
                                                bKillUnit = false
                                            end
                                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryFactory, oUnit.UnitId) then
                                            if oUnit[AiBotFactory.refbPrimaryFactoryForIslandOrPond] or ((oUnit[AiBotACU.refiUpgradeCount] or 0) > 0 and ((AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) > -2 or iCurUnits > iUnitCap + 5)) then bKillUnit = false end
                                            if bDebugMessages == true then LOG(sFunctionRef..': Considering destroying a factory '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..', is this a primary factory='..tostring(oUnit[AiBotFactory.refbPrimaryFactoryForIslandOrPond] or false)..'; Number of factories on team='..AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryLandFactory + AiBotUnitInfo.refCategoryAirFactory, aiBrain.AiBotTeam)..'; bKillUnit='..tostring(bKillUnit)) end
                                        end
                                        if bKillUnit then
                                            if bDebugMessages == true then LOG(sFunctionRef..': iCurUnitsDestroyed so far='..iCurUnitsDestroyed..'; Will destroy unit '..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..' to avoid going over unit cap'..'; Have we already tried to kill this unit? oUnit[AiBotUnitInfo.refbTriedToKill]='..tostring(oUnit[AiBotUnitInfo.refbTriedToKill] or false)..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))) end
                                            if not(oUnit[AiBotUnitInfo.refbTriedToKill]) then
                                                if EntityCategoryContains(AiBotUnitInfo.refCategoryWall, oUnit.UnitId) then
                                                    iCurUnitsDestroyed = iCurUnitsDestroyed + 0.25
                                                else
                                                    iCurUnitsDestroyed = iCurUnitsDestroyed + 1
                                                end
                                            end
                                            oUnit[AiBotUnitInfo.refbTriedToKill] = true --set here as well, since otherwise we wont move on to try and ctrlk other units later

                                            AiBotOrders.IssueTrackedKillUnit(oUnit)
                                            bKilledUnit = true

                                            if iCurUnitsDestroyed >= iMaxToDestroy then
                                                if iAdjustmentLevel <= 3 and not(AiBotMap.bIsCampaignMap) and aiBrain.BrainType == 'AI' then
                                                    AiBotChat.SendUnitCapMessage(aiBrain)
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': Destroyed max wanted so aborting loop of tUnitsToDestroy') end
                                                break
                                            end
                                        end
                                    end
                                end
                            end
                        end
                        if iCurUnitsDestroyed >= iMaxToDestroy then
                            if bDebugMessages == true then LOG(sFunctionRef..': Destroyed max wanted so aborting loop of categories') end
                            break
                        end
                    else
                        if bDebugMessages == true then LOG(sFunctionRef..': Destroyed enough so wont proceed with searching for this adjustment level, iCurUnits='..iCurUnits..'; iUnitCap='..iUnitCap..'; iThreshold='..iThreshold..'; iAdjustmentLevel='..iAdjustmentLevel..'; iCurUnitsDestroyed='..iCurUnitsDestroyed) end
                        break
                    end
                end
            end
            if bKilledUnit then aiBrain[refiTimeOfLastUnitCapDeath] = GetGameTimeSeconds() end
            aiBrain[refiUnitCapCategoriesDestroyed] = iCumulativeCategory
            if bDebugMessages == true then LOG(sFunctionRef..': FInished destroying units, iCurUnitsDestroyed='..iCurUnitsDestroyed) end
            if iCurUnitsDestroyed >= iMaxToDestroy and bReconsiderShortly then
                if bDebugMessages == true then LOG(sFunctionRef..': We wanted to destroy more units, so will reassess in 10 seconds') end
                ForkThread(DelayedUnitCapCheck, aiBrain, 10)
            end
        else
            --Only reset cap if we havent reached the higher ctrlk thresholds, unless we have a massive amount of headroom
            if aiBrain[refbCloseToUnitCap] and (iCurUnits < iUnitCap * 0.5 - 25 or (AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) > 1) then
                --Only reset cap if we have a bit of leeway
                if iCurUnits < (iUnitCap - iThreshold * 5) - 20 then
                    aiBrain[refbCloseToUnitCap] = false
                    --If none of the brains on the team are close to unit cap then increase adjustmentlevel if it is very low
                    if (AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) < 1 then
                        local bHaveABrainCloseToUnitCap = false
                        for iBrain, oBrain in AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                            if oBrain[refbCloseToUnitCap] then
                                bHaveABrainCloseToUnitCap = true
                                break
                            end
                        end
                        if not(bHaveABrainCloseToUnitCap) then
                            AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] = math.max(0, math.min((AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 3) + 2, 1))
                        end
                    end
                end
            end
        end
        aiBrain[refiExpectedRemainingCap] = iUnitCap - iCurUnits + iCurUnitsDestroyed
        if aiBrain[refbCloseToUnitCap] and aiBrain[refiExpectedRemainingCap] <= 25 then
            --Recheck in 30s
            ForkThread(DelayedUnitCapCheck, aiBrain)
        end
        if bDebugMessages == true then LOG(sFunctionRef..': End of code, expected remaining cap='..aiBrain[refiExpectedRemainingCap]) end
    else
        ForkThread(DelayedUnitCapCheck, aiBrain)
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DelayedUnitCapCheck(aiBrain, iOptionalSecondsToWait)
    if not(aiBrain[refbWillDoDelayedUnitCapCheck]) then
        aiBrain[refbWillDoDelayedUnitCapCheck] = true
        WaitSeconds(iOptionalSecondsToWait or 30)
        aiBrain[refbWillDoDelayedUnitCapCheck] = false
        CheckUnitCap(aiBrain)
    end
end

function ResetCivilianAllianceForBrain(iOurIndex, iCivilianIndex, sRealState, oCivilianBrain)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ResetCivilianAllianceForBrain'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --Call via forkthread
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, Time='..GetGameTimeSeconds()..'; iOurIndex='..iOurIndex..'; iCivilianIndex='..iCivilianIndex..'; Is ally='..tostring(IsAlly(iOurIndex, iCivilianIndex))..'; IsEnemy='..tostring(IsEnemy(iOurIndex, iCivilianIndex))) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    WaitTicks(11)
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': Finished waiting for some ticks, iOurIndex='..iOurIndex..'; iCivilianIndex='..iCivilianIndex..'; Is ally='..tostring(IsAlly(iOurIndex, iCivilianIndex))..'; IsEnemy='..tostring(IsEnemy(iOurIndex, iCivilianIndex))) end
    SetAlliance(iOurIndex, iCivilianIndex, sRealState)
    oCivilianBrain[refiTemporarilySetAsAllyForTeam] = nil
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    if bDebugMessages == true then LOG(sFunctionRef..': Have now set alliance back to real state, Time='..GetGameTimeSeconds()..' Have just set civilian brain '..oCivilianBrain.Nickname..' back to being '..sRealState..' for iOurIndex='..iOurIndex) end
end

function RevealCiviliansToAI(aiBrain)
    --On some maps like burial mounds civilians are revealed to human players but not AI; meanwhile on other maps even if theyre not revealed to humans, the humans will likely know where the buildings are having played the map before
    --Thanks to Relent0r for providing code that I used as a starting point to achieve this

    --SUPERCEDED BY RevealCivilainsToAIByGivingVision
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RevealCiviliansToAI'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    AiBotUtilities.ErrorHandler('Deprecated function')
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    WaitTicks(75) --Waiting only 5 ticks or less resulted in a strange bug where on one map when ahd 2 ACUs on the same team, the code would run for both of htem as expected, but the civilians would only be visible for one of the AI (as though making the civilian an ally had no effect for hte other); This went away when put a delay of 50 ticks; however have compatibility issues with RNG so want to wait a bit longer; waiting 60 meant it worked for M27 but didnt look like it worked for RNG (wiating 50 meant it worked for RNG but not for M27); waiting 70 meant it worked for both; have done 75 for AiBot given M27 uses 70
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    --if aiBrain:GetArmyIndex() == 3 then
    if bDebugMessages == true then LOG(sFunctionRef..': Have finished waiting, will loop throguh all brians now to look for civilians, aiBrain='..aiBrain.Nickname..' with index ='..aiBrain:GetArmyIndex()..'; AiBot team='..(aiBrain.AiBotTeam or 'nil')) end
    local tiCivilianBrains = {}
    local toCivilianBrains = {}
    local iOurIndex = aiBrain:GetArmyIndex()
    local iBrainIndex
    local sRealState
    local iTotalWait = 0

    for i, oBrain in ArmyBrains do
        iBrainIndex = oBrain:GetArmyIndex()
        if bDebugMessages == true then LOG(sFunctionRef..': Considering brain '..(oBrain.Nickname or 'nil')..' with index '..oBrain:GetArmyIndex()..' for aiBrain '..aiBrain.Nickname..'; Is enemy='..tostring(IsEnemy(iOurIndex, iBrainIndex))..'; ArmyIsCivilian(iBrainIndex)='..tostring(ArmyIsCivilian(iBrainIndex))..'; oBrain[refiTemporarilySetAsAllyForTeam]='..(oBrain[refiTemporarilySetAsAllyForTeam] or 'nil')..'; Our team='..aiBrain.AiBotTeam) end
        if ArmyIsCivilian(iBrainIndex) then
            while(oBrain[refiTemporarilySetAsAllyForTeam] and not(oBrain[refiTemporarilySetAsAllyForTeam] == aiBrain.AiBotTeam)) do
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitTicks(1)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                iTotalWait = iTotalWait + 1
                if iTotalWait >= 12 then
                    break
                end
            end
            if not(oBrain[refiTemporarilySetAsAllyForTeam]) then
                oBrain[refiTemporarilySetAsAllyForTeam] = aiBrain.AiBotTeam
                sRealState = IsAlly(iOurIndex, iBrainIndex) and 'Ally' or IsEnemy(iOurIndex, iBrainIndex) and 'Enemy' or 'Neutral'
                SetAlliance(iOurIndex, iBrainIndex, 'Ally')
                if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; Temporarily set the brain as an ally of team '..aiBrain.AiBotTeam..', sRealState='..sRealState) end
                table.insert(tiCivilianBrains, iBrainIndex)
                table.insert(toCivilianBrains, oBrain)
                --Prevent orders being given to these untis by AiBot
                --[[local tMobileUnits = oBrain:GetListOfUnits(categories.MOBILE, false, true)
                if AiBotUtilities.IsTableEmpty(tMobileUnits) == false then
                    for iUnit, oUnit in tMobileUnits do
                        AiBotMicro.TrackTemporaryUnitMicro(oUnit, 30)
                    end
                end--]]
                ForkThread(ResetCivilianAllianceForBrain, iOurIndex, iBrainIndex, sRealState, oBrain)
            elseif oBrain[refiTemporarilySetAsAllyForTeam] == aiBrain.AiBotTeam then
                table.insert(tiCivilianBrains, iBrainIndex)
                table.insert(toCivilianBrains, oBrain)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    WaitTicks(8) --When did with just 4 tick delay had issues where getunitsaroundpoint didnt work properly; increasing to 8 tick solved this
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RevealCivilainsToAIByGivingVision(aiBrain)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RevealCivilainsToAIByGivingVision'
    --First wait a couple of seconds to give a chance for units to be created
    local bHaveHumanTeammate = false
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains]) == false then
        for iBrain, oBrain in AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains] do
            if oBrain.BrainType == 'Human' then
                bHaveHumanTeammate = true
            end
        end
    end
    if GetGameTimeSeconds() <= 4.4 and not(bHaveHumanTeammate) then
        --Delay time to wait if we have human teammates
        local iTimeToWait = math.min(3, 4.4 - GetGameTimeSeconds())
        WaitSeconds(iTimeToWait)
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': About to reveal civilains and then consider capture targets if this is AiBotBrain, aiBrain.AiBotAI='..tostring(aiBrain.AiBotAI or false)..'; nickname='..(aiBrain.Nickname or 'nil')) end
    if aiBrain.AiBotAI then --redundancy
        local tACU = aiBrain:GetListOfUnits(categories.COMMAND, false, true)
        local iTempVisionOverride
        if bHaveHumanTeammate then iTempVisionOverride = 0.6 end
        -- Revealing the entire map briefly is invisible to a normal AI, but it
        -- causes a distracting fog-of-war flash for a human admin army.
        if not(aiBrain.BrainType == 'Human' and aiBrain.AiBotAdminRequested) then
            for iUnit, oUnit in tACU do
                AiBotUnitInfo.GiveUnitTemporaryVision(oUnit, 10000, iTempVisionOverride)
                break
            end
        end
        --Consider capture targets
        if bDebugMessages == true then LOG(sFunctionRef..': Will now consider capture targets') end
        ForkThread(GetCivilianCaptureTargets, aiBrain)

    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetCivilianCaptureTargets(aiBrain)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetCivilianCaptureTargets'

    WaitTicks(2) --tried 1 tick but not working for civilian mexes
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local tStartPoint = AiBotMap.PlayerStartPoints[aiBrain:GetArmyIndex()]
    local iPlateauWanted, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tStartPoint)
    local iClosestEnemyBase = AiBotMap.iMapSize
    local iTeam = aiBrain.AiBotTeam

    if iLandZone > 0 then
        local tLZData = AiBotMap.tAllPlateaus[iPlateauWanted][AiBotMap.subrefPlateauLandZones][iLandZone]
        local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
        iClosestEnemyBase = AiBotUtilities.GetDistanceBetweenPositions(tStartPoint, tLZTeamData[AiBotMap.reftClosestEnemyBase])
    end
    local iSearchRange = math.min(450, math.max(iClosestEnemyBase * 0.6, 200, math.min(275, iClosestEnemyBase * 0.75)))
    local iCategoriesOfInterest = AiBotUnitInfo.refCategoryLandCombat * categories.RECLAIMABLE - categories.TECH1
    local tUnitsOfInterest = aiBrain:GetUnitsAroundPoint(iCategoriesOfInterest, tStartPoint, iSearchRange, 'Neutral')
    if not(tUnitsOfInterest) then tUnitsOfInterest = {} end
    local tNeutralMexes = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryMex + AiBotUnitInfo.refCategoryHydro, tStartPoint, 10000, 'Neutral')
    if AiBotUtilities.IsTableEmpty(tNeutralMexes) == false then
        for iMex, oMex in tNeutralMexes do
            table.insert(tUnitsOfInterest, oMex)
        end
    end

    local iMaxPowerSearchRange = math.min(250, iClosestEnemyBase * 0.225)
    local tNearbyPower = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryPower, tStartPoint, iMaxPowerSearchRange, 'Neutral')
    if AiBotUtilities.IsTableEmpty(tNearbyPower) == false then
        for iPower, oPower in tNearbyPower do
            table.insert(tUnitsOfInterest, oPower)
        end
    end

    --Include much closer civilian units of all categories that are in the same plateau, and havent already been recorded
    local bSearchForLowerPriority = not(AiBotUtilities.IsTableEmpty(tUnitsOfInterest))
    local tVeryCloseUnits = aiBrain:GetUnitsAroundPoint(categories.RECLAIMABLE - AiBotUnitInfo.refCategoryAllAir, tStartPoint, math.min(iMaxPowerSearchRange, iSearchRange, iClosestEnemyBase * 0.2, AiBotMap.iMapSize * 0.25, 125), 'Neutral')
    if AiBotUtilities.IsTableEmpty(tVeryCloseUnits) == false then
        local sPathing = AiBotMap.refPathingTypeHover
        local bDoPathingCheck = not(AiBotMap.bIsLowMexMap)
        local bCheckExistingEntries = false
        local tOrigUnits
        if AiBotUtilities.IsTableEmpty(tUnitsOfInterest) == false then
            bCheckExistingEntries = true
            tOrigUnits = {}
            for iUnit, oUnit in tUnitsOfInterest do
                table.insert(tOrigUnits, oUnit)
            end
        end
        local bRecordUnit
        for iUnit, oUnit in tVeryCloseUnits do
            bRecordUnit = true
            if bCheckExistingEntries then
                for iRecorded, oRecorded in tOrigUnits do
                    if oRecorded == oUnit then bRecordUnit = false break end
                end
            end
            if bRecordUnit then
                --Check we are in the same plateau
                if not(bDoPathingCheck) or NavUtils.GetLabel(sPathing, oUnit:GetPosition()) == iPlateauWanted then
                    table.insert(tUnitsOfInterest, oUnit)
                end
            end
        end
    end

    if bSearchForLowerPriority then
        local bCheckIfAlreadyRecorded = not(AiBotUtilities.IsTableEmpty(tUnitsOfInterest))
        --Search for lower priority capture targets, and further away
        iCategoriesOfInterest = iCategoriesOfInterest + (categories.MOBILE * categories.LAND * categories.RECLAIMABLE - categories.TECH1) + AiBotUnitInfo.refCategoryT1Radar * categories.RECLAIMABLE + (AiBotUnitInfo.refCategoryStructureAA * categories.RECLAIMABLE - categories.TECH1) + AiBotUnitInfo.refCategoryPD + AiBotUnitInfo.refCategoryFixedT2Arti
        iSearchRange = math.max(math.min(350, AiBotMap.iMapSize * 0.5), iSearchRange + 25)
        if bCheckIfAlreadyRecorded then
            local tOrigUnits = {}
            for iUnit, oUnit in tUnitsOfInterest do
                table.insert(tOrigUnits, oUnit)
            end
            local tPotentialUnits = aiBrain:GetUnitsAroundPoint(iCategoriesOfInterest, tStartPoint, iSearchRange, 'Neutral')
            if AiBotUtilities.IsTableEmpty(tPotentialUnits) == false then
                local bRecordedAlready = false
                for iUnit, oUnit in tPotentialUnits do
                    bRecordedAlready = false
                    for iRecorded, oRecorded in tOrigUnits do
                        if oRecorded == oUnit then bRecordedAlready = true break end
                    end
                    if not(bRecordedAlready) then
                        table.insert(tUnitsOfInterest, oUnit)
                    end
                end
            end
        else
            tUnitsOfInterest = aiBrain:GetUnitsAroundPoint(iCategoriesOfInterest, tStartPoint, iSearchRange, 'Neutral')
        end
    end


    if bDebugMessages == true then LOG(sFunctionRef..': Running for aiBrain='..aiBrain.Nickname..' at gametime='..GetGameTimeSeconds()..'; Is table of tUnitsOfInterest empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsOfInterest))..'; iPlateauWanted='..iPlateauWanted..'; iClosestEnemyBase='..iClosestEnemyBase..'; iSearchRange='..iSearchRange..'; Is table of enemy units with further range empty='..tostring(AiBotUtilities.IsTableEmpty(aiBrain:GetUnitsAroundPoint(iCategoriesOfInterest, tStartPoint, 1000, 'Enemy')))..'; Is tNeutralMexes empty='..tostring(AiBotUtilities.IsTableEmpty(tNeutralMexes))) end
    if AiBotUtilities.IsTableEmpty(tUnitsOfInterest) == false then
        local iCurPlateau, iCurLandZone
        for iUnit, oUnit in tUnitsOfInterest do
            if oUnit:GetFractionComplete() >= 1 then
                --Is it in the same plateua?
                iCurPlateau, iCurLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition())

                if bDebugMessages == true then LOG(sFunctionRef..': Considering civilian unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurPlateau='..(iCurPlateau or 'nil')..'; iPlateauWanted='..iPlateauWanted..' (although we no longer check for this for most units), Dist to our base='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tStartPoint)..'; Mod dist='..AiBotMap.GetModDistanceFromStart(aiBrain, oUnit:GetPosition())) end
                if (iCurLandZone or 0) > 0 and (iCurPlateau or 0) > 0 then
                    --Is it one of the civilian brains we temporarily moved to be our ally?
                    if AiBotConditions.IsCivilianBrain(oUnit:GetAIBrain()) then
                        local tNearbyThreats = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryPD + AiBotUnitInfo.refCategoryFixedT2Arti, oUnit:GetPosition(), 140, 'Enemy')
                        if AiBotUtilities.IsTableEmpty(tNearbyThreats) then
                            RecordUnitAsCaptureTarget(oUnit, iCurPlateau, iCurLandZone)
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RecordUnitAsCaptureTarget(oUnit, iPlateau, iLandZone)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RevealCiviliansToAI'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local tUnitLZData
    if iPlateau == 0 then
        tUnitLZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandZone]][AiBotMap.subrefPondWaterZones][iLandZone]
    else
        tUnitLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
    end
    if not(tUnitLZData[AiBotMap.subreftoUnitsToCapture]) then tUnitLZData[AiBotMap.subreftoUnitsToCapture] = {} end
    table.insert(tUnitLZData[AiBotMap.subreftoUnitsToCapture], oUnit)
    oUnit[AiBotUnitInfo.refbIsCaptureTarget] = true

    if bDebugMessages == true then LOG(sFunctionRef..': Adding unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to the table of civilians to capture; unit brain='..(oUnit:GetAIBrain().Nickname or 'nil')..'; is civilian='..tostring(AiBotConditions.IsCivilianBrain(oUnit:GetAIBrain()))..'; iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; Island ref='..(tUnitLZData[AiBotMap.subrefLZIslandRef] or 'nil')..'; Land ref of LZData midpoint='..(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tUnitLZData[AiBotMap.subrefMidpoint]) or 'nil')..'; Land ref of the unit='..(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, oUnit:GetPosition()) or 'nil')) end
    if iPlateau > 0 then
        if not(tUnitLZData[AiBotMap.subrefLZIslandRef]) then
            local iIslandRef = (NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, oUnit:GetPosition()) or NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tUnitLZData[AiBotMap.subrefMidpoint]))
            if iIslandRef then
                if bDebugMessages == true then LOG(sFunctionRef..': will record P'..iPlateau..'Z'..iLandZone..' as having iIslandRef='..iIslandRef) end
                AiBotMap.AddLandZoneToIsland(iPlateau, iLandZone, iIslandRef, tUnitLZData)
            end
        end

        if tUnitLZData[AiBotMap.subrefLZIslandRef] then
            if not(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandUnitsToCapture][tUnitLZData[AiBotMap.subrefLZIslandRef]]) then
                if not(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandUnitsToCapture]) then AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandUnitsToCapture] = {} end
                AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandUnitsToCapture][tUnitLZData[AiBotMap.subrefLZIslandRef]] = {}
            end
            table.insert(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandUnitsToCapture][tUnitLZData[AiBotMap.subrefLZIslandRef]], oUnit)
            if bDebugMessages == true then LOG(sFunctionRef..': Recording unit against the island '..tUnitLZData[AiBotMap.subrefLZIslandRef]) end
        end
    end

    --Check not recorded as a reclaim target for any team (if unit is capturable - due to UEF M3 where black box triggers this function despite being a reclaim objective)
    ForkThread(ForkedUnitCaptureStatusCheck, oUnit, tUnitLZData)

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ForkedUnitCaptureStatusCheck(oUnit, tUnitLZData)
    WaitTicks(1)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ForkedUnitCaptureStatusCheck'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then
        LOG(sFunctionRef..': Start of code for oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Time='..GetGameTimeSeconds()..'; .Dead='..tostring(oUnit.Dead or false)..'; oUnit.IsCapturable is nil='..tostring(oUnit.IsCapturable == nil))
        if not(oUnit.Dead) and oUnit.IsCapturable then LOG(':IsCapturable='..tostring(oUnit:IsCapturable())) end
    end
    if not(oUnit.Dead) and (not(oUnit.IsCapturable) or oUnit:IsCapturable()) then
        for iTeam = 1, AiBotTeam.iTotalTeamCount do
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 0 then
                local tUnitLZTeamData = tUnitLZData[AiBotMap.subrefLZTeamData][iTeam]
                --Check if unit is recorded to be reclaimed, and if so then remove it if are capturable
                if AiBotUtilities.IsTableEmpty(tUnitLZTeamData[AiBotMap.subreftoUnitsToReclaim]) == false then
                    for iCurEntry = table.getn(tUnitLZTeamData[AiBotMap.subreftoUnitsToReclaim]), 1, -1 do
                        if tUnitLZTeamData[AiBotMap.subreftoUnitsToReclaim][iCurEntry] == oUnit then
                            table.remove(tUnitLZTeamData[AiBotMap.subreftoUnitsToReclaim], iCurEntry)
                            if bDebugMessages == true then LOG(sFunctionRef..': Removed unit '..tUnitLZTeamData[AiBotMap.subreftoUnitsToReclaim][iCurEntry].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tUnitLZTeamData[AiBotMap.subreftoUnitsToReclaim][iCurEntry])..' from the list of units to be reclaimed') end
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function OverseerManager(aiBrain)
    --ForkThread(DebugCheckProfiling, true) --true if want to only give tick count (to help figure out which tick happens just before the issue)
