    if bDebugMessages == true then LOG(sFunctionRef..': About to run main overseer loop') end
    while not(aiBrain:IsDefeated()) and not(aiBrain.AiBotIsDefeated) do
        local bEnabledProfiling = false

        --[[if GetGameTimeSeconds() >= 900 and not(bEnabledProfiling) then
             if not(import('/lua/AiBot/AiBotConfig.lua').AiBotRunProfiling) then
                 ForkThread(AiBotProfiler.ProfilerActualTimePerTick)
                 import('/lua/AiBot/AiBotConfig.lua').AiBotRunProfiling = true
