             bEnabledProfiling = true
         end--]]

        --if GetGameTimeSeconds() >= 2700 then import('/lua/AiBot/AiBotConfig.lua').AiBotShowUnitNames = true end
        --if GetGameTimeSeconds() >= 90 and GetGameTimeSeconds() <= 91 then TestCustom(aiBrain) end
        --Enable below to help figure out infinite loops
        --[[if GetGameTimeSeconds() >= 173 and not(bSetHook) then
            bSetHook = true
            AiBotProfiler.bFunctionCallDebugOverride = true
            --AiBotProfiler.bGlobalDebugOverride = true --Only enable this if want more detail as it will make things really slow
            debug.sethook(AiBotProfiler.OutputRecentFunctionCalls, "c", 200)
            LOG('Have started the main hook of function calls')
        end--]]
