end

function CheckIfScenarioMap()
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'CheckIfScenarioMap'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': ScenarioInfo.type == skirmish='..tostring(ScenarioInfo.type == "skirmish")..'; repru of ScenarioInfo.type='..repru(ScenarioInfo.type)..'; Is table of hunman players empty='..tostring(AiBotUtilities.IsTableEmpty(ScenarioInfo.HumanPlayers))..'; Is human players nil='..tostring(ScenarioInfo.HumanPlayers == nil)) end
    --Thanks to Hdt80bro for highlighting ScenarioInfo.type as a better way of figuring out if this is a campaign map
    if not(ScenarioInfo.type == "skirmish") then --AiBotUtilities.IsTableEmpty(ScenarioInfo.HumanPlayers) == false then
        AiBotMap.bIsCampaignMap = true
        LOG('Are in a campaign map, shared armies setting='..(ScenarioInfo.Options.AiBotCombinedArmy or 'nil')..'; CampAI='..(ScenarioInfo.Options.CampAI or 'nil')..'; Apply AiBotAI Easy to campaign AI='..(ScenarioInfo.Options.CmAiBotCampPers or 'nil')..'; CmApplyAIx='..(ScenarioInfo.Options.CmApplyAIx or 'nil')..'; Hostile delay='..(ScenarioInfo.Options.CmpAIDelay or 'nil'))
        --ForkThread(CheckForScenarioObjectives) --superceded by hook of addobjective
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function CheckForAlliedCampaignUnitsToShareAtGameStart(aiBrain)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'CheckForAlliedCampaignUnitsToShareAtGameStart'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local iTeam = aiBrain.AiBotTeam
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code at time '..GetGameTimeSeconds()..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAlreadyCheckedForUnitsToShare]='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAlreadyCheckedForUnitsToShare] or false)) end
    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAlreadyCheckedForUnitsToShare]) then
        AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAlreadyCheckedForUnitsToShare] = true
        while ScenarioInfo.OpEnded do
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(1)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Finished waiting for ScenarioInfo.OpEnded to finish, time='..GetGameTimeSeconds()) end
        local tStartPosition = AiBotMap.PlayerStartPoints[aiBrain:GetArmyIndex()]
        local tNearbyStructures = {}
        local iWaitCount = 0
        local tHumanBrains = {}
        local iAiBotSeparatePlayerCount = 0
        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains] do
            if bDebugMessages == true then LOG(sFunctionRef..': Creating list of human brains, oBrain.Nickanme='..oBrain.Nickname..'; brain type='..oBrain.BrainType) end
            if oBrain.BrainType == 'Human' then
                table.insert(tHumanBrains, oBrain)
            elseif oBrain.AiBotAI and not(oBrain.CampaignAI) then
                iAiBotSeparatePlayerCount = iAiBotSeparatePlayerCount + 1
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': iAiBotSeparatePlayerCount='..iAiBotSeparatePlayerCount..'; Is table of human brains empty='..tostring(AiBotUtilities.IsTableEmpty(tHumanBrains))) end
        local iCategoriesOfInterest = AiBotUnitInfo.refCategoryStructure + AiBotUnitInfo.refCategoryLandCombat + AiBotUnitInfo.refCategoryAllAir + AiBotUnitInfo.refCategoryAllNavy + AiBotUnitInfo.refCategoryEngineer - categories.COMMAND - AiBotUnitInfo.refCategoryMassStorage
        if iAiBotSeparatePlayerCount > 0 and AiBotUtilities.IsTableEmpty(tHumanBrains) == false then
            while AiBotUtilities.IsTableEmpty(tNearbyStructures) do
                if iWaitCount > 0 then
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    WaitTicks(1)
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                end
                iWaitCount = iWaitCount + 1
                if GetGameTimeSeconds() >= 120 and (not(ScenarioInfo.OpEnded) or GetGameTimeSeconds() >= 240) then break end
                for iBrain, oBrain in tHumanBrains do
                    local tPotentialStructures = oBrain:GetListOfUnits(iCategoriesOfInterest, false, true)
                    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; Is table of potential units empty for brain '..oBrain.Nickname..'='..tostring(AiBotUtilities.IsTableEmpty(tPotentialStructures))) end
                    if AiBotUtilities.IsTableEmpty(tPotentialStructures) == false then
                        for iUnit, oUnit in tPotentialStructures do
                            table.insert(tNearbyStructures, oUnit)
                        end
                    end
                end
                --tNearbyStructures = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryStructure, tStartPosition, 1000, 'Ally')
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': FInished wait for checking for ally structures to share, Time='..GetGameTimeSeconds()..'; Is tNearbyStructures empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyStructures))) end
        if AiBotUtilities.IsTableEmpty(tNearbyStructures) == false then
            --local tUnitsOfCategoryWanted = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryStructure + AiBotUnitInfo.refCategoryLandCombat + AiBotUnitInfo.refCategoryAllAir + AiBotUnitInfo.refCategoryAllNavy - categories.COMMAND, tStartPosition, 1000, 'Ally')
            local tUnitsOfCategoryWanted = tNearbyStructures
            if bDebugMessages == true then LOG(sFunctionRef..': Is table of units of category wanted empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsOfCategoryWanted))) end
            if AiBotUtilities.IsTableEmpty(tUnitsOfCategoryWanted) == false then
                local tUnitsToShareByBlueprint = {}
                for iUnit, oUnit in  tUnitsOfCategoryWanted do
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to add unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to table of units to share, Is uint valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))..'; Fraction complete='..oUnit:GetFractionComplete()..'; Unit brain nickname='..oUnit:GetAIBrain().Nickname..'; Unit brain type='..oUnit:GetAIBrain().BrainType) end
                    if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() == 1 and oUnit:GetAIBrain().BrainType == "Human" then
                        if not(tUnitsToShareByBlueprint[oUnit.UnitId]) then tUnitsToShareByBlueprint[oUnit.UnitId] = {} end
                        table.insert(tUnitsToShareByBlueprint[oUnit.UnitId], oUnit)
                        if bDebugMessages == true then LOG(sFunctionRef..': Add unit to the table of units to consider sharing') end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Is untis to share empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsToShareByBlueprint))) end
                if AiBotUtilities.IsTableEmpty(tUnitsToShareByBlueprint) == false then
                    local iNthEntryToGive
                    local iHumanBrainCount = 0
                    local iAiBotBrainCount = 0
                    for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains] do
                        if oBrain.AiBotAI and not(oBrain.CampaignAI) and not(oBrain.BrainType == 'Human') then iAiBotBrainCount = iAiBotBrainCount + 1
                        elseif oBrain.BrainType == 'Human' then
                            iHumanBrainCount = iHumanBrainCount + 1
                        end
                    end
                    if iAiBotBrainCount >= 1 and iAiBotBrainCount + iHumanBrainCount > 1 then
                        local iUnitsAlreadyOwnedOfBlueprint
                        iNthEntryToGive = math.ceil((iAiBotBrainCount + iHumanBrainCount) / iAiBotBrainCount)
                        local iTotalUnitCount
                        local iCurCycleCount
                        local tUnitsToGive = {}
                        local iCurNthEntryToGive
                        if bDebugMessages == true then LOG(sFunctionRef..': About to cycle through all units to potentially share, iNthEntryToGive='..iNthEntryToGive..'; iAiBotBrainCount='..iAiBotBrainCount..'; iHumanBrainCount='..iHumanBrainCount) end
                        for sBlueprint, tUnits in tUnitsToShareByBlueprint do
                            iCurNthEntryToGive = iNthEntryToGive
                            iTotalUnitCount = table.getn(tUnits)
                            if bDebugMessages == true then LOG(sFunctionRef..': sBLueprint='..sBlueprint..'; iTotalUnitCount='..iTotalUnitCount) end
                            if iTotalUnitCount >= iNthEntryToGive then
                                iUnitsAlreadyOwnedOfBlueprint = 0
                                for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                                    iUnitsAlreadyOwnedOfBlueprint = iUnitsAlreadyOwnedOfBlueprint + oBrain:GetCurrentUnits(categories[sBlueprint])
                                    if bDebugMessages == true then LOG(sFunctionRef..': oBrain cur units for sBlueprint='..oBrain:GetCurrentUnits(categories[sBlueprint])) end
                                end
                                if iUnitsAlreadyOwnedOfBlueprint > 0 then
                                    if iUnitsAlreadyOwnedOfBlueprint >= iTotalUnitCount then
                                        iCurNthEntryToGive = 1000
                                    else
                                        iCurNthEntryToGive = iCurNthEntryToGive + (iUnitsAlreadyOwnedOfBlueprint - iTotalUnitCount) * iAiBotBrainCount
                                    end
                                end
                                iCurCycleCount = 0
                                for iUnit, oUnit in tUnits do
                                    iCurCycleCount = iCurCycleCount + 1
                                    if iCurCycleCount >= iNthEntryToGive then
                                        table.insert(tUnitsToGive, oUnit)
                                        iCurCycleCount = 0
                                    end
                                end
                            end
                        end
                        if AiBotUtilities.IsTableEmpty(tUnitsToGive) == false then
                            local tiAiBotBrains = {}
                            local iAiBotBrainCount = 0
                            local oCurBrain
                            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false then
                                for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                                    if not(oBrain.CampaignAI) then
                                        table.insert(tiAiBotBrains, oBrain)
                                        iAiBotBrainCount = iAiBotBrainCount + 1
                                    end
                                end
                            elseif aiBrain.AiBotAI then
                                table.insert(tiAiBotBrains, aiBrain)
                                AiBotUtilities.ErrorHandler('Dont have any activeAiBot brains noted despite dealing with an AiBotBrain')
                            end
                            for iUnit, oUnit in tUnitsToGive do
                                if iAiBotBrainCount > 1 then
                                    oCurBrain = tiAiBotBrains[math.random(1, iAiBotBrainCount)]
                                else
                                    oCurBrain = tiAiBotBrains[iAiBotBrainCount]
                                end
                                --Gift adjacent mass storage if any
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oUnit.UnitId) then
                                    AiBotTeam.GiftAdjacentStorageToMexOwner(oUnit, oCurBrain)
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Just about to try and gift unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by '..oUnit:GetAIBrain().Nickname..' to AiBotAI brain '..oCurBrain.Nickname) end
                                AiBotTeam.TransferUnitsToPlayer({ oUnit }, oCurBrain:GetArmyIndex(), false)
                            end
                        end
                    end
                end
            end
        end

        --Make sure have full energy to cover any energy storage that have transferred over
        local iMaxEnergy, iCurEnergy
        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
            iMaxEnergy = AiBotEconomy.GetEnergyStorageMaximum(oBrain, true)
            iCurEnergy = oBrain:GetEconomyStored('ENERGY')
            if iCurEnergy < iMaxEnergy then
                oBrain:GiveResource('Energy', iMaxEnergy - iCurEnergy)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function SetBuildAndResourceCheatModifiers(aiBrain, iBuildModifier, iResourceModifier, bDontChangeScenarioInfo, iOptionalRecordedUnitResourceAdjust, bDontApplyToUnits, bUpdateCheatValue, bDontCreateBuffs)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'SetBuildAndResourceCheatModifiers'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code for aiBrain='..aiBrain.Nickname..'; iBuildModifier='..iBuildModifier..'; iResourceModifier='..iResourceModifier) end
    --Force build modifier and resource modifier to be numeric
    iBuildModifier = tonumber(iBuildModifier)
    iResourceModifier = tonumber(iResourceModifier)
    --Note - see also FixUnitResourceCheatModifiers(oUnit) for a function intended to try and fix SACU FAF issue with AIx
    if not(bDontChangeScenarioInfo) then
        ScenarioInfo.Options.CheatMult = tostring(iResourceModifier)
        ScenarioInfo.Options.BuildMult = tostring(iBuildModifier)
    end
    if bUpdateCheatValue then aiBrain.CheatValue = math.min(iBuildModifier, iResourceModifier) end
    if not(bDontCreateBuffs) then
        --local FAFBuffs = import('/lua/sim/Buff.lua')
        local sCheatBuildRate = 'CheatBuildRate'..aiBrain:GetArmyIndex()
        local sCheatIncome = 'CheatIncome'..aiBrain:GetArmyIndex()
        --local AdjBuffFuncs = import('/lua/sim/adjacencybufffunctions.lua')
        if not Buffs[sCheatBuildRate] then
            BuffBlueprint {
                Name = sCheatBuildRate,
                DisplayName = sCheatBuildRate,
                BuffType = 'BUILDRATECHEAT',
                Stacks = 'ALWAYS',
                Duration = -1,
                Affects = {
                    BuildRate = {
                        --BuffCheckFunction = AdjBuffFuncs.BuildRateBuffCheck,
                        Add = 0,
                        Mult = 1,
                    },
                },
            }
        end
        if not Buffs[sCheatIncome] then
            BuffBlueprint {
                Name = sCheatIncome,
                DisplayName = sCheatBuildRate,
                BuffType = 'INCOMECHEAT',
                Stacks = 'ALWAYS',
                Duration = -1,
                Affects = {
                    EnergyProduction = {
                        --BuffCheckFunction = AdjBuffFuncs.EnergyProductionBuffCheck,
                        Add = 0,
                        Mult = 1,
                    },
                    MassProduction = {
                        --BuffCheckFunction = AdjBuffFuncs.MassProductionBuffCheck,
                        Add = 0,
                        Mult = 1,
                    }
                },
            }
        end
        if AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive then
            Buffs[sCheatBuildRate].EntityCategory = 'ALLUNITS'
            Buffs[sCheatIncome].EntityCategory = 'ALLUNITS'
            Buffs[sCheatBuildRate].ParsedEntityCategory = categories.ALLUNITS
            Buffs[sCheatIncome].ParsedEntityCategory = categories.ALLUNITS
        end
        Buffs['CheatBuildRate'..aiBrain:GetArmyIndex()].Affects.BuildRate.Mult = iBuildModifier
        Buffs['CheatIncome'..aiBrain:GetArmyIndex()].Affects.EnergyProduction.Mult = iResourceModifier
        Buffs['CheatIncome'..aiBrain:GetArmyIndex()].Affects.MassProduction.Mult = iResourceModifier
    end
    if not(bDontApplyToUnits) then
        --Want both resource producing units, and units that can be upgraded
        local tExistingUnits = aiBrain:GetListOfUnits(AiBotUnitInfo.refCategoryResourceUnit + AiBotUnitInfo.refCategoryProductionUnit, false, false)
        if bDebugMessages == true then LOG(sFunctionRef..': Is table of existing units empty='..tostring(AiBotUtilities.IsTableEmpty(tExistingUnits))..'; Brain='..aiBrain.Nickname..'; Buffs[\'CheatBuildRate\'..aiBrain:GetArmyIndex()].Affects.BuildRate.Mult='..(Buffs['CheatBuildRate'..aiBrain:GetArmyIndex()].Affects.BuildRate.Mult or 'nil')..'; Time='..GetGameTimeSeconds()) end
        if AiBotUtilities.IsTableEmpty(tExistingUnits) == false then
            for iUnit, oUnit in tExistingUnits do
                AiBotUnitInfo.FixUnitResourceCheatModifiers(oUnit)
                --[[if bDebugMessages == true then LOG(sFunctionRef..': Applying buffs to unit '..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..' for brain='..aiBrain.Nickname..' with index='..aiBrain:GetArmyIndex()) end
                FAFBuffs.RemoveBuff(oUnit, 'CheatIncome'..aiBrain:GetArmyIndex(), true)
                FAFBuffs.ApplyBuff(oUnit, 'CheatIncome'..aiBrain:GetArmyIndex())
                FAFBuffs.RemoveBuff(oUnit, 'CheatBuildRate'..aiBrain:GetArmyIndex(), true)
                FAFBuffs.ApplyBuff(oUnit, 'CheatBuildRate'..aiBrain:GetArmyIndex())--]]
                if iOptionalRecordedUnitResourceAdjust then
                    ForkThread(UpdateGrossIncomeForUnit, oUnit, false, false, iOptionalRecordedUnitResourceAdjust)
                end
            end
        end
    end
    if not(aiBrain.CheatEnabled) and not(iResourceModifier == 1 and iBuildModifier == 1) then aiBrain.CheatEnabled = true end --redundnacy
    aiBrain[AiBotEconomy.refiBrainResourceMultiplier] = iResourceModifier
    aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier] = iBuildModifier
    if aiBrain.CheatEnabled and aiBrain.AiBotTeam then
        AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiHighestBrainResourceMultiplier] = math.max((AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiHighestBrainResourceMultiplier] or 0.1), iResourceModifier)
        AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiHighestBrainBuildMultiplier] = math.max((AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiHighestBrainBuildMultiplier] or 0.1), iBuildModifier)
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code for aiBrain='..aiBrain.Nickname..'; .CheatEnabled='..tostring(aiBrain.CheatEnabled or false)..'; refiBrainResourceMultiplier='..(aiBrain[AiBotEconomy.refiBrainResourceMultiplier] or 'nil')..'; refiBrainBuildRateMultiplier='..(aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier] or 'nil')) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function CheckForScenarioObjectives()
    --NO LONGER USED - use AddObjective hook instead
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'CheckForScenarioObjectives'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    AiBotUtilities.ErrorHandler('Obsolete function')
    if bDebugMessages == true then LOG(sFunctionRef..': Will start scenario mission checker if not already active, bActiveMissionChecker='..tostring(bActiveMissionChecker)) end
    if not(bActiveMissionChecker) then
        bActiveMissionChecker = true

        while not(AiBotMap.bMapLandSetupComplete) do
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(1)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            if AiBotUtilities.IsTableEmpty(tAllActiveAiBotBrains) then break end
        end
        local iTeam

        local tObjectivesConsidered = {}
        local iLastMissionConsidered = 0
        function ConsiderObjective(sMissionRef, iMission, iObjective)
            --Does this objective exist and we havent already considered it?
            if ScenarioInfo[sMissionRef] and not(tObjectivesConsidered[sMissionRef]) then
                tObjectivesConsidered[sMissionRef] = true
                iLastMissionConsidered = math.max(iMission, iLastMissionConsidered)
                if bDebugMessages == true then LOG(sFunctionRef..': Have just recorded a new objective, sMissionRef='..sMissionRef..'; iMission='..iMission..'; iObjective='..iObjective..'; reprs of mission='..reprs(ScenarioInfo[sMissionRef])) end
            end
        end
        local sMissionRef
        if bDebugMessages == true then LOG(sFunctionRef..': About to start main loop, is table of active AiBot brains empty='..tostring(AiBotUtilities.IsTableEmpty(tAllActiveAiBotBrains))) end
        while AiBotUtilities.IsTableEmpty(tAllActiveAiBotBrains) == false do
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(60)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            --Check for new objectives
            for iMission = math.max(1, iLastMissionConsidered), iLastMissionConsidered + 1 do
                for iPrimaryObjective = 1, 5 do
                    sMissionRef = 'M'..iMission..'P'..iPrimaryObjective
                    ConsiderObjective(sMissionRef, iMission, iPrimaryObjective)
                end
                for iSecondaryObjective = 1, 5 do
                    sMissionRef = 'M'..iMission..'S'..iSecondaryObjective
                    ConsiderObjective(sMissionRef, iMission, iSecondaryObjective)
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Finished checking form issions, iLastMissionConsidered='..iLastMissionConsidered..'; tObjectivesConsidered='..repru(tObjectivesConsidered)) end
        end

        bActiveMissionChecker = false
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

