function DelayedCybranFireBlackSun(aiBrain)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'DelayedCybranFireBlackSun'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': Will wait a bit then fire black sun') end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    WaitSeconds(10)
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': Has the op ended yet='..tostring(ScenarioInfo.OpEnded or false)..'; OpComplete='..tostring(ScenarioInfo.OpComplete or false)) end
    if not(ScenarioInfo.OpEnded) and not(ScenarioInfo.OpComplete) then
        AiBotChat.SendMessage(aiBrain, 'M6End', 'Getting ready to fire black sun...', 0, 100000, false, false)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(5)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        if bDebugMessages == true then LOG(sFunctionRef..': WIll fire black sun') end
        local ScenarioFramework = import('/lua/ScenarioFramework.lua')
        ScenarioFramework.FlushDialogueQueue()
        ScenarioFramework.EndOperationSafety()
        ScenarioInfo.OpComplete = true
        if ScenarioInfo.M3P2 then
            ScenarioInfo.M3P2:ManualResult(true)
        end
        ScenarioFramework.EndOperation(ScenarioInfo.OpComplete, ScenarioInfo.OpComplete, true)
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function M1AeonEndMissionBackupMonitor()
    --Every 20s checks if have killed enemy ACU then waits another 20s before ending game (as default is far too long)
    --Call via fork thread
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'M1AeonEndMissionBackupMonitor'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': start of code, for time '..GetGameTimeSeconds()..'; bActiveMissionChecker='..tostring(bActiveMissionChecker)..'; Is M7 UEF commander valid='..tostring(AiBotUnitInfo.IsUnitValid(ScenarioInfo.M7_FauxUEFCommanderUnit))) end
    if not(bActiveMissionChecker) and AiBotUnitInfo.IsUnitValid(ScenarioInfo.M7_FauxUEFCommanderUnit) then
        bActiveMissionChecker = true
        while AiBotUnitInfo.IsUnitValid(ScenarioInfo.M7_FauxUEFCommanderUnit) do
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(20)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; Is UEF ACU still valid='..tostring( AiBotUnitInfo.IsUnitValid(ScenarioInfo.M7_FauxUEFCommanderUnit))) end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': UEF ACU is now dead, will wait 20s then start ending the game') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(20)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        if bDebugMessages == true then LOG(sFunctionRef..': Is operation not ending yet via normal logic='..tostring(not(ScenarioInfo.OperationEnding))..'; Time='..GetGameTimeSeconds()) end
        if ScenarioInfo.OperationEnding then
            if bDebugMessages == true then LOG(sFunctionRef..': Will wait another 15s to see if scenario ends') end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(15)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end --Wait another 15s to give the main mission a chance to end properly
        if ScenarioInfo.M7P4.ManualResult then
            ScenarioInfo.M7P4.ManualResult(true)
            if bDebugMessages == true then LOG(sFunctionRef..': Will end operation safely, and then wait 10s and end operation') end
            local ScenarioFramework = import('/lua/ScenarioFramework.lua')
            local OpStrings   = import('/maps/scca_coop_a01.v0016/SCCA_Coop_A01_Strings.lua')
            local Objectives = import('/lua/ScenarioFramework.lua').Objectives
            ScenarioFramework.EndOperationSafety()
            ScenarioFramework.Dialogue(OpStrings.A01_M07_116, false, true) -- Rhiza: "Glorious!"
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(5)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            ScenarioInfo.OpComplete = true
            local secondary = Objectives.IsComplete(ScenarioInfo.M7S1) and Objectives.IsComplete(ScenarioInfo.M7S2)
            local bonus = Objectives.IsComplete(ScenarioInfo.M1B1) and Objectives.IsComplete(ScenarioInfo.M1B2) and Objectives.IsComplete(ScenarioInfo.M1B3) and Objectives.IsComplete(ScenarioInfo.M6B1)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(5.0)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            if bDebugMessages == true then LOG(sFunctionRef..': Will now end operation at time '..GetGameTimeSeconds()) end
            ScenarioFramework.EndOperation(ScenarioInfo.OpComplete, ScenarioInfo.OpComplete, secondary, bonus)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderSpecialCampaignObjectives(Type, Complete, Title, Description, ActionImage, Target, IsLoading, loadedTag, iOptionalWaitInSeconds)
    --NOTE: All of input variables are optional as sometimes we just call this due to a playable area size change
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderSpecialCampaignObjectives'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if iOptionalWaitInSeconds then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(iOptionalWaitInSeconds)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Near start of code at time '..GetGameTimeSeconds()..' after iOptionalWaitInSeconds='..(iOptionalWaitInSeconds or 'nil')..'; Is M3P3 active='..tostring(ScenarioInfo.M3P3.Active or false)..'; Is commander gate area empty='..tostring(Scenario.Areas['CDR_Gate_Area'] == nil)..'; CDR_Gate_Area='..repru(Scenario.Areas['CDR_Gate_Area'])..'; ScenarioInfo.M1P3.Active='..tostring(ScenarioInfo.M1P3.Active or false)..'; Is combined table empty='..tostring(AiBotUtilities.IsTableEmpty(ScenarioInfo.M1_TempleCombinedTable))..'; M1P2 active='..tostring(ScenarioInfo.M1P2.Active)..'; M1P1 active='..tostring(ScenarioInfo.M1P1.Active)..'; ScenarioInfo.MissionNumber='..(ScenarioInfo.MissionNumber or 'nil')) end

    local aiBrain
    for iBrain, oBrain in tAllActiveAiBotBrains do
        if oBrain.AiBotAI and not(oBrain.CampaignAI) then aiBrain = oBrain break end
    end
    if not(aiBrain) then
        --Get first player
        local oFirstPlayer
        for iBrain, oBrain in ArmyBrains do
            if oBrain.Human then oFirstPlayer = oBrain break end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': oFirstPlayer nickname='..(oFirstPlayer.Nickname or 'nil')) end
        if oFirstPlayer then
            local oNonHostileBrain
            local oHostileBrain

            for iBrain, oBrain in ArmyBrains do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering backup AiBot brain, oBrain='..(oBrain.Nickname)..'; IsAlly='..tostring(IsAlly(oBrain:GetArmyIndex(), oFirstPlayer:GetArmyIndex()))..'; .AiBotAI='..tostring(oBrain.AiBotAI or false)..'; Is enemy='..tostring(IsEnemy(oBrain:GetArmyIndex(), oFirstPlayer:GetArmyIndex()))) end
                if oBrain.AiBotAI and IsAlly(oBrain:GetArmyIndex(), oFirstPlayer:GetArmyIndex()) then
                    aiBrain = oBrain
                    break
                elseif not(oNonHostileBrain) and oBrain.AiBotAI and not(IsEnemy(oBrain:GetArmyIndex(), oFirstPlayer:GetArmyIndex())) then
                    oNonHostileBrain = oBrain
                elseif not(oHostileBrain) and oBrain.AiBotAI and IsEnemy(oBrain:GetArmyIndex(), oFirstPlayer:GetArmyIndex()) then
                    oHostileBrain = oBrain
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Finished searching for backup brain, aiBrain='..(aiBrain.Nickname or 'nil')..'; oNonHostileBrain='..(oNonHostileBrain.Nickname or 'nil')) end
            if not(aiBrain) then aiBrain = oNonHostileBrain or oHostileBrain end
        end
    end
    if aiBrain then
        local iTeam = aiBrain.AiBotTeam

        if bDebugMessages == true then
            LOG(sFunctionRef..': Further logs, ScenarioInfo.M3BaseDamageWarnings='..(ScenarioInfo.M3BaseDamageWarnings or 'nil')..'; ScenarioInfo.MainFrameIsAlive='..tostring(ScenarioInfo.MainFrameIsAlive or false)..'; ScenarioInfo.EMPFired='..tostring(ScenarioInfo.EMPFired or false)..'; ScenarioInfo.M3_Base is empty='..tostring(AiBotUtilities.IsTableEmpty(ScenarioInfo.M3_Base))..'; bPacifistModeActive='..tostring(bPacifistModeActive)..'; ScenarioInfo.MissionNumber='..(ScenarioInfo.MissionNumber or 'nil')..'; iTeam='..iTeam..'; C M6: ScenarioInfo.ControlCenter is nil='..tostring(ScenarioInfo.ControlCenter == nil)..'; ScenarioInfo.Czar is nil='..tostring(ScenarioInfo.Czar == nil)..'; Is table of czars empty='..tostring(AiBotUtilities.IsTableEmpty(ScenarioInfo.Czar))..'; Is M3P1 active='..tostring(ScenarioInfo.M3P1.Active)..'; Is M3P2 active='..tostring(ScenarioInfo.M3P2.Active)..'; Is there a valid black sun unit='..tostring(AiBotUnitInfo.IsUnitValid(ScenarioInfo.BlackSunWeapon))..'; UEF M5: Is ScenarioInfo.M1P2.Active='..tostring(ScenarioInfo.M1P2.Active or false)..'; Is research facility 1 nil='..tostring(ScenarioInfo.ResearchFacility1 == nil)..'; Is research facility 2 nil='..tostring(ScenarioInfo.ResearchFacility2 == nil))
            if AiBotUnitInfo.IsUnitValid(ScenarioInfo.BlackSunWeapon) then LOG(sFunctionRef..': Have a valid black sun unit, Target[1].UnitId='..(Target[1].UnitId or 'nil')..'; Black sun brain owner='..ScenarioInfo.BlackSunWeapon:GetAIBrain().Nickname..'; Faction index='..ScenarioInfo.BlackSunWeapon:GetAIBrain():GetFactionIndex()) end
            LOG(sFunctionRef..': Sera M3 logs, Is M4P3 active='..tostring(ScenarioInfo.M4P3.Active)..'; Is target category urc1901='..tostring(Target.Requirements[1].Category == categories.urc1901)..'; Target.Area='..(Target.Requirements[1].Area or 'nil')..'; reprs of ScenarioInfo.M2P2='..reprs(ScenarioInfo.M2P2)..'; reprs of Target='..reprs(Target))
            LOG(sFunctionRef..': Aeon M5 check, if ScenarioInfo.M2P1Obj.Active='..tostring(ScenarioInfo.M2P1Obj.Active or false)..'; ScenarioInfo.Ariel==nil='..tostring(ScenarioInfo.Ariel == nil)..'; Colonies is nil='..tostring(ScenarioInfo.Colonies == nil)..'; tbSpecialCodeForMission[21]='..tostring(tbSpecialCodeForMission[21] or false))
            LOG(sFunctionRef..': UEF M6 check, ScenarioInfo.Component='..(ScenarioInfo.Component or 'nil')..'; ScenarioInfo.BlackSun='..(ScenarioInfo.BlackSun or 'nil')..'; is ScenarioInfo.BlackSunComponent valid='..tostring(AiBotUnitInfo.IsUnitValid(ScenarioInfo.BlackSunComponent))..'; is it nil='..tostring(ScenarioInfo.BlackSunComponent == nil)..'; ScenarioInfo.M1P2.Active='..tostring(ScenarioInfo.M1P2.Active))
            LOG(sFunctionRef..': Cybran M5 check, ScenarioInfo.FauxUEF='..(ScenarioInfo.FauxUEF or 'nil')..'; Hex5='..(ScenarioInfo.Hex5 or 'nil')..'; M1P1Complete='..tostring(ScenarioInfo.M1P1Complete or false)..'; M2P2Complete='..tostring(ScenarioInfo.M2P2Complete or false))
            LOG(sFunctionRef..': FA M1 check, is ScenarioInfo.M1ObjectiveShield nil='..tostring(ScenarioInfo.M1ObjectiveShield == nil)..'; .UnitId='..(ScenarioInfo.M1ObjectiveShield.UnitId or 'nil'))
        end
        --UEF M1 - Air fac upgrading breaks the mission
        if ScenarioInfo.AirFactory.UnitId and not(ScenarioInfo.AirFactory[AiBotUnitInfo.refbObjectiveUnit]) and ScenarioInfo.AirFactory:GetBlueprint().General.UpgradesTo and ScenarioInfo.AirFactory:GetAIBrain().AiBotAI then
            if bDebugMessages == true then LOG(sFunctionRef..': Flagging not to upgrade unit '..ScenarioInfo.AirFactory.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(ScenarioInfo.AirFactory.UnitId)..' as it may be an objective unit') end
            ScenarioInfo.AirFactory[AiBotUnitInfo.refbObjectiveUnit] = true
        end
        --UEF Mission 2 - if player 1 has AiBotAI logic active, then try and move units to the area for civilians
        if Target.Area == 'Civilian_Area' and ScenarioInfo.M2P1.Active and ScenarioInfo.AllyResearch == 3 and ScenarioInfo.AllyCivilian == 4 and ScenarioInfo.CivilianFacilityReinforcedObjectiveComplete == false then
            ForkThread(UEFMission2ReinforceCivilianTracker, iTeam)
            --UEF Mission 2 - repair research facility (it gets transfered to player when they land units) - refer to DeathTriggerAdded
            --UEF Mission 3 - get MAA and inties early on
        elseif ScenarioInfo.Arnold == 3 and ScenarioInfo.Aeon == 2 and ScenarioInfo.M1P1.Active and not(aiBrain['AiBotUEFM3MAALoop']) then
            while true do
                local iCurMAA = aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMAA)
                local iCurAirAA = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat] / 50
                local tLandFactories = aiBrain:GetListOfUnits(AiBotUnitInfo.refCategoryLandFactory, false, true)
                local tAirFactories = aiBrain:GetListOfUnits(AiBotUnitInfo.refCategoryAirFactory, false, true)
                if AiBotUtilities.IsTableEmpty(tLandFactories) == false or AiBotUtilities.IsTableEmpty(tAirFactories) == false then
                    --Consider aborting the loop
                    if GetGameTimeSeconds() >= 900 or iCurMAA >= 14 or iCurAirAA >= 20 or not(ScenarioInfo.M1P1.Active) then
                        aiBrain['AiBotUEFM3MAALoop'] = nil
                        if AiBotUtilities.IsTableEmpty(tLandFactories) == false then
                            for iFactory, oFactory in tLandFactories do
                                oFactory[AiBotFactory.refsFactoryNextBlueprintOverride] = nil
                            end
                        end
                        if AiBotUtilities.IsTableEmpty(tAirFactories) == false then
                            for iFactory, oFactory in tAirFactories do
                                oFactory[AiBotFactory.refsFactoryNextBlueprintOverride] = nil
                            end
                        end
                        break
                    end
                    if AiBotUtilities.IsTableEmpty(tLandFactories) == false then
                        for iFactory, oFactory in tLandFactories do
                            if (oFactory[AiBotFactory.refiTotalBuildCount] or 0) > 0 and (iCurMAA <= 8 or (oFactory[AiBotFactory.refsLastBlueprintBuilt] and not(EntityCategoryContains(AiBotUnitInfo.refCategoryMAA, oFactory[AiBotFactory.refsLastBlueprintBuilt])))) and (oFactory[AiBotFactory.refiTotalBuildCount] >= 5 or AiBotUnitInfo.GetUnitLifetimeCount(oFactory) > 1 or (AiBotUnitInfo.GetUnitTechLevel(oFactory) >= 2 and oFactory[AiBotFactory.refiTotalBuildCount] >= 2)) then
                                oFactory[AiBotFactory.refsFactoryNextBlueprintOverride] = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, AiBotUnitInfo.refCategoryMAA, oFactory, false, false, false, nil, false, nil, true)
                                if AiBotUnitInfo.GetUnitLifetimeCount(oFactory) == 1 then oFactory[AiBotFactory.refbPrimaryFactoryForIslandOrPond] = true end
                            else
                                oFactory[AiBotFactory.refsFactoryNextBlueprintOverride] = nil
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': COnsidered setting MAA override for oFactory='..oFactory.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFactory)..'; refsFactoryNextBlueprintOverride='..(oFactory[AiBotFactory.refsFactoryNextBlueprintOverride] or 'nil')..'; iCurMAA='..iCurMAA..'; refiTotalBuildCount='..(oFactory[AiBotFactory.refiTotalBuildCount] or 'nil')) end
                        end
                    end
                    if AiBotUtilities.IsTableEmpty(tAirFactories) == false then
                        for iFactory, oFactory in tAirFactories do
                            if (oFactory[AiBotFactory.refiTotalBuildCount] or 0) >= 2 and (oFactory[AiBotFactory.refsLastBlueprintBuilt] and (iCurAirAA < 3 or not(EntityCategoryContains(AiBotUnitInfo.refCategoryAirAA, oFactory[AiBotFactory.refsLastBlueprintBuilt]))))
                                    and (iCurAirAA < 5 or not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])) then
                                oFactory[AiBotFactory.refsFactoryNextBlueprintOverride] = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, AiBotUnitInfo.refCategoryAirAA, oFactory, false, false, false, nil, false, nil, true)
                                if AiBotUnitInfo.GetUnitLifetimeCount(oFactory) == 1 then oFactory[AiBotFactory.refbPrimaryFactoryForIslandOrPond] = true end
                            else
                                oFactory[AiBotFactory.refsFactoryNextBlueprintOverride] = nil
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': COnsidered setting AirAA override for oFactory='..oFactory.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFactory)..'; refsFactoryNextBlueprintOverride='..(oFactory[AiBotFactory.refsFactoryNextBlueprintOverride] or 'nil')..'; iCurAirAA estimate='..iCurAirAA..'; refiTotalBuildCount='..(oFactory[AiBotFactory.refiTotalBuildCount] or 'nil')) end
                        end
                    end
                end
                WaitSeconds(5)
            end

            --UEF Mission 3 - create a special death trigger for Aeon ACU due to flaw with preceding objective
        elseif ScenarioInfo.M4P1 and AiBotUtilities.IsTableEmpty(Target.Units) and ScenarioInfo.M4P1.Active and AiBotUnitInfo.IsUnitValid(ScenarioInfo.AeonCDR) then
            if bDebugMessages == true then LOG(sFunctionRef..': Creating manual on death trigger') end
            local ScenarioFramework = import('/lua/ScenarioFramework.lua')
            ScenarioFramework.CreateUnitDeathTrigger(AiBotErisKilled, ScenarioInfo.AeonCDR)
            --UEF Mission 4 - send sweeney to gateway
        elseif ScenarioInfo.M2P2.Active and ScenarioInfo.M3Gate and ScenarioInfo.M2EscapeTruck then
            local tTrucks = ScenarioInfo.M2EscapeTruck:GetPlatoonUnits()
            local rTargetRect = import("/lua/sim/scenarioutilities.lua").AreaToRect('M3_Engineer_Teleport')
            local tTargetMidpoint = {(rTargetRect['x0'] + rTargetRect['x1'])*0.5 , 0, (rTargetRect['y0'] + rTargetRect['y1'])*0.5}
            tTargetMidpoint[2] = GetTerrainHeight(tTargetMidpoint[1], tTargetMidpoint[3])

            ForkThread(UEFMissionSendTruckToTarget, tTrucks, tTargetMidpoint, 'M2P2')

            --UEF Mission 4 - build T2 radar
        elseif ScenarioInfo.M3P1.Active and ScenarioInfo.M3RadarsUp then
            local ScenarioUtils = import('/lua/sim/ScenarioUtilities.lua')
            local tRect1 = ScenarioUtils.AreaToRect('M3_Radar_Loc_01')
            local tRect2 = ScenarioUtils.AreaToRect('M3_Radar_Loc_02')
            local tRect3 = ScenarioUtils.AreaToRect('M3_Radar_Loc_03')
            local trRects = {}
            for iRect, tRect in {tRect1, tRect2, tRect3} do
                trRects[iRect] = {tRect['x0'], tRect['y0'], tRect['x1'], tRect['y1']}
                if trRects[iRect] then
                    local rRect = trRects[iRect]
                    local tLocation = {(rRect[1] + rRect[3])*0.5, 0, (rRect[2] + rRect[4])*0.5}
                    local iSize = math.min(rRect[3] - rRect[1], rRect[4] - rRect[2]) * 0.5
                    tLocation[2] = GetTerrainHeight(tLocation[1], tLocation[3])
                    local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tLocation)
                    if (iLandZone or 0) > 0 then
                        local tLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][iTeam]
                        --Wont set a size for now (v296 functionality)
                        tLZTeamData[AiBotMap.reftObjectiveLocation] = {[AiBotMap.subreftObjLocation] = {tLocation[1], tLocation[2], tLocation[3]}, [AiBotMap.subrefiObjCategoryToBuild] = categories.ueb3201, [AiBotMap.subrefiObjTechLevelWanted] = 2, [AiBotMap.subrefiObjLocationSize] = iSize, [AiBotMap.subrefiNumberWanted] = 1}
                        if bDebugMessages == true then LOG(sFunctionRef..': Added T2 radar location for Plateau '..iPlateau..'; Zone '..iLandZone..'; reftObjectiveLocation='..reprs(tLZTeamData[AiBotMap.reftObjectiveLocation])) end
                    end
                end
            end
            --UEF Mission 5 - send ACU to gateway
        elseif ScenarioInfo.M3P3.Active and Scenario.Areas['CDR_Gate_Area'] and ScenarioInfo.PlayerCDRs and ScenarioInfo.City then
            SendACUsToCampaignObjective('CDR_Gate_Area')

            --UEF M5 - sending trucks - refer to DeathTriggerAdded

            --UEF M5 - build SMD and protect research facilities with heavy shields
        elseif (ScenarioInfo.ResearchFacility1 or ScenarioInfo.ResearchFacility2 or ScenarioInfo.ResearchFacility3) then
            if ScenarioInfo.M1P2.Active then
                local tResearchLocations = {}
                if AiBotUnitInfo.IsUnitValid(ScenarioInfo.ResearchFacility1) then
                    table.insert(tResearchLocations, ScenarioInfo.ResearchFacility1:GetPosition())
                end
                if AiBotUnitInfo.IsUnitValid(ScenarioInfo.ResearchFacility2) then
                    table.insert(tResearchLocations, ScenarioInfo.ResearchFacility2:GetPosition())
                end
                if AiBotUnitInfo.IsUnitValid(ScenarioInfo.ResearchFacility3) then
                    table.insert(tResearchLocations, ScenarioInfo.ResearchFacility3:GetPosition())
                end
                if AiBotUtilities.IsTableEmpty(tResearchLocations) == false then
                    for iEntry, tLocation in tResearchLocations do
                        local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tLocation)
                        if (iLandZone or 0) > 0 then
                            local tLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][iTeam]
                            --Wont set a size for now (v296 functionality)
                            tLZTeamData[AiBotMap.reftObjectiveLocation] = {[AiBotMap.subreftObjLocation] = {tLocation[1], tLocation[2], tLocation[3]}, [AiBotMap.subrefiObjCategoryToBuild] = AiBotUnitInfo.refCategorySMD, [AiBotMap.subrefiObjTechLevelWanted] = 3, [AiBotMap.subrefiNumberWanted] = 1}
                            if bDebugMessages == true then LOG(sFunctionRef..': Added SMD location for Plateau '..iPlateau..'; Zone '..iLandZone) end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': tResearchLocations='..reprs(tResearchLocations)) end
            elseif ScenarioInfo.M1P1.Active then
                --Make sure research centres are added to list of buildings to shield
                local oUnit = ScenarioInfo.ResearchFacility1
                if AiBotUnitInfo.IsUnitValid(oUnit) then AiBotBuilding.CheckIfUnitWantsFixedShield(oUnit, true, 1) end
                oUnit = ScenarioInfo.ResearchFacility2
                if AiBotUnitInfo.IsUnitValid(oUnit) then AiBotBuilding.CheckIfUnitWantsFixedShield(oUnit, true, 1) end
                oUnit = ScenarioInfo.ResearchFacility3
                if AiBotUnitInfo.IsUnitValid(oUnit) then AiBotBuilding.CheckIfUnitWantsFixedShield(oUnit, true, 1) end
            end
            --UEF M6 - check periodically if enemy navy near transport is dead, and if so send transport to load and then unload the truck
        elseif ScenarioInfo.Component == 5 and ScenarioInfo.BlackSun == 2 and AiBotUnitInfo.IsUnitValid(ScenarioInfo.BlackSunComponent) and (ScenarioInfo.M1P2.Active or ScenarioInfo.MissionNumber == 1) then
            ForkThread(UEFBlackSunComponentCheckForTransport)
        elseif ScenarioInfo.M1_TempleCombinedTable and (ScenarioInfo.M1P3.Active or ScenarioInfo.M1P2.Active) then
            if bDebugMessages == true then LOG(sFunctionRef..': Will check if we have Seraphim temples that need manually destroying') end
            if AiBotUtilities.IsTableEmpty(   ScenarioInfo.M1_TempleCombinedTable) == false and AiBotUtilities.IsTableEmpty(tAllActiveAiBotBrains) == false then

                for iUnit, oUnit in ScenarioInfo.M1_TempleCombinedTable do
                    --Add to table of units in the land zone (if it is in a land zone)
                    local iPlateau, iLandZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iPlateau='..(iPlateau or 'nil')..'; iLandZone='..(iLandZone or 'nil')) end
                    if (iLandZone or 0) > 0 then
                        local tLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][iTeam]
                        local bAddToTable = true
                        if not(tLZTeamData[AiBotMap.reftoGroundFireFriendlyTarget]) then tLZTeamData[AiBotMap.reftoGroundFireFriendlyTarget] = {}
                        else
                            for iRecordedUnit, oRecordedUnit in tLZTeamData[AiBotMap.reftoGroundFireFriendlyTarget] do
                                if oRecordedUnit == oUnit then
                                    bAddToTable = false
                                    break
                                end
                            end
                        end
                        if bAddToTable then
                            if bDebugMessages == true then LOG(sFunctionRef..': Added unit to the land zone team table of ground fire targets') end
                            table.insert(tLZTeamData[AiBotMap.reftoGroundFireFriendlyTarget], oUnit)
                        end
                    end
                end
            end
            --Cybran mission 2 - move to gate
        elseif ScenarioInfo.M3P2.Active and ScenarioInfo.M3Gate and AiBotUnitInfo.IsUnitValid(ScenarioInfo.M3Gate) and ScenarioInfo.FakeAeon then
            for iBrain, oBrain in tAllActiveAiBotBrains do
                if not(oBrain.CampaignAI) then
                    local tACUs = oBrain:GetListOfUnits(categories.COMMAND, false, true)
                    if AiBotUtilities.IsTableEmpty(tACUs) == false then
                        for iUnit, oUnit in tACUs do
                            LOG(sFunctionRef..': Considering ACU owned by brain '..oUnit:GetAIBrain().Nickname..'; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; if AiBot then will set objective to gate position='..repru(ScenarioInfo.M3Gate:GetPosition()))
                            oUnit[AiBotACU.reftSpecialObjectiveMoveLocation] = ScenarioInfo.M3Gate:GetPosition()
                        end
                    end
                end
            end
            --Cybran mission 2 - get subs as first naval units (to defend from off-map frigates)
        elseif ScenarioInfo.CybranJanus == 3 and ScenarioInfo.FakeJanus == 6 and ScenarioInfo.M1NETechFound == false and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategorySubmarine) < 10 then
            ForkThread(TellFactoryToBuildSpecificUnitInCampaignMission, iTeam, AiBotUnitInfo.refCategoryNavalFactory, 10, AiBotUnitInfo.refCategorySubmarine)
            --Cybran mission 3 - monitor for trucks and send to the gate
            --NOTE: Also see DeathTriggerAdded
        elseif ScenarioInfo.M2BrackmanTrucksCreated and ScenarioInfo.M2BrackmanTrucksDestroyed and ScenarioInfo.M2P2Complete and ScenarioInfo.M2P1Complete and not(ScenarioInfo.M2P3Complete) and (Target.Units or AiBotUtilities.IsTableEmpty(ScenarioInfo.EscapeConvoy) == false) then
            local rTargetRect = import("/lua/sim/scenarioutilities.lua").AreaToRect('M2_Gate_Delete_Area')
            local tTargetMidpoint = {(rTargetRect['x0'] + rTargetRect['x1'])*0.5 , 0, (rTargetRect['y0'] + rTargetRect['y1'])*0.5}
            ForkThread(UEFMissionSendTruckToTarget, (Target.Units or ScenarioInfo.EscapeConvoy), tTargetMidpoint, 'M2P3Obj', 600)

            --Cybran mission 4 - play defensively and let human player try and capture the nodes
        elseif ScenarioInfo.M3BaseDamageWarnings and ScenarioInfo.MainFrameIsAlive and not ScenarioInfo.EMPFired and (ScenarioInfo.M3_Base or Scenario.Areas['Aeon_Base_M3']) and not(bPacifistModeActive) then
            --Reset base warnings to help AiBot a bit since it can trigger the damage before this objective is even active
            if ScenarioInfo.M3BaseDamageWarnings > 0 then ScenarioInfo.M3BaseDamageWarnings = 0 end
            local tUnitsToConsider = ScenarioInfo.M3_Base
            if not(tUnitsToConsider) then
                local ScenarioFramework = import('/lua/ScenarioFramework.lua')
                tUnitsToConsider = ScenarioFramework.GetCatUnitsInArea(categories.STRUCTURE - categories.WALL, 'Aeon_Base_M3', ArmyBrains[ScenarioInfo.Aeon])
            end
            if AiBotUtilities.IsTableEmpty(tUnitsToConsider) == false then
                if bDebugMessages == true then LOG(sFunctionRef..': Want to disable attacking parts of the map that could cause us to fail the mission') end
                bPacifistModeActive = true

                tiPacifistZonesByPlateau = {}
                toPacifistUnits = {}
                local tbHasPlateauAndZoneBeenRecorded = {}
                local iCurPlateauOrZero, iCurLandOrWaterZone
                for iUnit, oUnit in ScenarioInfo.M3_Base do
                    iCurPlateauOrZero, iCurLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                    if iCurPlateauOrZero and iCurLandOrWaterZone and not(tbHasPlateauAndZoneBeenRecorded[iCurPlateauOrZero][iCurLandOrWaterZone]) then
                        if not(tiPacifistZonesByPlateau[iCurPlateauOrZero]) then tiPacifistZonesByPlateau[iCurPlateauOrZero] = {} end
                        table.insert(tiPacifistZonesByPlateau[iCurPlateauOrZero], iCurLandOrWaterZone)
                        if not(tbHasPlateauAndZoneBeenRecorded[iCurPlateauOrZero]) then tbHasPlateauAndZoneBeenRecorded[iCurPlateauOrZero] = {} end
                        tbHasPlateauAndZoneBeenRecorded[iCurPlateauOrZero][iCurLandOrWaterZone] = true
                    end
                    table.insert(toPacifistUnits, oUnit)
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Finished recording the plateaus and zones that units in M3_Base are in, repru of tiPacifistZonesByPlateau='..repru(tiPacifistZonesByPlateau)) end
                if AiBotUtilities.IsTableEmpty(tiPacifistZonesByPlateau) == false then
                    --Record any adjacent zones
                    local tiAdjacentZonesByPlateau = {}
                    for iPlateauOrZero, tBaseSubtable in tiPacifistZonesByPlateau do
                        for iEntry, iLandOrWaterZone in tBaseSubtable do
                            local tLZOrWZData
                            if iPlateauOrZero == 0 then
                                tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
                                --Water zone: Adjacent land zones
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering water zone '..iLandOrWaterZone..'; Is table of adjacent land zones empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefAdjacentLandZones]))) end
                                if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefAdjacentLandZones]) == false then
                                    for iEntry, tSubtable in tLZOrWZData[AiBotMap.subrefAdjacentLandZones] do
                                        local iPlateauRef = tSubtable[AiBotMap.subrefWPlatAndLZNumber][1]
                                        local iAdjZoneRef = tSubtable[AiBotMap.subrefWPlatAndLZNumber][2]
                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjZoneRef='..iAdjZoneRef..'; iPlateauRef='..iPlateauRef) end
                                        if not(tbHasPlateauAndZoneBeenRecorded[iPlateauRef][iAdjZoneRef]) then
                                            tbHasPlateauAndZoneBeenRecorded[iPlateauRef][iAdjZoneRef] = true
                                            if not(tiAdjacentZonesByPlateau[iPlateauRef]) then tiAdjacentZonesByPlateau[iPlateauRef] = {} end
                                            if bDebugMessages == true then LOG(sFunctionRef..': Adding iAdjZoneRef='..iAdjZoneRef..'; to table') end
                                            table.insert(tiAdjacentZonesByPlateau[iPlateauRef], iAdjZoneRef)
                                        end
                                    end
                                end
                                --Water zone: Adjacent water zones:
                                if bDebugMessages == true then LOG(sFunctionRef..': Is table of adjacent water zones empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefWZAdjacentWaterZones]))) end
                                if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefWZAdjacentWaterZones]) == false then
                                    for _, iAdjZoneRef in tLZOrWZData[AiBotMap.subrefWZAdjacentWaterZones] do
                                        if not(tbHasPlateauAndZoneBeenRecorded[0][iAdjZoneRef]) then
                                            if not(tbHasPlateauAndZoneBeenRecorded[0]) then tbHasPlateauAndZoneBeenRecorded[0] = {} end
                                            tbHasPlateauAndZoneBeenRecorded[0][iAdjZoneRef] = true
                                            if not(tiAdjacentZonesByPlateau[0]) then tiAdjacentZonesByPlateau[0] = {} end
                                            if bDebugMessages == true then LOG(sFunctionRef..': Adding WZ iAdjZoneRef='..iAdjZoneRef..'; to table') end
                                            table.insert(tiAdjacentZonesByPlateau[0], iAdjZoneRef)
                                        end
                                    end
                                end
                            else
                                tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
                                --Land zone: Adjacent land zones
                                if bDebugMessages == true then LOG(sFunctionRef..': Dealing with land zone, is table of adjacent land zones empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones]))) end
                                if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                    for _, iAdjZoneRef in tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones] do
                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjZoneRef='..iAdjZoneRef..' in iPlateuOrZero='..iPlateauOrZero) end
                                        if not(tbHasPlateauAndZoneBeenRecorded[iPlateauOrZero][iAdjZoneRef]) then
                                            if not(tbHasPlateauAndZoneBeenRecorded[iPlateauOrZero]) then tbHasPlateauAndZoneBeenRecorded[iPlateauOrZero] = {} end
                                            tbHasPlateauAndZoneBeenRecorded[iPlateauOrZero][iAdjZoneRef] = true
                                            if not(tiAdjacentZonesByPlateau[iPlateauOrZero]) then tiAdjacentZonesByPlateau[iPlateauOrZero] = {} end
                                            if bDebugMessages == true then LOG(sFunctionRef..': Adding LZ iAdjZoneRef='..iAdjZoneRef..'; to table') end
                                            table.insert(tiAdjacentZonesByPlateau[iPlateauOrZero], iAdjZoneRef)
                                        end
                                    end
                                end
                                --Land zone: Adjacent water zone:
                                if bDebugMessages == true then LOG(sFunctionRef..': Is table of adjacent water zones empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefAdjacentWaterZones]))) end
                                if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefAdjacentWaterZones]) == false then
                                    for iEntry, tSubtable in tLZOrWZData[AiBotMap.subrefAdjacentWaterZones] do
                                        local iAdjZoneRef = tSubtable[AiBotMap.subrefAWZRef]
                                        if not(tbHasPlateauAndZoneBeenRecorded[0][iAdjZoneRef]) then
                                            if not(tbHasPlateauAndZoneBeenRecorded[0]) then tbHasPlateauAndZoneBeenRecorded[0] = {} end
                                            tbHasPlateauAndZoneBeenRecorded[0][iAdjZoneRef] = true
                                            if not(tiAdjacentZonesByPlateau[0]) then tiAdjacentZonesByPlateau[0] = {} end
                                            if bDebugMessages == true then LOG(sFunctionRef..': Adding WZ iAdjZoneRef='..iAdjZoneRef..'; to table') end
                                            table.insert(tiAdjacentZonesByPlateau[0], iAdjZoneRef)
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': About to add adjacent zones to core zone, tiAdjacentZonesByPlateau='..repru(tiAdjacentZonesByPlateau)) end
                    if AiBotUtilities.IsTableEmpty(tiAdjacentZonesByPlateau) == false then
                        for iPlateauOrZero, tSubtable in tiAdjacentZonesByPlateau do
                            for iEntry, iAdjZoneRef in tSubtable do
                                if not(tiPacifistZonesByPlateau[iPlateauOrZero]) then tiPacifistZonesByPlateau[iPlateauOrZero] = {} end
                                if bDebugMessages == true then LOG(sFunctionRef..': Adding iAdjZoneRef='..iAdjZoneRef..' for iPlateauOrZero='..iPlateauOrZero) end
                                table.insert(tiPacifistZonesByPlateau[iPlateauOrZero], iAdjZoneRef)
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Finished adding adjacent zones, repru of adjacent zones by plateau='..repru(tiAdjacentZonesByPlateau)) end

                    for iPlateauOrZero, tSubtable in tiPacifistZonesByPlateau do
                        for iEntry, iLandOrWaterZone in tSubtable do
                            local tLZOrWZData
                            if iPlateauOrZero == 0 then
                                tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
                            else
                                tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
                            end
                            tLZOrWZData[AiBotMap.subrefbPacifistArea] = true
                            if bDebugMessages == true then LOG(sFunctionRef..': Set pacifist flag to true for iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone) end
                        end
                    end
                end
                tAveragePacifistLocation = AiBotUtilities.GetAverageOfUnitPositions(toPacifistUnits)
            end
            --Cybran mission 4 - disable pacifist flag once emp fired
        elseif bPacifistModeActive and ScenarioInfo.EMPFired and AiBotUtilities.IsTableEmpty(tiPacifistZonesByPlateau) == false then
            --Disable pacifist flag
            if bDebugMessages == true then LOG(sFunctionRef..': EMP has been fired so will disable pacifist flag for all recorded zones, tiPacifistZonesByPlateau='..repru(tiPacifistZonesByPlateau)) end
            bPacifistModeActive = false
            for iPlateauOrZero, tSubtable in tiPacifistZonesByPlateau do
                local tLZOrWZData
                for iEntry, iLandOrWaterZone in tSubtable do
                    if iPlateauOrZero == 0 then
                        tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
                    else
                        tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
                    end
                    tLZOrWZData[AiBotMap.subrefbPacifistArea] = false
                end
            end
            --Cybran mission 5 - get subs near start to help vs enemy UEF destroyer
        elseif ScenarioInfo.FauxUEF == 4 and ScenarioInfo.Hex5 == 3 and not(ScenarioInfo.M1P1Complete) then
            ForkThread(TellFactoryToBuildSpecificUnitInCampaignMission, iTeam, AiBotUnitInfo.refCategoryNavalFactory, 10, AiBotUnitInfo.refCategorySubmarine)
            --Cybran mission 5 - send ACU to get codes from Hex5
        elseif ScenarioInfo.FauxUEF == 4 and ScenarioInfo.Hex5 == 3 and not(ScenarioInfo.M2P2Complete) and ScenarioInfo.M2P1Complete == true then
            SendACUsToCampaignObjective('M2_Hex5ObjectiveMarker')
            --Cybran mission 6 - activate black sun (below is as a redundancy but doesnt actually trigger - are reliant on the oncapture event instead)
        elseif ScenarioInfo.M3P2.Active and AiBotUnitInfo.IsUnitValid(ScenarioInfo.BlackSunWeapon) and ScenarioInfo.BlackSunWeapon:GetAIBrain().AiBotAI and ScenarioInfo.BlackSunWeapon:GetAIBrain():GetFactionIndex() == AiBotUnitInfo.refFactionCybran then
            if bDebugMessages == true then LOG(sFunctionRef..' Cybran M6 Want to fire black sun to complete cybran campaign - will fire in a bit') end
            ForkThread(DelayedCybranFireBlackSun, ScenarioInfo.BlackSunWeapon:GetAIBrain())
            --Cybran mission 6 - kill Czar
        elseif ScenarioInfo.ControlCenter and ScenarioInfo.Czar and AiBotUtilities.IsTableEmpty(ScenarioInfo.Czar) == false and ScenarioInfo.M1P1.Active then
            if bDebugMessages == true then LOG(sFunctionRef..': Cybran M6 Want to focus on killing czar') end
            function DelayedRecordingOfCzar(tUnits)
                WaitSeconds(15)
                if bDebugMessages == true then LOG(sFunctionRef..': Finished waiting, time='..GetGameTimeSeconds()..' is table of units empty='..tostring(AiBotUtilities.IsTableEmpty(tUnits))) end
                if AiBotUtilities.IsTableEmpty(tUnits) == false then
                    for iUnit, oUnit in tUnits do
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering unit '..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))) end
                        if AiBotUnitInfo.IsUnitValid(oUnit) then
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryAllAir * categories.EXPERIMENTAL, oUnit.UnitId) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Will record enemy Czar as a priority enemy air experimental target unless it is alrady recorded') end
                                local bAlreadyIncluded = false
                                if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyExperimentalAirObjectives]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyExperimentalAirObjectives] = {}
                                else
                                    for iRecordedUnit, oRecordedUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyExperimentalAirObjectives] do
                                        if oRecordedUnit == oUnit then bAlreadyIncluded = true break end
                                    end
                                end
                                if not(bAlreadyIncluded) then
                                    table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyExperimentalAirObjectives], oUnit)
                                end
                            end
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Will wait a while and then look to include enemy Czar as a priority enemy air experimental target unless it is alrady recorded') end
            local tUnits = {}
            --Work whether Czar is a table or a isngle unit
            if AiBotUnitInfo.IsUnitValid(ScenarioInfo.Czar) and ScenarioInfo.Czar.UnitId then table.insert(tUnits, ScenarioInfo.Czar)
            else tUnits = ScenarioInfo.Czar
            end
            ForkThread(DelayedRecordingOfCzar, tUnits)
            --Cybran M6 - send ACU to quantum gateway to download virus, and flag to build more SMD
        elseif ScenarioInfo.M2P2.Active and ScenarioInfo.Aeon == 2 and ScenarioInfo.UEF == 3 and ScenarioInfo.BlackSun == 4 and ScenarioInfo.Cybran == 5 and ScenarioInfo.Player1CDR and EntityCategoryContains(categories.CYBRAN, ScenarioInfo.Player1CDR.UnitId) then
            if bDebugMessages == true then LOG(sFunctionRef..': Cybran M6 Will send ACU to gateway and record we want more SMD') end
            ForkThread(CybranM6SendCampaignACUToNearestGateway)
            --Record we want more SMD
            local oAiBotBrain = GetAiBotBrainForCampaignObjective()
            if oAiBotBrain then
                local tStart = AiBotMap.GetPlayerStartPosition(oAiBotBrain)
                if tStart then
                    local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tStart)
                    if iPlateauOrZero > 0 and (iLandOrWaterZone or 0) > 0 then
                        local tLZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZTeamData][iTeam]
                        tLZTeamData[AiBotMap.reftObjectiveLocation] = {[AiBotMap.subreftObjLocation] = {tStart[1], GetSurfaceHeight(tStart[1], tStart[3]), tStart[3]}, [AiBotMap.subrefiObjCategoryToBuild] = AiBotUnitInfo.refCategorySMD, [AiBotMap.subrefiObjTechLevelWanted] = 3, [AiBotMap.subrefiObjLocationSize] = 80, [AiBotMap.subrefiNumberWanted] = 7}
                        if bDebugMessages == true then LOG(sFunctionRef..': Recording we want 7 SMD for P'..iPlateauOrZero..'Z'..iLandOrWaterZone) end
                    end
                end
            end

            --Cybran M6 - periodically suicide an engineer to capture control centrue (as constant enemy attacks mean it is almost impossible for AiBot to get all reclaim and finish building things it wants before capturing)
        elseif ScenarioInfo.M2P3.Active and ScenarioInfo.ControlCenter and ScenarioInfo.Player1CDR and EntityCategoryContains(categories.CYBRAN, ScenarioInfo.Player1CDR.UnitId) then
            if bDebugMessages == true then LOG(sFunctionRef..': Cybran M6 WIll periodically send an engineer to capture the control centre') end
            ForkThread(PeriodicallySendEngineerToCaptureTarget, ScenarioInfo.ControlCenter)
            --Cybran M6 start - get battleships
        elseif ScenarioInfo.Player1CDR and EntityCategoryContains(categories.CYBRAN, ScenarioInfo.Player1CDR.UnitId) and ScenarioInfo.BlackSun == 4 and ScenarioInfo.Aeon == 2 and ScenarioInfo.UEF == 3 and not(ScenarioInfo.M1P1Complete) and GetGameTimeSeconds() <= 300 then
            if bDebugMessages == true then LOG(sFunctionRef..': Cybran M6, M1P1complete='..tostring(ScenarioInfo.M1P1Complete or false)..'; will try to get battleships') end
            ForkThread(TellFactoryToBuildSpecificUnitInCampaignMission, iTeam, AiBotUnitInfo.refCategoryNavalFactory, 1, AiBotUnitInfo.refCategoryNavalAA * categories.TECH3, 2, AiBotUnitInfo.refCategoryBattleship)
            --Aeon Mission 1 workaround for bug in mission preventing it from ending
        elseif ScenarioInfo.M7_FauxUEFCommanderUnit then
            ForkThread(M1AeonEndMissionBackupMonitor)
            --Aeon M2 - get pd early on and engis to build them
        elseif ScenarioInfo.NeutralCybran == 3 and ScenarioInfo.Cybran == 2 and  ScenarioInfo.M1P1Objective.Active and GetGameTimeSeconds() <= 300 then
            local oAiBotBrain = GetAiBotBrainForCampaignObjective()
            if oAiBotBrain then
                local tStart = AiBotMap.GetPlayerStartPosition(oAiBotBrain)
                if tStart then
                    local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tStart)
                    if bDebugMessages == true then LOG(sFunctionRef..': Checking if have start with valid zone, iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')) end
                    if iPlateauOrZero > 0 and (iLandOrWaterZone or 0) > 0 then
                        local tLZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZTeamData][iTeam]
                        tLZTeamData[AiBotMap.reftObjectiveLocation] = {[AiBotMap.subreftObjLocation] = {tStart[1], GetSurfaceHeight(tStart[1], tStart[3]), tStart[3]}, [AiBotMap.subrefiObjCategoryToBuild] = AiBotUnitInfo.refCategoryPD, [AiBotMap.subrefiObjTechLevelWanted] = 1, [AiBotMap.subrefiObjLocationSize] = 80, [AiBotMap.subrefiNumberWanted] = 1}
                        tLZTeamData[AiBotMap.subrefLZFortify] = true
                        if bDebugMessages == true then LOG(sFunctionRef..': Recording we want 2 PD for P'..iPlateauOrZero..'Z'..iLandOrWaterZone) end
                    end
                end
            end
            ForkThread(TellFactoryToBuildSpecificUnitInCampaignMission, iTeam, AiBotUnitInfo.refCategoryLandFactory, 5, AiBotUnitInfo.refCategoryEngineer, 2, AiBotUnitInfo.refCategoryMAA)
            --Aeon Mission 3 - get gun upgrade asap and subs
        elseif ScenarioInfo.Eris == 3 and ScenarioInfo.UEF == 2 and ScenarioInfo.Player2 == 4 and GetGameTimeSeconds() <= 360 then
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftAiBotACUs]) == false then
                for iACU, oACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftAiBotACUs] do
                    oACU[AiBotACU.refbWantsPriorityUpgrade] = true
                end
            end
            TellFactoryToBuildSpecificUnitInCampaignMission(iTeam, AiBotUnitInfo.refCategoryNavalFactory, 23, AiBotUnitInfo.refCategoryNavalAA,20,  AiBotUnitInfo.refCategorySubmarine)
            --Aeon mission 5 - build UEF T3 shield
        elseif ScenarioInfo.M1P1Obj.Active and Target.MarkArea and Target.Requirements and Target.Category == categories.uab4301 then
            AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] = true
            AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount] = 1
            if bDebugMessages == true then LOG(sFunctionRef..': Want to build T3 shielding for Aeon M5') end
            local iOurBrainIndex = AiBotTeam.GetFirstActiveAiBotBrain(iTeam):GetArmyIndex()
            for iTarget, tRequirements in Target.Requirements do
                local tRect = import("/lua/sim/scenarioutilities.lua").AreaToRect(tRequirements.Area)
                local tBaseAreaForRect = {tRect['x0'], tRect['y0'], tRect['x1'], tRect['y1']}
                if bDebugMessages == true then LOG(sFunctionRef..': rRect='..repru(tBaseAreaForRect)..'; tRequirements.Area='..reprs(tRequirements.Area)..'; AreaToRect='..repru(import("/lua/sim/scenarioutilities.lua").AreaToRect(tRequirements.Area))) end
                if tBaseAreaForRect then
                    local iRadiusAdjust = -16
                    local rRect = Rect(tBaseAreaForRect[1] - iRadiusAdjust, tBaseAreaForRect[2] - iRadiusAdjust, tBaseAreaForRect[3] + iRadiusAdjust, tBaseAreaForRect[4] + iRadiusAdjust)
                    if bDebugMessages == true then LOG(sFunctionRef..': rRect to search after adjust='..repru(rRect)) end
                    local tUnitsInRect = GetUnitsInRect(rRect)
                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of units in rec empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsInRect))) end
                    if AiBotUtilities.IsTableEmpty(tUnitsInRect) == false then
                        local tBuildingsInRect = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryStructure, tUnitsInRect)
                        if bDebugMessages == true then LOG(sFunctionRef..': Is table of tBuildingsInRect empty='..tostring(AiBotUtilities.IsTableEmpty(tBuildingsInRect))) end
                        if AiBotUtilities.IsTableEmpty(tBuildingsInRect) == false then
                            for iUnit, oUnit in tBuildingsInRect do
                                if not(IsEnemy(oUnit:GetAIBrain():GetArmyIndex(), iOurBrainIndex)) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Sending unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to function to assign shielding requirement') end
                                    AiBotBuilding.CheckIfUnitWantsFixedShield(oUnit, true, 1)
                                end
                            end
                        end
                    end
                    local tMidpoint = {(tBaseAreaForRect[1] + tBaseAreaForRect[3]) * 0.5, 0, (tBaseAreaForRect[2] + tBaseAreaForRect[4]) * 0.5}
                    local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tMidpoint)
                    local tMidpointLZData, tMidpointLZTeamData = AiBotMap.GetLandOrWaterZoneData(tMidpoint, true, iTeam)

                    tMidpointLZTeamData[AiBotMap.subrefLZFortify] = true
                    if bDebugMessages == true then LOG(sFunctionRef..': Changing P'..iPlateauOrZero..'Z'..iLandOrWaterZone..' midppoint from '..repru(tMidpointLZData[AiBotMap.subrefMidpoint])..' to '..repru(tMidpoint)) end
                    tMidpointLZData[AiBotMap.subrefMidpoint] = {tMidpoint[1], tMidpoint[2], tMidpoint[3]}
                    local iTotalSegments = table.getn(tMidpointLZData[AiBotMap.subrefLZSegments])
                    local iSegmentStart = (tMidpointLZData[AiBotMap.subrefiLastSegmentEntryConsideredForBuilding] or 0)
                    if bDebugMessages == true then LOG(sFunctionRef..': Rect Midpoint='..repru(tMidpoint)..'; iLandOrWaterZone='..iLandOrWaterZone..'; iTotalSegments='..iTotalSegments..'; iSegmentStart='..iSegmentStart) end
                    local iCurCycleCount = 0
                    local iWaitCycleCount = 0
                    while iSegmentStart < iTotalSegments * 0.9 do
                        iCurCycleCount = iCurCycleCount + 1
                        iWaitCycleCount = iWaitCycleCount + 1
                        if iWaitCycleCount >= 100 then
                            iWaitCycleCount = 0
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            WaitTicks(1)
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                        end
                        if iCurCycleCount >= 10000 then break end
                        AiBotEngineer.SearchForBuildableLocationsForLandOrWaterZone(aiBrain, iPlateauOrZero, iLandOrWaterZone, math.min(100, math.floor(iTotalSegments * 0.1)))
                        iTotalSegments = table.getn(tMidpointLZData[AiBotMap.subrefLZSegments])
                        iSegmentStart = (tMidpointLZData[AiBotMap.subrefiLastSegmentEntryConsideredForBuilding] or 0)
                        if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; iTotalSegments='..iTotalSegments..'; iSegmentStart='..iSegmentStart) end
                    end
                end
            end

            --Aeon Mission 5 - build SMD
        elseif ScenarioInfo.M1P2Obj.Active and Target.MarkArea and Target.Category == categories.uab4302 and Target.Areas then
            local ScenarioUtilities = import("/lua/sim/scenarioutilities.lua")

            for iArea, sArea in Target.Areas do
                local tRect = ScenarioUtilities.AreaToRect(sArea)
                local tBaseAreaForRect = {tRect['x0'], tRect['y0'], tRect['x1'], tRect['y1']}
                if bDebugMessages == true then LOG(sFunctionRef..': tRect='..repru(tRect)..'; tBaseAreaForRect='..repru(tBaseAreaForRect)..'; sArea='..sArea) end
                if tBaseAreaForRect then
                    local tMidpoint = {(tBaseAreaForRect[1] + tBaseAreaForRect[3]) * 0.5, 0, (tBaseAreaForRect[2] + tBaseAreaForRect[4]) * 0.5}
                    local iSize = math.min(tBaseAreaForRect[3] - tBaseAreaForRect[1], tBaseAreaForRect[4] - tBaseAreaForRect[2]) * 0.5
                    local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tMidpoint)
                    if iPlateauOrZero > 0 and (iLandOrWaterZone or 0) > 0 then
                        local tMidpointLZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZTeamData][iTeam]
                        tMidpointLZTeamData[AiBotMap.reftObjectiveLocation] = {[AiBotMap.subreftObjLocation] = {tMidpoint[1], GetSurfaceHeight(tMidpoint[1], tMidpoint[3]), tMidpoint[3]}, [AiBotMap.subrefiObjCategoryToBuild] = AiBotUnitInfo.refCategorySMD, [AiBotMap.subrefiObjTechLevelWanted] = 3, [AiBotMap.subrefiObjLocationSize] = iSize, [AiBotMap.subrefiNumberWanted] = 1}
                        if bDebugMessages == true then LOG(sFunctionRef..': Set SMD location for iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone..'; Location='..repru(tMidpointLZTeamData[AiBotMap.reftObjectiveLocation])) end
                    end

                end
            end
            --SC Aeon Mission 5 - UEF changing sides
        elseif ScenarioInfo.M2P1Obj.Active and ScenarioInfo.Ariel and ScenarioInfo.Colonies and not(tbSpecialCodeForMission[21]) then
            tbSpecialCodeForMission[21] = true
            --Have had a change in factions, update all unit tables
            if bDebugMessages == true then LOG(sFunctionRef..': Will update recorded units following uef alliance changes so arti is detected, changing sides, Time='..GetGameTimeSeconds()) end
            ForkThread(UpdateAllRecordedUnitsFollowingTeamChange)
            --Aeon mission 6 - prioritise battleships and carriers; also periodically send engineer to try and capture
        elseif ScenarioInfo.UEF == 2 and ScenarioInfo.Aeon == 4 and ScenarioInfo.Cybran == 3 and ScenarioInfo.Neutral == 5 and not(ScenarioInfo.M1P1Objective.Complete) and not(ScenarioInfo.M1P2Objective.Active) then
            if bDebugMessages == true then LOG(sFunctionRef..': Will prioritise building carrier and battleships for start of Aeon M6') end
            TellFactoryToBuildSpecificUnitInCampaignMission(iTeam, AiBotUnitInfo.refCategoryNavalFactory, 1, AiBotUnitInfo.refCategoryCarrier, 4, AiBotUnitInfo.refCategoryBattleship)
            --After 45m consider sending engineers
            if ScenarioInfo.BlackSunControlCenter then
                ForkThread(PeriodicallySendEngineerToCaptureTarget, ScenarioInfo.BlackSunControlCenter, ScenarioInfo.M1P1Objective, 2700)
            end
            --FA M1 - build T2 AA by the shield, and rush T3 HQ
        elseif ScenarioInfo.M1ObjectiveShield and ScenarioInfo.Seraphim == 2 and ScenarioInfo.Order == 3 and ScenarioInfo.UEF == 4 and not(ScenarioInfo.M2P1.Active) and not(ScenarioInfo.M2P1.Complete) then
            if bDebugMessages == true then LOG(sFunctionRef..': Will look to build AA under shield if M1S2 is active or it is start of game (i.e. havent even been given the objective yet), or if not will upgrade facs to t2, ScenarioInfo.M1S2.Active='..tostring(ScenarioInfo.M1S2.Active or false)) end
            --if ScenarioInfo.M1S2.Active then
            if not(ScenarioInfo.M1S2.Complete) then
                local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(ScenarioInfo.M1ObjectiveShield:GetPosition())
                if iPlateauOrZero > 0 and (iLandOrWaterZone or 0) > 0 then
                    local tMidpointLZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZTeamData][iTeam]
                    tMidpointLZTeamData[AiBotMap.reftObjectiveLocation] = {[AiBotMap.subreftObjLocation] = ScenarioInfo.M1ObjectiveShield:GetPosition(), [AiBotMap.subrefiObjCategoryToBuild] = categories.ANTIAIR * categories.STRUCTURE * categories.ANTIAIR - categories.TECH1, [AiBotMap.subrefiObjTechLevelWanted] = 2, [AiBotMap.subrefiObjLocationSize] = 15, [AiBotMap.subrefiNumberWanted] = 2}
                    if bDebugMessages == true then LOG(sFunctionRef..': Setting to build 2 T2 AA at objective location for iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone..'; Location='..repru(tMidpointLZTeamData[AiBotMap.reftObjectiveLocation])) end
                end
            end
            if not(ScenarioInfo.M1S2.Active) then
                --Start of game
                ForkThread(TellFactoryToBuildSpecificUnitInCampaignMission, iTeam, AiBotUnitInfo.refCategoryLandFactory * categories.TECH1, 1, AiBotUnitInfo.refCategoryLandHQ * categories.TECH2, nil, nil, nil, nil, 'T2Land')
                ForkThread(TellFactoryToBuildSpecificUnitInCampaignMission, iTeam, AiBotUnitInfo.refCategoryLandFactory * categories.TECH2, 8, AiBotUnitInfo.refCategoryEngineer * categories.TECH2, 1, AiBotUnitInfo.refCategoryLandHQ * categories.TECH3, nil, nil, 'T2LEng')
                ForkThread(TellFactoryToBuildSpecificUnitInCampaignMission, iTeam, AiBotUnitInfo.refCategoryAirFactory * categories.TECH1, 1, AiBotUnitInfo.refCategoryAirHQ * categories.TECH2, nil, nil, nil, nil, 'T2Air')
                ForkThread(TellFactoryToBuildSpecificUnitInCampaignMission, iTeam, AiBotUnitInfo.refCategoryAirFactory * categories.TECH2, 8, AiBotUnitInfo.refCategoryEngineer * categories.TECH2, 1, AiBotUnitInfo.refCategoryAirHQ * categories.TECH3, nil, nil, 'T2AEng')
            end
            --Use gunships more aggressively once built up a decent force
            AiBotTeam.tTeamData[iTeam][AiBotTeam.refbActiveDefenseObjective] = true
            --FA M1 - once defended civilians remove gunship aggression flag
        elseif ScenarioInfo.Seraphim == 2 and ScenarioInfo.Order == 3 and ScenarioInfo.UEF == 4 and ScenarioInfo.M1P1.Complete and (ScenarioInfo.M2CivilianBuildings or ScenarioInfo.M1ObjectiveShield or ScenarioInfo.M3CivilianCity or ScenarioInfo.Incarna1) then
            if ScenarioInfo.M2P1.Active then AiBotTeam.tTeamData[iTeam][AiBotTeam.refbActiveDefenseObjective] = true
            elseif ScenarioInfo.M2P1.Complete or AiBotUtilities.IsTableEmpty(ScenarioInfo.M2CivilianBuildings) then AiBotTeam.tTeamData[iTeam][AiBotTeam.refbActiveDefenseObjective] = false
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Will set gunship aggression flag depending on if M2P1 is active, refbActiveDefenseObjective='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbActiveDefenseObjective] or false)) end
            --end
            --FA M2 Dawn - update enemy unit tables after brief delay
        elseif ScenarioInfo.QAICommander and ScenarioInfo.M4P1.Active and not(tbSpecialCodeForMission[41]) then
            tbSpecialCodeForMission[41] = true
            --Have had a change in factions, update all unit tables
            if bDebugMessages == true then LOG(sFunctionRef..': ScenarioInfo.OrderAlly='..tostring(ScenarioInfo.OrderAlly or false)..'; Time='..GetGameTimeSeconds()) end
            ForkThread(UpdateAllRecordedUnitsFollowingTeamChange, ScenarioInfo.OrderAlly)
            --Dawn (FA Mission 2) - add redundancy so upgraidng facotires doesnt break the objective - solved via callback appraoch instead
            --[[elseif AiBotUtilities.IsTableEmpty(ScenarioInfo.M1P1Units) == false and not(ScenarioInfo.M1P2.Active) and ScenarioInfo.M1P1.Active then
                --Monitor the M1P1 units and remove any that become obsolete
                LOG(sFunctionRef..': Want to monitor ScenarioInfo.M1P1Units units, will list out each unit, is table empty='..tostring(ScenarioInfo.M1P1Units))
                for iUnit, oUnit in ScenarioInfo.M1P1Units do
                    LOG(sFunctionRef..': iUnit='..iUnit..'; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Is valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit)))
                end
                ForkThread(MonitorObjectiveUnitsAndRemoveIfDead, ScenarioInfo.M1P1Units, 1, ScenarioInfo.M1P1)
                --]]
            --Dawn (FA Mission 2) - redundancy for case where first objective (kill attack) is done but second (destroy order base) doesnt trigger - commented out as in the particular case this function (i.e. considering special campaign objectives) only triggers when the attack wave is still alive, and doesnt trigger when the units die
            --[[elseif ScenarioInfo.M1P1Units and ScenarioInfo.M1OrderAttack and not(ScenarioInfo.M1P2.Active) then
                --If we have alive units in M1P1Units then are still scenario 1
                local bHaveAliveBaseUnits = false
                local bHaveAliveAttackUnits = false
                for iUnit, oUnit in ScenarioInfo.M1OrderAttack do
                    if not(oUnit.Dead) then bHaveAliveAttackUnits = true break end
                end
                for iUnit, oUnit in ScenarioInfo.M1P1Units do
                    if not(oUnit.Dead) then
                        bHaveAliveBaseUnits = true
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': bHaveAliveAttackUnits='..tostring(bHaveAliveAttackUnits)..'; bHaveAliveBaseUnits='..tostring(bHaveAliveBaseUnits)..'; ScenarioInfo.M1P1.Active='..tostring(ScenarioInfo.M1P1.Active or false)) end
                if not(bHaveAliveAttackUnits) and bHaveAliveBaseUnits then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will do delayed check if mission active') end
                    WaitSeconds(300)
                    if not(ScenarioInfo.M1P2.Active) then
                        ScenarioInfo.M1P1:ManualResult(true)
                    end
                end--]]
            --FA M3 (Saving rihanne) - dont adjust orders of engineers building exp bombers for a while
        elseif ScenarioInfo.ExperimentalEngineers and AiBotUtilities.IsTableEmpty(ScenarioInfo.ExperimentalEngineers) == false then
            if bDebugMessages == true then LOG(sFunctionRef..': ScenarioInfo.M1P1.Active='..tostring(ScenarioInfo.M1P1.Active or false)..'; ScenarioInfo.M2P1.Active='..tostring(ScenarioInfo.M2P1.Active or false)..'; M3P1='..tostring(ScenarioInfo.M3P1.Active or false)..'; Time='..GetGameTimeSeconds()) end
            if ScenarioInfo.M2P1.Active or ScenarioInfo.M1P1.Active then
                for iEngi, oEngi in ScenarioInfo.ExperimentalEngineers do
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering tracking engineer oEngi='..oEngi.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngi)..'; oEngi[AiBotUnitInfo.refbSpecialMicroActive]='..tostring(oEngi[AiBotUnitInfo.refbSpecialMicroActive] or false)) end
                    oEngi[AiBotUnitInfo.refbCampaignNeverPause] = true
                    if AiBotUnitInfo.IsUnitValid(oEngi) then
                        if oEngi[AiBotUnitInfo.refbPaused] or (oEngi.IsPaused and oEngi:IsPaused()) then AiBotUnitInfo.PauseOrUnpauseMassUsage(oEngi, false) end
                        if bDebugMessages == true then LOG(sFunctionRef..': Will track special micro') end
                        if not(oEngi[AiBotUnitInfo.refbSpecialMicroActive]) then
                            AiBotMicro.TrackTemporaryUnitMicro(oEngi, 180, nil, false)
                        end
                        if ScenarioInfo.M2P1.Active then
                            AiBotEngineer.TrackEngineerAction(oEngi, AiBotEngineer.refActionBuildExperimental, true, 1, nil, nil, false)
                        end
                    end
                end
            else
                for iEngi, oEngi in ScenarioInfo.ExperimentalEngineers do
                    if bDebugMessages == true then LOG(sFunctionRef..': Will remove special micro flags from engis') end
                    oEngi[AiBotUnitInfo.refbCampaignNeverPause] = nil
                    oEngi[AiBotUnitInfo.refbSpecialMicroActive] = false
                end
            end

            --FA M4 - prioritise early T2 land
        elseif ScenarioInfo.Dostya == 2 and ScenarioInfo.Seraphim == 3 and ScenarioInfo.SeraphimSecondary == 4 and not(ScenarioInfo.M1P1.Complete) then
            ForkThread(TellFactoryToBuildSpecificUnitInCampaignMission, iTeam, AiBotUnitInfo.refCategoryLandFactory, 5, AiBotUnitInfo.refCategoryEngineer, 1, AiBotUnitInfo.refCategoryLandFactory * categories.TECH2, nil, nil, 'T2Land')
            --UEF and Cybran - get skirmishers
            ForkThread(TellFactoryToBuildSpecificUnitInCampaignMission, iTeam, AiBotUnitInfo.refCategoryLandFactory * categories.TECH2, 2, AiBotUnitInfo.refCategoryLandScout, 3, AiBotUnitInfo.refCategorySkirmisher * categories.TECH2, nil, nil, 'T2Skirmish')
            --FA M5 start of game
        elseif ScenarioInfo.Brackman == 8 and ScenarioInfo.Hex5 == 3 and ScenarioInfo.AeonArmy == 5 and not( ScenarioInfo.M1P1.Complete) then
            ForkThread(TellFactoryToBuildSpecificUnitInCampaignMission, iTeam, AiBotUnitInfo.refCategoryLandFactory, 5, AiBotUnitInfo.refCategoryEngineer, 1, AiBotUnitInfo.refCategoryMobileDFLand, 1, AiBotUnitInfo.refCategoryLandFactory * categories.TECH2, 'T2Land')

            --FA M6 - Fletcher changing sides
        elseif ScenarioInfo.M2P1.Active and ScenarioInfo.FletcherACU and not(tbSpecialCodeForMission[21]) then
            tbSpecialCodeForMission[21] = true
            --Have had a change in factions, update all unit tables
            if bDebugMessages == true then LOG(sFunctionRef..': Will update recorded units following fletcher changing sides, Time='..GetGameTimeSeconds()) end
            ForkThread(UpdateAllRecordedUnitsFollowingTeamChange)
            --Seraphim M3 - protect QAI mainframe (as objective currently has strange way of doing this where it tracks the area rather htan the unit)
        elseif ScenarioInfo.M4P3.Active and Target.Requirements[1].Category == categories.urc1901 and Target.Requirements[1].Area then

            local ScenarioUtilities = import("/lua/sim/scenarioutilities.lua")
            local tRect = ScenarioUtilities.AreaToRect(Target.Requirements[1].Area)
            local tBaseAreaForRect = {tRect['x0'], tRect['y0'], tRect['x1'], tRect['y1']}
            if bDebugMessages == true then LOG(sFunctionRef..': Will add QAI mainframe as a priority defence target, tRect='..repru(tRect)..';tBaseAreaForRect='..repru(tBaseAreaForRect)..'; Target.Requirements[1].Area='..(Target.Requirements[1].Area or 'nil')) end
            local tUnitsInRect = GetUnitsInRect(tRect)
            if bDebugMessages == true then LOG(sFunctionRef..': Is tUnitsInRect empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsInRect))) end
            if AiBotUtilities.IsTableEmpty(tUnitsInRect) == false then
                local tQAIMainframes = EntityCategoryFilterDown(Target.Requirements[1].Category, tUnitsInRect)
                if bDebugMessages == true then LOG(sFunctionRef..': Is tQAIMainframes empty='..tostring(AiBotUtilities.IsTableEmpty(tQAIMainframes))) end
                if AiBotUtilities.IsTableEmpty(tQAIMainframes) == false then
                    for iUnit, oUnit in tQAIMainframes do
                        if bDebugMessages == true then LOG(sFunctionRef..': Adding unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' as a priority air defence target') end
                        AiBotAir.AddPriorityAirDefenceTarget(oUnit)
                    end
                end
            end

            --Operation trident - dont reclaim the civilians
        elseif ScenarioInfo.M1CivilianCity and AiBotUtilities.IsTableEmpty(ScenarioInfo.M1CivilianCity) == false then
            if bDebugMessages == true then LOG(sFunctionRef..': Will flag every unit in civilian city to not be a reclaim target, Time='..GetGameTimeSeconds()) end
            for iUnit, oUnit in ScenarioInfo.M1CivilianCity do
                oUnit[AiBotUnitInfo.refbIsReclaimTarget] = false
                if AiBotUtilities.IsTableEmpty(oUnit[AiBotUnitInfo.refiTeamsWithThisAsReclaimTarget]) == false then
                    for iEntry, iTeam in oUnit[AiBotUnitInfo.refiTeamsWithThisAsReclaimTarget] do
                        local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iTeam)
                        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoUnitsToReclaim]) == false then
                            for iRecorded, oRecorded in tLZTeamData[AiBotMap.subreftoUnitsToReclaim] do
                                if oRecorded == oUnit then
                                    table.remove(tLZTeamData[AiBotMap.subreftoUnitsToReclaim], iRecorded)
                                    break
                                end
                            end
                        end
                    end
                    oUnit[AiBotUnitInfo.refiTeamsWithThisAsReclaimTarget] = nil
                    if bDebugMessages == true then LOG(sFunctionRef..': Removed unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' from table of units wanting reclaiming in this zone for all teams') end
                end
            end
            --Fort clarke assault - dont control seraphim bombers, gunships or asfs in the short period after cutscene ends and the main game starts if we have AiBot taking control of allies
        elseif ScenarioInfo.Seraphim and ScenarioInfo.CoopCDR and ScenarioInfo.UnitNames[ScenarioInfo.Seraphim]['NIS_Bomber_1'] and (ScenarioInfo.Options.CampAI == 2 or ScenarioInfo.Options.CampAI == 4) then
            if bDebugMessages == true then LOG(sFunctionRef..': Will disable orders for the experimental bombers') end
            local oSeraphimBrain
            local toBombersToKill = {}
            for iBomber = 1, 3 do
                local oUnit = ScenarioInfo.UnitNames[ScenarioInfo.Seraphim]['NIS_Bomber_'..iBomber]
                if oUnit then
                    table.insert(toBombersToKill, oUnit)
                    if not(oSeraphimBrain) and not(oUnit.Dead) then oSeraphimBrain = oUnit:GetAIBrain() end
                    if bDebugMessages == true then LOG(sFunctionRef..': Setting micro flag for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                    AiBotMicro.TrackTemporaryUnitMicro(oUnit, 600, nil, false)
                end
            end
            if oSeraphimBrain then
                local tGunshipsAndASFs = oSeraphimBrain:GetListOfUnits(categories.xsa0303 + categories.xsa0203, false, true)
                if AiBotUtilities.IsTableEmpty(tGunshipsAndASFs) == false then
                    for iUnit, oUnit in tGunshipsAndASFs do
                        AiBotMicro.TrackTemporaryUnitMicro(oUnit, 180, nil, false)
                    end
                end
            end
            --Redundancy - Campaign script appears to try and send bombers to a target where they get killed when close, but in the event AiBot logic introduces special microing order the below should ensure the bombers die
            if AiBotConditions.IsTableOfUnitsStillValid(toBombersToKill) then
                ForkThread(DelayedKillUnits, toBombersToKill, 300)
            end
        end
    else
        if bDebugMessages == true then LOG(sFunctionRef..': No active AiBot brains so aborting') end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function AddCampaignUnitToUnitsToRepair(oUnit, iTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AddCampaignUnitToUnitsToRepair'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
    local tLZOrWZData
    if bDebugMessages == true then LOG(sFunctionRef..': oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')..'; iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; Unit position='..repru(oUnit:GetPosition())) end
    if iLandOrWaterZone > 0 then
        local tLZOrWZTeamData
        if iPlateauOrZero == 0 then
            tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
            tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
        else
            tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
            tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
        end
        if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subreftoUnitsToRepair]) then
            tLZOrWZData[AiBotMap.subreftoUnitsToRepair] = {}
        end
        table.insert(tLZOrWZData[AiBotMap.subreftoUnitsToRepair], oUnit)
        AiBotAir.AddPriorityAirDefenceTarget(oUnit)
        if bDebugMessages == true then LOG(sFunctionRef..': Added unit to table of units to repair') end
        --Consider adding this zone as somewhere to drop if it's not adjacent to a core zone
        if iPlateauOrZero > 0 then
            local bAdjacentToCoreBase = false
            if tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] then
                bAdjacentToCoreBase = true
                if bDebugMessages == true then LOG(sFunctionRef..': Are in a core base; tLZOrWZTeamData[AiBotMap.subrefbCoreBaseOverride]='..tostring(tLZOrWZTeamData[AiBotMap.subrefbCoreBaseOverride])) end

            elseif AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                for _, iAdjLZ in tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones] do
                    if AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZbCoreBase] then
                        if bDebugMessages == true then LOG(sFunctionRef..': iAdjLZ '..iAdjLZ..' is a core base, midpoint of adjlz='..repru(AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefMidpoint])..'; Dist to midpoint of this LZ='..AiBotUtilities.GetDistanceBetweenPositions(AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefMidpoint], tLZOrWZData[AiBotMap.subrefMidpoint])..'; Travel distance='..(AiBotMap.GetTravelDistanceBetweenLandZones(iPlateauOrZero, iLandOrWaterZone, iAdjLZ) or 'nil')) end
                        bAdjacentToCoreBase = true
                        break
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to add location as a drop zone target, bAdjacentToCoreBase='..tostring(bAdjacentToCoreBase)..'; iTeam='..iTeam) end
            if not(bAdjacentToCoreBase) then
                --Add to locations for priority transport drop
                AiBotAir.UpdateTransportPlateauDropLocationShortlist(iTeam) --incase not already run
                AiBotAir.AddZoneToPotentialDropZonesSameIslandOrDifPond(iTeam, iPlateauOrZero, iLandOrWaterZone)
                if bDebugMessages == true then LOG(sFunctionRef..': Have tried toa dd to same island drop list, iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone..'; iTeam='..iTeam) end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateAllRecordedUnitsFollowingTeamChange(tbOptionalVariableToBeTrue)
    --E.g. for Dawn M2 where order switches from enemy to ally of player team - clears all land and water zone details of enemy and allied units, and then re-records all the units
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateAllRecordedUnitsFollowingTeamChange'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if not(tbOptionalVariableToBeTrue == nil) then
        while not(tbOptionalVariableToBeTrue) do
            if bDebugMessages == true then LOG(sFunctionRef..': tbOptionalVariableToBeTrue is not nil but not true so will wait 1 tyick') end
            WaitTicks(1)
        end
    end

    local tiTeamsToConsider = {}
    for iTeam = 1, AiBotTeam.iTotalTeamCount do
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] >= 1 then
            table.insert(tiTeamsToConsider, iTeam)
        end
    end
    local bChangedAlliesOrEnemiesForZone = false
    if bDebugMessages == true then LOG(sFunctionRef..': About to check if any units need updating from allies to enemies or vice versa, tiTeamsToConsider='..repru(tiTeamsToConsider)..'; Time='..GetGameTimeSeconds()) end

    --A player has changed from ally to enemy or vice versa; if AiBotAI is only applying to one of the two (but not neither, and not both), then will need to update flag
    --e.g. Celene in Dawn
    local oFirstHuman
    for iBrain, oBrain in ArmyBrains do
        if oBrain.Human then
            oFirstHuman = oBrain
            break
        end
    end

    --First consider if we need to create/change team composition
    for iBrain, oBrain in ArmyBrains do
        local bApplyAiBotAI = AiBotConditions.ApplyAiBotToOtherAI(oBrain)
        if bDebugMessages == true then LOG(sFunctionRef..': Considering iBrain '..iBrain..' oBrain='..oBrain.Nickname..'; bApplyAiBotAI='..tostring(bApplyAiBotAI or false)..'; oBrain.AiBotAI='..tostring(oBrain.AiBotAI or false)) end
        if bApplyAiBotAI and not(oBrain.AiBotAI) then
            if bDebugMessages == true then LOG(sFunctionRef..': Starting applying AiBotAI to brain '..oBrain.Nickname) end
            oBrain.AiBotAI = true --redundancy, below should do this as well
            oBrain['AiBotBrainSetupRun'] = nil
            DecideWhetherToApplyAiBotToCampaignAI(oBrain, nil, true)
            --Make sure we are added to player team if we are an ally
            if IsAlly(oFirstHuman:GetArmyIndex(), oBrain:GetArmyIndex()) then
                local iTeam = oFirstHuman.AiBotTeam
                oBrain.AiBotTeam = iTeam
                if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains]) then
                    AiBotUtilities.ErrorHandler('Need to add code to handle this scenario - need to run some but not all of the logic for a new team, or just move all players into a brand new team')
                else
                    table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains], oBrain)
                    table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains], oBrain)
                    AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] = (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or 0) + 1
                end
                --Set air subteam
                oBrain.AiBotAirSubteam = nil
                AiBotTeam.CreateNewAirSubteam(oBrain)
                oBrain.AiBotLandSubteam = nil
                ForkThread(AiBotTeam.CheckForBrainsWithoutLandSubteam, iTeam, nil, true)
                if bDebugMessages == true then LOG(sFunctionRef..': Finsihed reocrding brain '..oBrain.Nickname..' as a new teammate for team '..iTeam) end
            elseif IsEnemy(oFirstHuman:GetArmyIndex(), oBrain:GetArmyIndex()) then
                local iTeam = oFirstHuman.AiBotTeam
                if (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or 0) > 0 then
                    table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoEnemyBrains], oBrain)
                end
                if bDebugMessages == true then LOG(sFunctionRef..': About to reset and create new team for brain '..oBrain.Nickname) end
                oBrain.AiBotTeam = nil
                oBrain.AiBotLandSubteam = nil
                oBrain.AiBotAirSubteam = nil
                AiBotTeam.CreateNewTeam(oBrain)
                if oBrain.AiBotTeam then AiBotTeam.CheckForBrainsWithoutLandSubteam(oBrain.AiBotTeam, nil, true) end
                if bDebugMessages == true then LOG(sFunctionRef..': Finsihed creating a new team for brain '..oBrain.Nickname..'; New team='..(oBrain.AiBotTeam or 'nil')..'; Land subteam='..(oBrain.AiBotLandSubteam or 'nil')..'; Air subteam='..(oBrain.AiBotAirSubteam or 'nil')..'; Time='..GetGameTimeSeconds()) end
            end
            --Figure out what zone to treat as core base
            WaitTicks(1)
            local tFriendlyFactories = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryLandHQ + AiBotUnitInfo.refCategoryAirHQ, false, true)
            if bDebugMessages == true then LOG(sFunctionRef..': Is tFriendlyFactories empty='..tostring(AiBotUtilities.IsTableEmpty(tFriendlyFactories))) end
            if AiBotUtilities.IsTableEmpty(tFriendlyFactories) == false then
                local tiFactoriesByPlateauAndZone = {}
                local iCurPlateau, iCurZone
                for iFactory, oFactory in tFriendlyFactories do
                    iCurPlateau, iCurZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oFactory:GetPosition())
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering oFactory='..oFactory.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFactory)..' in P'..iCurPlateau..'Z'..iCurZone) end
                    if iCurPlateau and iCurZone and iCurPlateau > 0 then
                        if not(tiFactoriesByPlateauAndZone[iCurPlateau][iCurZone]) then
                            if not(tiFactoriesByPlateauAndZone[iCurPlateau]) then tiFactoriesByPlateauAndZone[iCurPlateau] = {} end
                            tiFactoriesByPlateauAndZone[iCurPlateau][iCurZone] = 0
                        end
                    end
                    tiFactoriesByPlateauAndZone[iCurPlateau][iCurZone] = tiFactoriesByPlateauAndZone[iCurPlateau][iCurZone] + AiBotUnitInfo.GetUnitTechLevel(oFactory)
                end
                local iHighestPlateau, iHighestZone
                local iHighestCount = 0
                if AiBotUtilities.IsTableEmpty(tiFactoriesByPlateauAndZone) == false then
                    for iPlateau, tZones in tiFactoriesByPlateauAndZone do
                        for iZone, iCount in tZones do
                            if iCount > iHighestCount then
                                iHighestCount = iCount
                                iHighestPlateau = iPlateau
                                iHighestZone = iZone
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iHighestCount='..iHighestCount..'; iHighestPlateau='..iHighestPlateau..'; iHighestZone='..iHighestZone..'; will now flag core base override to true, iTeam='..oBrain.AiBotTeam..'; Brain nickname='..oBrain.Nickname) end
                    if iHighestCount > 0 then
                        local tLZTeamData = AiBotMap.tAllPlateaus[iHighestPlateau][AiBotMap.subrefPlateauLandZones][iHighestZone][AiBotMap.subrefLZTeamData][oBrain.AiBotTeam]
                        tLZTeamData[AiBotMap.subrefbCoreBaseOverride] = true
                    end
                end
            end


        elseif not(bApplyAiBotAI) and oBrain.AiBotAI then
            oBrain.AiBotAI = false
            oBrain.AiBotTeam = nil
            AiBotTeam.CreateNewTeam(oBrain)
            if bDebugMessages == true then LOG(sFunctionRef..': No longer applying AiBotAI to brain '..oBrain.Nickname..'; assigned it to the team '..(oBrain.AiBotTeam or 'nil')) end
        end
    end

    --Give time for any brain changes to take effect
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    WaitTicks(2)
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    function UpdateStatusOfFriendlyAndEnemyUnits(tLZOrWZTeamData, iTeam)
        local iTeamBrainIndex = AiBotTeam.GetFirstActiveAiBotBrain(iTeam):GetArmyIndex()
        local toFriendlyUnits = {}
        local toEnemyUnits = {}
        local bChangedAlliesOrEnemies = false
        if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
            for iUnit, oUnit in tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits] do
                if AiBotUnitInfo.IsUnitValid(oUnit) then
                    if IsAlly(oUnit:GetAIBrain():GetArmyIndex(), iTeamBrainIndex) then
                        table.insert(toFriendlyUnits, oUnit)
                    elseif IsEnemy(oUnit:GetAIBrain():GetArmyIndex(), iTeamBrainIndex) then
                        table.insert(toEnemyUnits, oUnit)
                        bChangedAlliesOrEnemies = true
                    else
                        bChangedAlliesOrEnemies = true
                    end
                end
            end
        end
        if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
            for iUnit, oUnit in tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits] do
                if AiBotUnitInfo.IsUnitValid(oUnit) then
                    if IsEnemy(oUnit:GetAIBrain():GetArmyIndex(), iTeamBrainIndex) then
                        table.insert(toEnemyUnits, oUnit)
                    elseif IsAlly(oUnit:GetAIBrain():GetArmyIndex(), iTeamBrainIndex) then
                        table.insert(toFriendlyUnits, oUnit)
                        bChangedAlliesOrEnemies = true
                    else
                        bChangedAlliesOrEnemies = true
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Updating for team '..iTeam..'; bChangedAlliesOrEnemies='..tostring(bChangedAlliesOrEnemies or false)) end
        if bChangedAlliesOrEnemies then
            bChangedAlliesOrEnemiesForZone = true
            if bDebugMessages == true then LOG(sFunctionRef..': Have a zone with units who have an updated ally/enemy status, iTeam='..iTeam) end
            tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits] = nil
            tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits] = toEnemyUnits
            tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits] = nil
            tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits] = toFriendlyUnits
            if AiBotUnitInfo.IsUnitValid(tLZOrWZTeamData[AiBotMap.refoBestRadar]) and not(IsAlly(tLZOrWZTeamData[AiBotMap.refoBestRadar]:GetAIBrain():GetArmyIndex(), iTeamBrainIndex)) then
                if bDebugMessages == true then LOG(sFunctionRef..': Will update best radar for change in ally by treating radar as being destroyed, tLZOrWZTeamData[AiBotMap.refoBestRadar] owner='..tLZOrWZTeamData[AiBotMap.refoBestRadar]:GetAIBrain().Nickname..'; tLZOrWZTeamData[AiBotMap.refoBestRadar]='..tLZOrWZTeamData[AiBotMap.refoBestRadar].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tLZOrWZTeamData[AiBotMap.refoBestRadar])) end
                AiBotLand.UpdateRadarCoverageForDestroyedRadar(tLZOrWZTeamData[AiBotMap.refoBestRadar], iTeam) --didnt end up needing this but left it in just in case
            end
        end
    end
    if AiBotUtilities.IsTableEmpty(tiTeamsToConsider) == false then
        for iPlateau, tPlateauData in AiBotMap.tAllPlateaus do
            for iLandZone, tLZData in tPlateauData[AiBotMap.subrefPlateauLandZones] do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering if have any units to update status of for iPlateau='..iPlateau..'; iLandZone='..iLandZone) end
                for _, iTeam in tiTeamsToConsider do
                    UpdateStatusOfFriendlyAndEnemyUnits(tLZData[AiBotMap.subrefLZTeamData][iTeam], iTeam)
                end
            end
        end

        for iPond, tPondSubtable in AiBotMap.tPondDetails do
            if AiBotUtilities.IsTableEmpty(tPondSubtable[AiBotMap.subrefPondWaterZones]) == false then
                for iWaterZone, tWZData in tPondSubtable[AiBotMap.subrefPondWaterZones] do
                    for _, iTeam in tiTeamsToConsider do
                        UpdateStatusOfFriendlyAndEnemyUnits(tWZData[AiBotMap.subrefWZTeamData][iTeam], iTeam)
                    end
                end
            end
        end
        --Update neutral units
        for _, iTeam in tiTeamsToConsider do
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoCampaignNeutralUnitsNotRecorded]) == false then
                local oAiBotBrain
                local oFirstAnyAiBotBrain
                for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                    if oBrain.AiBotAI then
                        if not(oFirstAnyAiBotBrain) then oFirstAnyAiBotBrain = oBrain end
                        if not(oAiBotBrain) and not(oBrain.CampaignAI) then oAiBotBrain = oBrain end
                    end
                end
                if not(oAiBotBrain) then oAiBotBrain = oFirstAnyAiBotBrain end
                if oAiBotBrain then
                    local iAiBotIndex = oAiBotBrain:GetArmyIndex()

                    local tiUnitsToRemove = {}
                    for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoCampaignNeutralUnitsNotRecorded] do
                        if AiBotUnitInfo.IsUnitValid(oUnit) then
                            --Rerecord if this is now an enemy
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering if unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' is now an enemy to team '..iTeam..'; oAiBotBrain='..oAiBotBrain.Nickname..'; Unit brain owner='..oUnit:GetAIBrain().Nickname..'; Is enemy='..tostring(IsEnemy(oUnit:GetAIBrain():GetArmyIndex(), iAiBotIndex))) end
                            if IsEnemy(oUnit:GetAIBrain():GetArmyIndex(), iAiBotIndex) then
                                oUnit[AiBotUnitInfo.reftbConsideredForAssignmentByTeam][iTeam] = nil
                                AiBotTeam.AssignUnitToLandZoneOrPond(oAiBotBrain, oUnit)
                                table.insert(tiUnitsToRemove, iUnit)
                            end
                        else
                            table.insert(tiUnitsToRemove, iUnit)
                        end
                    end
                    if AiBotUtilities.IsTableEmpty(tiUnitsToRemove) == false then
                        local iToRemoveTotal = table.getn(tiUnitsToRemove)
                        for iCurRemoval = iToRemoveTotal, 1, -1 do
                            table.remove(tiUnitsToRemove, tiUnitsToRemove[iCurRemoval])
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function MonitorObjectiveUnitsAndRemoveIfDead(tUnits, iMissionRef, vMissionStatusVariable)
    --Call via forked thread, intended e.g. for M2 Dawn of FA campaign where upgrading/destroying factories before the objective starts breaks the mission
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'MonitorObjectiveUnitsAndRemoveIfDead'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)


    if not(bActiveObjectiveUnitValidMonitorByObjective[iMissionRef]) then
        bActiveObjectiveUnitValidMonitorByObjective[iMissionRef] = true
        while vMissionStatusVariable.Active do
            AiBotConditions.IsTableOfUnitsStillValid(tUnits)
            WaitTicks(1)
            if bDebugMessages == true then
                LOG(sFunctionRef..': Finished updating tUnits, is table empty='..tostring(AiBotUtilities.IsTableEmpty(tUnits))..'; Time='..GetGameTimeSeconds())
                if AiBotUtilities.IsTableEmpty(tUnits) == false then
                    LOG(sFunctionRef..': Size of tUnits='..table.getn(tUnits))
                end
            end
        end
        --Have moved onto next objective now
        if bDebugMessages == true then
            WaitSeconds(60)
            LOG(sFunctionRef..': after waiting a while size of tUnits='..table.getn(tUnits)..'; Will cycle through each unit')
            for iUnit, oUnit in tUnits do
                LOG(sFunctionRef..': oUnit='..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..'; Is dead='..tostring(oUnit.Dead or false)..'; reprs of unit='..reprs(oUnit))

            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DelayedM27AiBotBrainCheck(aiBrain)
    WaitSeconds(1)
    --LOG('Delayed brain check, brain nickname='..aiBrain.Nickname..'; .M27AI='..tostring(aiBrain.M27AI or false)..'; .AiBotAI='..tostring(aiBrain.AiBotAI or false))
    if aiBrain.M27AI and aiBrain.AiBotAI then aiBrain.AiBotAI = false end
end

function DecideWhetherToApplyAiBotToCampaignAI(aiBrain, planName, bDontWait)
    --Wait a second so hopefully isenemy is more accurate
    if not(bDontWait) then WaitSeconds(1) end --also need to update references to iTimeOfLatestBrainToCheckForAiBotLogic if changing this
    if AiBotConditions.ApplyAiBotToOtherAI(aiBrain) then
        local AiBotEvents = import('/lua/AiBot/AI/AiBotEvents.lua')
        aiBrain.AiBotAI = true
        AiBotUtilities.bAiBotAIInGame = true
        --LOG('AiBot in game 4')
        if ScenarioInfo.Options.CmApplyAIx == 1 then
            aiBrain.CheatEnabled = true
        end
        if ScenarioInfo.Options.CmAiBotCampPers == 1 then
            aiBrain.AiBotEasy = true
        end
        LOG('Setting AI to use AiBot, aiBrain.Nickname='..(aiBrain.Nickname or 'nil')..'; aiBrain[AiBotBrainSetupRun] before being cleared='..tostring(aiBrain['AiBotBrainSetupRun'] or false)..'; ScenarioInfo.Options.CmApplyAIx='..(ScenarioInfo.Options.CmApplyAIx or 'nil')..'; Brain flagged as cheat enabled='..tostring(aiBrain.CheatEnabled or false)..'; aiBrain.AiBotEasy='..tostring(aiBrain.AiBotEasy or false))
        ForkThread(AiBotEvents.OnCreateBrain, aiBrain, planName, false)
    end
end


function RemoveUnitsFromPlatoon(oPlatoon, tUnits, bReturnToBase, oPlatoonToAddTo)
    --Intended to remove a particular unit from a platoon e.g. to avoid campaign AI overriding AiBot AI
    --if bReturnToBase is true then units will be told to move to aiBrain's base
    --if tUnits isnt in oPlatoon then does nothing
    --oPlatoonToAddTo - optional, if empty, then will try to assign to army pool instead
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RemoveUnitsFromPlatoon'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if oPlatoon and oPlatoon.GetBrain and oPlatoon.GetPlan and not(oPlatoon.Dead) then
        local aiBrain = oPlatoon:GetBrain()

        if bDebugMessages == true then
            LOG(sFunctionRef..': About to list out every unit that is about to be removed')
            for iUnit, oUnit in tUnits do
                if oUnit.GetUnitId then LOG('iUnit='..iUnit..'; oUnitId='..oUnit.UnitId)
                else LOG('iUnit='..iUnit..'; Unit has no unitId') end
            end
        end
        if not(oPlatoonToAddTo == oPlatoon) then
            local oArmyPool = aiBrain:GetPlatoonUniquelyNamed('ArmyPool')
            local sName
            if oPlatoonToAddTo == nil then
                if bDebugMessages == true then LOG(sFunctionRef..': Will add units to army pool') end
                oPlatoonToAddTo = oArmyPool
                sName = 'ArmyPool'
            else
                if oPlatoonToAddTo == oArmyPool then sName = 'ArmyPool'
                else
                    if oPlatoonToAddTo.GetPlan then
                        sName = oPlatoonToAddTo:GetPlan()
                    end
                    if sName == nil then sName = 'nil' end

                    if bDebugMessages == true then LOG(sFunctionRef..': Adding unit to '..sName) end
                end
            end
            if oPlatoonToAddTo == nil then
                LOG(sFunctionRef..': WARNING: oPlatoonToAddTo is nil')
            else
                local sCurPlatoonName
                if oPlatoon == oArmyPool then
                    sCurPlatoonName = 'ArmyPool'
                else
                    sCurPlatoonName = oPlatoon:GetPlan()
                    if sCurPlatoonName == nil then sCurPlatoonName = 'None' end
                    if bDebugMessages == true then LOG(sFunctionRef..': sCurPlatoonName='..sCurPlatoonName) end
                end

                if not(sCurPlatoonName == sName) then
                    if bDebugMessages == true then
                        if oPlatoon == oArmyPool then
                            AiBotUtilities.ErrorHandler('ideally shouldnt have any units using armypool platoon now, see if can figure out where this came from')
                            LOG(sFunctionRef..': About to remove units from ArmyPool platoon and add to platoon '..sName)
                        else
                            LOG(sFunctionRef..': About to remove units from platoon '..oPlatoon:GetPlan())
                        end
                    end

                    if bReturnToBase == true then
                        if bDebugMessages == true then LOG(sFunctionRef..': Issuing move command to tUnits') end
                        if bDebugMessages == true then LOG(sFunctionRef..': Clearing commands; Gametime='..GetGameTimeSeconds()) end
                        local tBase = AiBotMap.PlayerStartPoints[aiBrain:GetArmyIndex()]
                        for iUnit, oUnit in tUnits do
                            AiBotOrders.IssueTrackedClearCommands(oUnit)
                            AiBotOrders.IssueTrackedMove(oUnit, tBase, 10, false, 'PlatRB', false)
                        end
                    end
                    aiBrain:AssignUnitsToPlatoon(oPlatoonToAddTo, tUnits, 'Support', 'GrowthFormation')
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DelayedCheckOfUnitsAtStartOfGame()
    --Sometimes e.g. in a campaign, the map has units pre-created meaning they dont trigger 'oncreate' logic - do a 1-off check at the start of the game for such units
    if not(bCheckForPrecreatedUnitsActive) then
        bCheckForPrecreatedUnitsActive = true
        while not(AiBotMap.bWaterZoneInitialCreation) or not(AiBotMap.bFirstAiBotTeamHasBeenInitialised) or GetGameTimeSeconds() <= 5 do
            WaitTicks(1)
            if GetGameTimeSeconds() >= 10 then break end
        end
        WaitTicks(1)
        local AiBotEvents = import('/lua/AiBot/AI/AiBotEvents.lua')
        for iBrain, oBrain in ArmyBrains do
            if oBrain.GetListOfUnits then
                local tAllUnits = oBrain:GetListOfUnits(categories.ALLUNITS - categories.UNSELECTABLE - categories.UNTARGETABLE, false, true)
                if AiBotUtilities.IsTableEmpty(tAllUnits) == false then
                    for iUnit, oUnit in tAllUnits do
                        if not(oUnit['AiBotOnCrRn']) and oUnit:GetFractionComplete() == 1 then
                            AiBotEvents.OnCreate(oUnit)
                        end
                    end
                end
            end
        end
    end

end

function ConsiderUnpausingAllCreatedNukes(iTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderUnpausingAllCreatedNukes'

    WaitTicks(1) --to ensure we register the units
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local iExistingSML = 0
    for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
        iExistingSML = iExistingSML + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategorySML - categories.EXPERIMENTAL)
        if bDebugMessages == true then LOG(sFunctionRef..': Cumulative SML units after considering brain '..oBrain.Nickname..'='..iExistingSML) end
    end
    if iExistingSML >= 4 then
        local tSMLToUnpause = {}
        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
            local tSML = oBrain:GetListOfUnits(AiBotUnitInfo.refCategorySML - categories.EXPERIMENTAL, false, true)
            if AiBotUtilities.IsTableEmpty(tSML) == false then
                for iSML, oSML in tSML do
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering oSML='..oSML.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oSML)..'; Have we registered the construction completion of this='..tostring(oSML.AiBotOnConstructedCalled or false)..'; Fraction complete='..oSML:GetFractionComplete()..'; Is paused nil='..tostring(oSML[AiBotUnitInfo.refbPaused] == nil)) end
                    if not(oSML.AiBotOnConstructedCalled) and oSML:GetFractionComplete() == 1 and oSML[AiBotUnitInfo.refbPaused] == nil then
                        table.insert(tSMLToUnpause, oSML)
                        if bDebugMessages == true then LOG(sFunctionRef..': Adding SML to table of units to unpause; is SML actually paused='..tostring(oSML:IsPaused())) end
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Is table of SML to unpause empty='..tostring(AiBotUtilities.IsTableEmpty(tSMLToUnpause))) end
        if AiBotUtilities.IsTableEmpty(tSMLToUnpause) == false then
            ForkThread(DelayedUnpauseOfUnits, tSMLToUnpause, 1)
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Have a nuke created with 100% completion but no onconstructed logic run, so will consider unpausing every nuke we have, iTeam='..iTeam..'; have got iExistingSML='..iExistingSML..'; have unpaused every SML we own if we have lots now') end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DelayedUnpauseOfUnits(tUnits, iDelayInSeconds)
    WaitSeconds(iDelayInSeconds)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'DelayedUnpauseOfUnits'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotConditions.IsTableOfUnitsStillValid(tUnits) then
        local tUnitsForFurtherCheck = {}
        for iUnit, oUnit in tUnits do
            if bDebugMessages == true then LOG(sFunctionRef..': About to unpause unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Is paused='..tostring(oUnit:IsPaused())..'; Time='..GetGameTimeSeconds()) end
            AiBotUnitInfo.PauseOrUnpauseEnergyUsage(oUnit, false)
            if oUnit.EnableShield and oUnit.MyShield then oUnit:EnableShield() end
            if EntityCategoryContains(AiBotUnitInfo.refCategoryMobileLandShield, oUnit.UnitId) then
                table.insert(tUnitsForFurtherCheck, oUnit)
            end
        end
        if AiBotUtilities.IsTableEmpty(tUnitsForFurtherCheck) == false then
            ForkThread(SecondDelayedUnpauseCheckForMobileShields, tUnitsForFurtherCheck, 20)
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code at time='..GetGameTimeSeconds()) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function SecondDelayedUnpauseCheckForMobileShields(tUnits, iDelayInSeconds)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'SecondDelayedUnpauseCheckForMobileShields'

    WaitSeconds(iDelayInSeconds)
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if AiBotConditions.IsTableOfUnitsStillValid(tUnits) then
        if bDebugMessages == true then LOG(sFunctionRef..': Cycling through mobile shields, size of tUnits='..table.getn(tUnits)) end
        local iCurShield, iMaxShield
        for iUnit, oUnit in tUnits do
            iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oUnit, true)
            if bDebugMessages == true then LOG(sFunctionRef..': Considering mobile shield oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iMaxShield='..iMaxShield..'; iCurShield='..iCurShield..'; if cur shield is 0 then will try and unpause, aiBrain owner='..oUnit:GetAIBrain().Nickname) end
            if iMaxShield > 0 and iCurShield == 0 then
                oUnit:EnableShield()
                AiBotUnitInfo.PauseOrUnpauseEnergyUsage(oUnit, false)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DecideOnGeneralMapStrategy(aiBrain)
    --Decide if we want to consider ignoring T2 mex upgrading and going all in on T1 spam, along with certain other factors such as combat land scouts
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'DecideOnGeneralMapStrategy'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --5-10km 1v1 but not winter duel, and can path to enemy by land
    if bDebugMessages == true then LOG(sFunctionRef..': Considering brain '..aiBrain.Nickname..'; Map size='..AiBotMap.iMapSize..'; Players at start='.. AiBotTeam.iPlayersAtGameStart..'; aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand]='..tostring(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand])) end
    if AiBotMap.iMapSize >= 225 and AiBotMap.iMapSize <= 512 and AiBotTeam.iPlayersAtGameStart <= 4 and aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand] then
        --Dont stay at t1 if we have a high AIx modifier or no mexes on map, or a campaign map
        if bDebugMessages == true then LOG(sFunctionRef..': Is low mex map='..tostring(AiBotMap.bIsLowMexMap)..'; Resource mult='..(aiBrain[AiBotEconomy.refiBrainResourceMultiplier] or 1)..'; Is campaign map='..tostring(AiBotMap.bIsCampaignMap)) end
        if not(AiBotMap.bIsLowMexMap) and (aiBrain[AiBotEconomy.refiBrainResourceMultiplier] or 1) <= 1.7 and not(AiBotMap.bIsCampaignMap) then
            --Are there lots of mexes outside the core bases to fight over, and most are in the core base plateau?
            local iMexesOnMap = table.getn(AiBotMap.tMassPoints)
            if bDebugMessages == true then LOG(sFunctionRef..': iMexesOnMap='..iMexesOnMap) end
            if iMexesOnMap < 150 then
                local iMexesInStartZones = 0
                local iStartPlateau, iStartZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(AiBotMap.GetPlayerStartPosition(aiBrain))
                if iStartPlateau and iStartZone and AiBotMap.tAllPlateaus[iStartPlateau][AiBotMap.subrefPlateauTotalMexCount] >= 0.8 * iMexesOnMap then
                    local tiStartZones = {}
                    for iBrain, oBrain in tAllAIBrainsByArmyIndex do
                        if bDebugMessages == true then LOG(sFunctionRef..': Deciding whether to include brain start posiiton, oBrain='..oBrain.Nickname..'; Is civilian='..tostring(AiBotConditions.IsCivilianBrain(oBrain))) end
                        if not(AiBotConditions.IsCivilianBrain(oBrain)) then
                            local iPlateau, iZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(AiBotMap.GetPlayerStartPosition(oBrain))
                            if iPlateau == iStartPlateau then
                                tiStartZones[iZone] = true
                                if bDebugMessages == true then LOG(sFunctionRef..': Will include the start position, iPlateau='..iPlateau..'; iZone='..iZone) end
                            end
                        end
                    end
                    if AiBotUtilities.IsTableEmpty(tiStartZones) == false then
                        for iZone, bInclude in tiStartZones do
                            if bDebugMessages == true then LOG(sFunctionRef..': Will include mexes in zone '..iZone..'; Mex count for this zone='..(AiBotMap.tAllPlateaus[iStartPlateau][AiBotMap.subrefPlateauLandZones][iZone][AiBotMap.subrefLZOrWZMexCount] or 0)) end
                            iMexesInStartZones = iMexesInStartZones + (AiBotMap.tAllPlateaus[iStartPlateau][AiBotMap.subrefPlateauLandZones][iZone][AiBotMap.subrefLZOrWZMexCount] or 0)
                        end
                    end
                end
                local iMexPercentThreshold = 0.45
                if iMexesOnMap > 80 or AiBotTeam.iPlayersAtGameStart >= 4 then
                    if iMexesOnMap > 130 then iMexPercentThreshold = 0.3
                    else iMexPercentThreshold = 0.375
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': iMexesInStartZones='..iMexesInStartZones..'; iMexesOnMap='..iMexesOnMap..'; iMexPercentThreshold='..iMexPercentThreshold..'; AiBotTeam.iPlayersAtGameStart='..AiBotTeam.iPlayersAtGameStart) end
                if iMexesInStartZones < iMexPercentThreshold * iMexesOnMap then
                    AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refbFocusOnT1Spam] = true
                    ForkThread(AiBotTeam.MonitorLeavingT1SpamMode, aiBrain.AiBotTeam)
                    if bDebugMessages == true then LOG(sFunctionRef..': Want to avoid getting T2 mex upgrade') end
                end
            end
        end

    end

    --Combat land scouts - do if can path to enemy base
    local tStartPosition = AiBotMap.GetPlayerStartPosition(aiBrain)
    local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(tStartPosition, true, aiBrain.AiBotTeam)
    if tLZData[AiBotMap.subrefLZIslandRef] == AiBotUtilities.NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestEnemyBase]) then
        --We can path to enemy with land
        --if brain is UEF then reduce the threshold, and eliminate entirely if enemy has aeon (as aurora have same range as snoops)
        if aiBrain.AiBotEasy then
            aiBrain[refiCombatLandScoutThreshold] = 0 --wont be kiting with the land scouts
        elseif aiBrain:GetFactionIndex() == AiBotUnitInfo.refFactionAeon then
            aiBrain[refiCombatLandScoutThreshold] = 15 --spirits only have 1 dps so this only gives a slight long term benefit in t1 land combat
        elseif not(aiBrain[refiCombatLandScoutThreshold]) then
            if aiBrain:GetFactionIndex() == AiBotUnitInfo.refFactionUEF then
                for iBrain, oBrain in AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subreftoEnemyBrains] do
                    if oBrain:GetFactionIndex() == AiBotUnitInfo.refFactionAeon then
                        aiBrain[refiCombatLandScoutThreshold] = 0
                        break
                    end
                end
                if not(aiBrain[refiCombatLandScoutThreshold]) then
                    --We havent considered this before, so can do a random % chance
                    local iRandom = math.random(1, 10)
                    if iRandom >= 8 then
                        aiBrain[refiCombatLandScoutThreshold] = 10
                    elseif iRandom >= 5 then
                        aiBrain[refiCombatLandScoutThreshold] = 5
                    else
                        aiBrain[refiCombatLandScoutThreshold] = 0
                    end
                end
            else
                --Non aeon non-UEF - dont try and build scouts for their combat value
                aiBrain[refiCombatLandScoutThreshold] = 0
            end
        end
    end
    if not(aiBrain[refiCombatLandScoutThreshold]) then aiBrain[refiCombatLandScoutThreshold] = 0 end --redundancy
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)

end

function ConsiderSlowdownForHighUnitCount()
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderSlowdownForHighUnitCount'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if refiRoughTotalUnitsInGame >= 1500 then --in case the rough number isnt accurate
        local iAiBotUnits = 0
        local oFirstAiBotBrain
        for iBrain, oBrain in ArmyBrains do
            if not(oBrain.AiBotIsDefeated) then
                iAiBotUnits = iAiBotUnits + GetArmyUnitCostTotal(oBrain:GetArmyIndex())
                if oBrain.AiBotAI then oFirstAiBotBrain = oBrain end
            end
        end
        if iAiBotUnits > 1750 or AiBotLand.iTicksPerLandCycle > 11 or AiBotAir.iExtraTicksToWaitBetweenAirCycles > 0 then
            local iOrigTicksPerLandCycle = AiBotLand.iTicksPerLandCycle
            AiBotLand.iTicksPerLandCycle = math.min(11, math.max(11, 11 + (iAiBotUnits-1500) / 200, tonumber((ScenarioInfo.Options.AiBotTimeBetweenOrders or 1))*10+1))
            AiBotAir.iExtraTicksToWaitBetweenAirCycles = math.max(0,AiBotLand.iTicksPerLandCycle - 11)
            AiBotNavy.iTicksPerNavyCycle = math.min(40, AiBotLand.iTicksPerLandCycle) --want to cap at 40 as bombardment logic considers if we have been bombarding in the last 4s
            if AiBotLand.iTicksPerLandCycle > iOrigTicksPerLandCycle then
                if oFirstAiBotBrain.BrainType == 'AI' then
                    AiBotChat.SendSlowdownModeMessage(oFirstAiBotBrain)
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Slowdown mode active, AiBotLand.iTicksPerLandCycle='..AiBotLand.iTicksPerLandCycle..'; iOrigTicksPerLandCycle='..iOrigTicksPerLandCycle..'; AiBotAir.iExtraTicksToWaitBetweenAirCycles='..AiBotAir.iExtraTicksToWaitBetweenAirCycles) end
        else
            --Use default values
            AiBotLand.iTicksPerLandCycle = tonumber((ScenarioInfo.Options.AiBotTimeBetweenOrders or 1))*10+1
            AiBotAir.iExtraTicksToWaitBetweenAirCycles = 0
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GlobalOverseer()
    --Called once at initial setup if we have an AiBot in the game; can be used for tracking things on a global basis (instead of per brain or team)
    local iSlowCycleThreshold = 30
    local iCurSlowCycle = 0

    --Set time between refreshing
    AiBotLand.iTicksPerLandCycle = tonumber((ScenarioInfo.Options.AiBotTimeBetweenOrders or 1))*10+1
    AiBotAir.iExtraTicksToWaitBetweenAirCycles = math.max(0,tonumber((ScenarioInfo.Options.AiBotTimeBetweenOrders or 1))*10+1 - 11)
    AiBotNavy.iTicksPerNavyCycle = math.min(40, AiBotLand.iTicksPerLandCycle) --want to cap at 40 as bombardment logic considers if we have been bombarding in the last 4s

    --ForkThread(DebugCheckProfiling, true) --will  output cur tick each log
    while AiBotUtilities.bAiBotAIInGame do
        iCurSlowCycle = iCurSlowCycle + 1
        if iCurSlowCycle >= iSlowCycleThreshold then
            iCurSlowCycle = 0
            ForkThread(ConsiderSlowdownForHighUnitCount)
        end
        WaitSeconds(1) --in case want to add per second logic in the future
    end
end



function DebugCheckProfiling(bJustShowTickCount)
    AiBotUtilities.ErrorHandler('Debug check profiling is enabled')
    local sFunctionRef = 'DebugCheckProfiling'
    local iTimeInSecondsToStartDetailedDebug = 103400.8 --set to high number if first want to figure out the tick where this happens
    local bSetHook = false --Used for debugging
    if not(bDebugTickCheckerActive) then
        bDebugTickCheckerActive = true
        --Every tick list out the tick - use this function to help identify infinite loops
        while true do
            WaitTicks(1)
            LOG(sFunctionRef..': Cur time='..GetGameTimeSeconds())
            if not(bSetHook) and not(bJustShowTickCount) and GetGameTimeSeconds() >= iTimeInSecondsToStartDetailedDebug then
                bSetHook = true
                AiBotProfiler.bFunctionCallDebugOverride = true
                --AiBotProfiler.bGlobalDebugOverride = true --Only enable this if want more detail as it will make things really slow
                debug.sethook(AiBotProfiler.OutputRecentFunctionCalls, "c", 200)
                LOG(sFunctionRef..': Have started the main hook of function calls')
            end
        end
    end
end

function ConsiderSteamMessageIfNoAiBot()
    if AiBotUtilities.bSteamActive then
        WaitSeconds(1)
        local bHaveAiBotInGame = false
        local oFirstBrain
        for iBrain, oBrain in ArmyBrains do
            if not(oFirstBrain) then oFirstBrain = oBrain end
            if oBrain.AiBotAI then bHaveAiBotInGame = true break end
        end
        if not(bHaveAiBotInGame) and oFirstBrain then
            AiBotChat.SendMessage(oFirstBrain, 'SteamAIIssue', 'AiBot is active, but no compatible AI has been selected', 1, 1000, false, false)
        end
    end
end

function SetAiBotActiveFlag()
    --Global flag referenced by other orders
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'SetAiBotActiveFlag'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': ScenarioInfo.Options.AiBotCombinedArmy='..(ScenarioInfo.Options.AiBotCombinedArmy or 'nil')..'; Time='..GetGameTimeSeconds()) end
    if not(AiBotOrders.bDontConsiderCombinedArmy == false) and not(tonumber(ScenarioInfo.Options.AiBotCombinedArmy or 2) == 2) and not(ScenarioInfo.Options.AiBotCombinedArmy == 5) then
        AiBotOrders.bDontConsiderCombinedArmy = false
        AiBotUnitInfo.bDontConsiderCombinedArmy = false
    end

    -- Combined-army mode is global, but admin activation is per brain.  Keep
    -- scanning after the global flag has already been enabled so a second admin
    -- can activate later in the same match.
    for iBrain, oBrain in ArmyBrains do
        if bDebugMessages == true then LOG(sFunctionRef..': Considering oBrain='..oBrain.Nickname) end
        local adminPlayers = ScenarioInfo.Options and ScenarioInfo.Options.AiBotAdminPlayers
        if oBrain.BrainType == 'Human'
            and oBrain.AiBotAdminRequested
            and type(adminPlayers) == 'table'
            and adminPlayers[oBrain.Nickname] == true
            and not(oBrain.AiBotAI) then
            LOG('Running AiBotBrainCreated for brain '..oBrain.Nickname)
            AiBotBrainCreated(oBrain)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetFirstActiveBrain()
    for iBrain, oBrain in tAllActiveAiBotBrains do
        if oBrain.IsDefeated and not(oBrain:IsDefeated()) then
            return oBrain
        end
    end
    for iBrain, oBrain in ArmyBrains do
        if oBrain.IsDefeated and not(oBrain:IsDefeated()) then
            return oBrain
        end
    end
    AiBotUtilities.ErrorHandler('Dont appear to have any active brains')
end

function ReviewTreatingOldBaseAsCoreBase(aiBrain)
    --Claled when aibrain is defeated - if have teammates then will consider treating its old base as a core base once enemy threats dealt with and we have sufficient tech/mexes in the zone, but will also consider turning the flag off
    local sFunctionRef = 'ReviewTreatingOldBaseAsCoreBase'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iTeam = aiBrain.AiBotTeam
    local tStartPosition = AiBotMap.GetPlayerStartPosition(aiBrain)
    local iStartPlateau, iStartZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tStartPosition)

    if iStartPlateau and iStartZone and iStartPlateau > 0 then
        local tLZData = AiBotMap.tAllPlateaus[iStartPlateau][AiBotMap.subrefPlateauLandZones][iStartZone]
        local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
        --Only consider this for 4+ mex zones and mod dist is <=0.3
        if bDebugMessages == true then LOG(sFunctionRef..': Considering whether we want to monitor resetting core base flag, iStartPlateau='..iStartPlateau..'; iStartZone='..iStartZone..'; LZ mex c ount='..tLZData[AiBotMap.subrefLZOrWZMexCount]..'; Mod dist%='..tLZTeamData[AiBotMap.refiModDistancePercent]..'; Brain nickname='..(aiBrain.Nickname or 'nil')) end
        if tLZData[AiBotMap.subrefLZOrWZMexCount] >= 4 and tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.3 then
            while AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false do
                if bDebugMessages == true then LOG(sFunctionRef..': Start of loop for assessing if we want to change this zone core zone flag, tLZTeamData[AiBotMap.subrefbCoreBaseOverride]='..tostring(tLZTeamData[AiBotMap.subrefbCoreBaseOverride] or false)..'; tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]='..tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]..'; Enemy air to ground='..tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]..'; Enemies in this or adj zone='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or false)..'; T2 mexes in zone='..tLZTeamData[AiBotMap.subrefMexCountByTech][2]..'; T3 mexes in zone='..tLZTeamData[AiBotMap.subrefMexCountByTech][3]..'; Total mexes in zone='..tLZData[AiBotMap.subrefLZOrWZMexCount]..'; Time='..GetGameTimeSeconds()) end
                --If this is already a core zone, then only abort if dangerous enemies in the zone, and we lack a factory HQ
                if tLZTeamData[AiBotMap.subrefbCoreBaseOverride] then
                    --We are a core zone, only change if significant change in position
                    if tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] >= 100 or tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] > 0 then
                        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) then
                            tLZTeamData[AiBotMap.subrefbCoreBaseOverride] = false
                            if bDebugMessages == true then LOG(sFunctionRef..': No friendly units so not a core base') end
                        else
                            local tFriendlyT2PlusHQs = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAllHQFactories - categories.TECH1, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                            if AiBotUtilities.IsTableEmpty(tFriendlyT2PlusHQs) then
                                if bDebugMessages == true then LOG(sFunctionRef..': No friendly HQ so not a core base anymore') end
                                tLZTeamData[AiBotMap.subrefbCoreBaseOverride] = false
                            end
                        end
                    end
                else
                    --We arent a core zone, consider if we want to become one - consider if all mexes are T2+, at least one is T3+, and there are no enemies in an adjacent zone
                    if not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) and tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= tLZData[AiBotMap.subrefLZOrWZMexCount] and (tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= 6) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Will treat this as a core zone again') end
                        tLZTeamData[AiBotMap.subrefbCoreBaseOverride] = true
                    end
                end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitSeconds(10)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DelayedArmyChangeForPings()
    --Orig commit just did this for LOUD: https://github.com/maudlin27/AiBotAI/commit/db56187766479a769779b6c4567e66646cc2be66
    --However, FAF has similar issue that is fixed with just this; decided to leave in LOUD as duplicate for redundancy/incase LOUD doesnt call same event on starting
    WaitSeconds(0.5) --just in case some LOUD or FAF stuff hasnt loaded yet
    local SimPing = import('/lua/SimPing.lua')
    SimPing.OnArmyChange()
end

function UEFMission2ReinforceCivilianTracker()
    local sFunctionRef = 'UEFMission2ReinforceCivilianTracker'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --Is player 1 AiBotAI?
    local oAiBotBrain, oFirstPlayer = GetAiBotBrainForCampaignObjective()

    if bDebugMessages == true then LOG(sFunctionRef..': oAiBotBrain='..(oAiBotBrain.Nickname or 'nil')) end

    if oAiBotBrain and oFirstPlayer then
        local rTargetRect = import("/lua/sim/scenarioutilities.lua").AreaToRect('Civilian_Area')
        local tTargetMidpoint = {(rTargetRect['x0'] + rTargetRect['x1'])*0.5 , 0, (rTargetRect['y0'] + rTargetRect['y1'])*0.5}
        tTargetMidpoint[2] = GetTerrainHeight(tTargetMidpoint[1], tTargetMidpoint[3])
        local iTargetPlateau, iTargetZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tTargetMidpoint)
        if iTargetPlateau and iTargetZone and iTargetPlateau > 0 then
            local iTargetIsland = NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tTargetMidpoint)
            if iTargetIsland then
                local toTankReinforcements = {}
                local toMAAReinforcements = {}
                local toGunshipReinforcements = {}
                local iTanksWanted = 20
                local iMAAWanted = 14
                local iGunshipsWanted = 12
                local iTanksAssigned, iMAAAssigned, iGunshipsAssigned
                local iTankCategory = categories.MOBILE * categories.LAND * categories.DIRECTFIRE - categories.COMMAND
                local iMAACategory = categories.MOBILE * categories.LAND * categories.ANTIAIR
                local iGunshipCategory = categories.uea0203
                local aiBrain = oAiBotBrain
                local iTeam = aiBrain.AiBotTeam
                local iTimeToResetMicro
                function MoveUnitsToObjective(toUnits)
                    if AiBotUtilities.IsTableEmpty(toUnits) == false then
                        for iUnit, oUnit in toUnits do
                            if bDebugMessages == true then LOG(sFunctionRef..': About to give move order to unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; AiBotOrders.bDontConsiderCombinedArmy='..tostring(AiBotOrders.bDontConsiderCombinedArmy or false)..'; oUnit.AiBotActive='..tostring(oUnit.AiBotActive or false)..'; Unit state='..AiBotUnitInfo.GetUnitState(oUnit)..'; Unit speed='..AiBotUnitInfo.GetUnitSpeed(oUnit)..'; Dist to target='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tTargetMidpoint)..'; refbSpecialMicroActive='..tostring(oUnit[AiBotUnitInfo.refbSpecialMicroActive])..'; Time until refiGameTimeToResetMicroActive is passed='..GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiGameTimeToResetMicroActive] or 0)) end
                            if AiBotOrders.bDontConsiderCombinedArmy or oUnit.AiBotActive then
                                AiBotOrders.IssueTrackedMove(oUnit, tTargetMidpoint, 5, false, 'CampObjM', true)
                                --Reapply micro flag in case it has been turned off elsewhere
                                oUnit[AiBotUnitInfo.refbSpecialMicroActive] = true
                                oUnit[AiBotUnitInfo.refiGameTimeToResetMicroActive] = iTimeToResetMicro
                            end
                        end
                    end
                end

                function SearchForUnitsToAssign(iCategoryToSearch, iUnitsWanted, tTableToAddTo, bIsAirUnit, bDontSetFactoryOverrides)
                    local iUnitsFound = 0
                    local toUnitsOfCategory = aiBrain:GetListOfUnits(iCategoryToSearch, false, true)
                    local bAlreadyRecorded
                    if AiBotUtilities.IsTableEmpty(toUnitsOfCategory) == false then
                        if bDebugMessages == true then LOG(sFunctionRef..': iUnitsWanted='..iUnitsWanted..'; bIsAirUnit='..tostring(bIsAirUnit)..'; size of toUnitsOfCategory='..table.getn(toUnitsOfCategory)..'; Time='..GetGameTimeSeconds()) end
                        for iUnit, oUnit in toUnitsOfCategory do
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Fraction complete='..oUnit:GetFractionComplete()..'; refbSpecialMicroActive='..tostring(oUnit[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; Assigned plateau='..(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] or 'nil')..'; Land label='..(NavUtils.GetLabel(AiBotMap.refPathingTypeLand, oUnit:GetPosition()) or 'nil')..'; iTargetIsland='..(iTargetIsland or 'nil')) end
                            if oUnit:GetFractionComplete() == 1 and not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]) and (bIsAirUnit or (oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iTargetPlateau and NavUtils.GetLabel(AiBotMap.refPathingTypeLand, oUnit:GetPosition()) == iTargetIsland)) then
                                --Check we havent already recorded unit
                                bAlreadyRecorded = false
                                if AiBotUtilities.IsTableEmpty(tTableToAddTo) == false then
                                    for iRecordedUnit, oRecordedUnit in tTableToAddTo do
                                        if oRecordedUnit == oUnit then
                                            bAlreadyRecorded = true
                                            break
                                        end
                                    end
                                end
                                if not(bAlreadyRecorded) then
                                    oUnit[AiBotUnitInfo.refbSpecialMicroActive] = true
                                    oUnit[AiBotUnitInfo.refiGameTimeToResetMicroActive] = iTimeToResetMicro
                                    table.insert(tTableToAddTo, oUnit)
                                    iUnitsFound = iUnitsFound + 1
                                    if bDebugMessages == true then LOG(sFunctionRef..': Adding unit to table of units to give orders to') end
                                    if iUnitsFound >= iUnitsWanted then break end
                                end
                            end
                        end
                    end
                    if iUnitsWanted > iUnitsFound and not(bDontSetFactoryOverrides) then
                        local iFactoryCategory
                        if bIsAirUnit then iFactoryCategory = AiBotUnitInfo.refCategoryAirFactory * categories.UEF - categories.TECH1
                        else iFactoryCategory = AiBotUnitInfo.refCategoryLandFactory * categories.UEF
                        end
                        local toFactories = aiBrain:GetListOfUnits(iFactoryCategory, false, true)
                        if AiBotUtilities.IsTableEmpty(toFactories) == false then
                            --Make sure factory will only build these units
                            for iFactory, oFactory in toFactories do
                                --Is factory on same island?
                                if NavUtils.GetLabel(AiBotMap.refPathingTypeLand, oFactory:GetPosition()) == iTargetIsland then
                                    --Get most expensive unit matching the category wanted
                                    oFactory[AiBotFactory.refsFactoryNextBlueprintOverride] = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, iCategoryToSearch, oFactory, false, false, false, nil, false, nil, true)
                                    if AiBotUnitInfo.GetUnitLifetimeCount(oFactory) == 1 then oFactory[AiBotFactory.refbPrimaryFactoryForIslandOrPond] = true end
                                end
                            end
                        end
                    end
                    return iUnitsFound
                end

                local bAlsoSendTruckOrder = false
                if oFirstPlayer.AiBotAI and oFirstPlayer == oAiBotBrain then bAlsoSendTruckOrder = true end --Will also set to true later on if we gift all the reinforcements from an AiBot brain


                while ScenarioInfo.CivilianFacilityReinforcedObjectiveComplete == false do
                    iTimeToResetMicro = GetGameTimeSeconds() + 15
                    --Do we have a shortfall of units?
                    if AiBotConditions.IsTableOfUnitsStillValid(toTankReinforcements) then
                        iTanksAssigned = 0
                        for iUnit, oUnit in toTankReinforcements do
                            if AiBotUnitInfo.GetUnitSpeed(oUnit) == 0 and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tTargetMidpoint) >= 30 then
                                --Unit may be stuck so want more units assigned
                            else
                                iTanksAssigned = iTanksAssigned + 1
                            end
                        end
                    else iTanksAssigned = 0
                    end
                    if AiBotConditions.IsTableOfUnitsStillValid(toMAAReinforcements) then
                        iMAAAssigned = 0
                        for iUnit, oUnit in toMAAReinforcements do
                            if AiBotUnitInfo.GetUnitSpeed(oUnit) == 0 and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tTargetMidpoint) >= 30 then
                                --Unit may be stuck so want more units assigned
                            else
                                iMAAAssigned = iMAAAssigned + 1
                            end
                        end
                    else iMAAAssigned = 0
                    end
                    if AiBotConditions.IsTableOfUnitsStillValid(toGunshipReinforcements) then
                        iGunshipsAssigned = table.getn(toGunshipReinforcements)
                    else iGunshipsAssigned = 0
                    end
                    if iTanksAssigned < iTanksWanted then
                        iTanksAssigned = iTanksAssigned + SearchForUnitsToAssign(iTankCategory, iTanksWanted - iTanksAssigned, toTankReinforcements, false, false)
                    end
                    if iMAAAssigned < iMAAWanted then
                        iMAAAssigned = iMAAAssigned + SearchForUnitsToAssign(iMAACategory, iMAAWanted - iMAAAssigned, toMAAReinforcements, false, iTanksAssigned < iTanksWanted)
                    end
                    if iGunshipsAssigned < iGunshipsWanted then
                        iGunshipsAssigned = iGunshipsAssigned + SearchForUnitsToAssign(iGunshipCategory, iGunshipsWanted - iGunshipsAssigned, toGunshipReinforcements, true, false)
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iTanksAssigned='..iTanksAssigned..'; iTanksWanted='..iTanksWanted..'; iMAAAssigned='..iMAAAssigned..'; iMAAWanted='..iMAAWanted) end
                    MoveUnitsToObjective(toTankReinforcements)
                    MoveUnitsToObjective(toMAAReinforcements)
                    MoveUnitsToObjective(toGunshipReinforcements)

                    if not(oFirstPlayer == oAiBotBrain) and iTanksAssigned >= iTanksWanted and iMAAAssigned >= iMAAWanted and iGunshipsAssigned >= iGunshipsWanted then
                        --Gift units to player 1 if they are all in the target area
                        local iTanksInTargetArea = 0
                        for iUnit, oUnit in toTankReinforcements do
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering position of oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; position='..repru(oUnit:GetPosition())..'; rTargetRect='..repru(rTargetRect)) end
                            if AiBotConditions.IsPositionInRectangle(oUnit:GetPosition(), rTargetRect) then iTanksInTargetArea = iTanksInTargetArea + 1 end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': iTanksInTargetArea='..iTanksInTargetArea) end
                        if iTanksInTargetArea >= iTanksWanted then
                            local iMAAInTargetArea = 0
                            for iUnit, oUnit in toMAAReinforcements do
                                if AiBotConditions.IsPositionInRectangle(oUnit:GetPosition(), rTargetRect) then iMAAInTargetArea = iMAAInTargetArea + 1 end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': iMAAInTargetArea='..iMAAInTargetArea) end
                            if iMAAInTargetArea >= iMAAWanted then
                                local iGunshipsInTargetArea = 0
                                for iUnit, oUnit in toGunshipReinforcements do
                                    if AiBotConditions.IsPositionInRectangle(oUnit:GetPosition(), rTargetRect) then iGunshipsInTargetArea = iGunshipsInTargetArea + 1 end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': iGunshipsInTargetArea='..iGunshipsInTargetArea) end
                                if iGunshipsInTargetArea >= iGunshipsWanted then
                                    --Gift units to the player and exit loop, and give trucks a 1-off order
                                    bAlsoSendTruckOrder = true
                                    AiBotTeam.TransferUnitsToPlayer(toTankReinforcements, oFirstPlayer:GetArmyIndex(), false)
                                    AiBotTeam.TransferUnitsToPlayer(toMAAReinforcements, oFirstPlayer:GetArmyIndex(), false)
                                    AiBotTeam.TransferUnitsToPlayer(toGunshipReinforcements, oFirstPlayer:GetArmyIndex(), false)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will gift units to oFirstPlayer') end
                                    break
                                end
                            end
                        end
                    end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    WaitSeconds(10)
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                end
                --Clear factory overrides and unit orders
                local toFactories = aiBrain:GetListOfUnits(AiBotUnitInfo.refCategoryFactory, false, true)
                if AiBotUtilities.IsTableEmpty(toFactories) == false then
                    for iFactory, oFactory in toFactories do
                        if oFactory[AiBotFactory.refsFactoryNextBlueprintOverride] then oFactory[AiBotFactory.refsFactoryNextBlueprintOverride] = nil end
                    end
                end

                if AiBotConditions.IsTableOfUnitsStillValid(toTankReinforcements) then
                    for iUnit, oUnit in toTankReinforcements do
                        oUnit[AiBotUnitInfo.refbSpecialMicroActive] = false
                        oUnit[AiBotUnitInfo.refiGameTimeToResetMicroActive] = nil
                    end
                end
                if AiBotConditions.IsTableOfUnitsStillValid(toMAAReinforcements) then
                    for iUnit, oUnit in toMAAReinforcements do
                        oUnit[AiBotUnitInfo.refbSpecialMicroActive] = false
                        oUnit[AiBotUnitInfo.refiGameTimeToResetMicroActive] = nil
                    end
                end
                if AiBotConditions.IsTableOfUnitsStillValid(toGunshipReinforcements) then
                    for iUnit, oUnit in toGunshipReinforcements do
                        oUnit[AiBotUnitInfo.refbSpecialMicroActive] = false
                        oUnit[AiBotUnitInfo.refiGameTimeToResetMicroActive] = nil
                    end
                end

                if bDebugMessages == true then LOG(sFunctionRef..': Considering if we should try giving civilian trucks an order, bAlsoSendTruckOrder='..tostring(bAlsoSendTruckOrder)..'; ScenarioInfo.M2P2.Active='..tostring(ScenarioInfo.M2P2.Active or false)..'; ScenarioInfo.M2P2Complete='..tostring(ScenarioInfo.M2P2Complete or false)) end

                --Monitor for the civilian trucks, and give them a 1-off order (even if AiBot not active) to go to the research facility (refresh the order if AiBotActive is enabled)
                if bAlsoSendTruckOrder and ScenarioInfo.M2P2.Active then
                    local refiTimeLastGivenTruckMoveOrder = 'AiBotUEFM2TruckOrder'
                    local tTruckTargetRect = import("/lua/sim/scenarioutilities.lua").AreaToRect('Research_Area')
                    local tTruckTargetMidpoint = {(tTruckTargetRect['x0'] + tTruckTargetRect['x1'])*0.5 , 0, (tTruckTargetRect['y0'] + tTruckTargetRect['y1'])*0.5}
                    local iDelayBeforeReissuingIfNoSpeed = 300
                    if oFirstPlayer.AiBotAI and oFirstPlayer == oAiBotBrain then iDelayBeforeReissuingIfNoSpeed = 120 end
                    WaitSeconds(2)

                    local bResetAiBotActiveFlag
                    local bTruckIncludedInPriorityDefence
                    while not(ScenarioInfo.M2P2Complete) do
                        if bDebugMessages == true then LOG(sFunctionRef..': Is TruckList empty='..tostring(AiBotUtilities.IsTableEmpty(ScenarioInfo.TruckList))..'; Time='..GetGameTimeSeconds()..'; ScenarioInfo.OpEnded='..tostring(ScenarioInfo.OpEnded or false)..'; iDelayBeforeReissuingIfNoSpeed='..iDelayBeforeReissuingIfNoSpeed) end
                        if AiBotUtilities.IsTableEmpty(ScenarioInfo.TruckList) == false then
                            for iTruck, oTruck in ScenarioInfo.TruckList do
                                if bDebugMessages == true and not(oTruck.Dead) then LOG(sFunctionRef..': COnsidering g iving order to oTruck='..oTruck.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTruck)..'; oTruck[refiTimeLastGivenTruckMoveOrder]='..(oTruck[refiTimeLastGivenTruckMoveOrder] or 'nil')..'; truck speed='..AiBotUnitInfo.GetUnitSpeed(oTruck)..'; refiGameTimeToResetMicroActive='..(oTruck[AiBotUnitInfo.refiGameTimeToResetMicroActive] or 'nil')..'; Dist to target midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oTruck:GetPosition(), tTruckTargetMidpoint)) end
                                if not(oTruck.Dead) and (((not(oTruck[refiTimeLastGivenTruckMoveOrder]) or oTruck.AiBotActive) and not(oTruck:IsUnitState('Attached')) and (AiBotUnitInfo.GetUnitSpeed(oTruck) < 0.1 or (oTruck.AiBotActive and (not(oTruck[AiBotUnitInfo.refiGameTimeToResetMicroActive]) or GetGameTimeSeconds() - oTruck[AiBotUnitInfo.refiGameTimeToResetMicroActive] <= 10)))) or (oTruck[refiTimeLastGivenTruckMoveOrder] and GetGameTimeSeconds() - oTruck[refiTimeLastGivenTruckMoveOrder] >= iDelayBeforeReissuingIfNoSpeed and AiBotUnitInfo.GetUnitSpeed(oTruck) == 0)) then
                                    if not(oTruck.AiBotActive) and not(AiBotOrders.bDontConsiderCombinedArmy) then
                                        --Temporarily set AiBotActive to true
                                        bResetAiBotActiveFlag = true
                                        oTruck.AiBotActive = true
                                    end
                                    AiBotOrders.IssueTrackedMove(oTruck, tTruckTargetMidpoint, 5, false, 'CampObjMTr', true)
                                    oTruck[AiBotUnitInfo.refiGameTimeToResetMicroActive] = GetGameTimeSeconds() + 120
                                    oTruck[AiBotUnitInfo.refbSpecialMicroActive] = true
                                    oTruck[refiTimeLastGivenTruckMoveOrder] = GetGameTimeSeconds()
                                    if bDebugMessages == true then LOG(sFunctionRef..': Given move order to truck') end
                                    if bResetAiBotActiveFlag then
                                        oTruck.AiBotActive = false
                                    end
                                    bTruckIncludedInPriorityDefence = false
                                    if not(AiBotTeam.tAirSubteamData[oAiBotBrain.AiBotAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam]) then
                                        AiBotTeam.tAirSubteamData[oAiBotBrain.AiBotAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam] = {}
                                    else
                                        for iRecordedTruck, oRecordedTruck in AiBotTeam.tAirSubteamData[oAiBotBrain.AiBotAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam] do
                                            if oTruck == oRecordedTruck then
                                                bTruckIncludedInPriorityDefence = true
                                                break
                                            end
                                        end
                                    end
                                    if not(bTruckIncludedInPriorityDefence) then
                                        table.insert(oTruck, AiBotTeam.tAirSubteamData[oAiBotBrain.AiBotAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam])
                                    end
                                end
                            end
                        end
                        WaitSeconds(10)
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UEFMissionSendTruckToTarget(tTrucks, tTargetMidpoint, sScenarioObjective, iOptionalSecondsToConsiderOverride, bRecheckObjectiveUnitTable)
    local sFunctionRef = 'UEFMissionSendTruckToTarget'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    --sScenarioObjective - either send as text the objective reference, such that doing .Active for this will return the right answer, or if the mission does something like ScenarioInfo.M1P2Complete = true then could send the refernece 'M1P2Complete'
    --bRecheckObjectiveUnitTable - if true then will look for ScenarioInfo[sScenarioObjective].units
    --Is player 1 AiBotAI?
    local oAiBotBrain, oFirstPlayer = GetAiBotBrainForCampaignObjective()
    if bDebugMessages == true then LOG(sFunctionRef..': oAiBotBrain='..(oAiBotBrain.Nickname or 'nil')) end
    if oAiBotBrain and oFirstPlayer then
        --refbCampaignSpecialLoopActive = 'AiBotCampActiveLoop' --against trucks part of the loop so we dont have multiple loops
        local refbGivenTruckOrder = 'AiBotUEFM2TruckOrder'
        local refiTimeLastGivenTruckMoveOrder = 'AiBotUEFM4TruckOrder'
        local oFirstTruckWithoutOrder
        for iTruck, oTruck in tTrucks do
            if not(oTruck.Dead) and not(oTruck[refiTimeLastGivenTruckMoveOrder]) and not(oTruck[refbCampaignSpecialLoopActive]) then
                oFirstTruckWithoutOrder = oTruck
                break
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': oFirstTruckWithoutOrder='..(oFirstTruckWithoutOrder.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFirstTruckWithoutOrder) or 'nil')..'; Time='..GetGameTimeSeconds()) end
        if oFirstTruckWithoutOrder then
            refbGivenTruckOrder = refbGivenTruckOrder..oFirstTruckWithoutOrder.EntityId

            if oAiBotBrain and oFirstPlayer and not(oAiBotBrain[refbGivenTruckOrder]) then
                local iTargetPlateau, iTargetZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tTargetMidpoint)
                if iTargetPlateau and iTargetZone and iTargetPlateau > 0 then
                    local iTargetIsland = NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tTargetMidpoint)
                    if iTargetIsland then
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering if we should try giving civilian trucks an order, ScenarioInfo.M2P2.Active='..tostring(ScenarioInfo.M2P2.Active or false)..'; ScenarioInfo.M2P2Complete='..tostring(ScenarioInfo.M2P2Complete or false)) end
                        local iTimeToCheckUntil = GetGameTimeSeconds() + (iOptionalSecondsToConsiderOverride or 90)



                        if AiBotUtilities.IsTableEmpty(tTrucks) == false then
                            local bResetAiBotActiveFlag
                            local bTruckIncludedInPriorityDefence
                            local iDelayBeforeReissuingIfNoSpeed = 300
                            if oFirstPlayer.AiBotAI and oFirstPlayer == oAiBotBrain then iDelayBeforeReissuingIfNoSpeed = 120 end
                            oAiBotBrain[refbGivenTruckOrder] = true
                            local refiCyclesWhereNotMovingWithoutOrder = 'AiBotTruckNoOrder'
                            for iTruck, oTruck in tTrucks do
                                if not(oTruck.Dead) then oTruck[refbCampaignSpecialLoopActive] = true end
                            end
                            while GetGameTimeSeconds() < iTimeToCheckUntil and (ScenarioInfo[sScenarioObjective].Active or not(ScenarioInfo[sScenarioObjective] == true)) do
                                if bDebugMessages == true then LOG(sFunctionRef..': Start of cycle for oFirstTruckWithoutOrder='..(oFirstTruckWithoutOrder.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFirstTruckWithoutOrder) or 'nil')..'; size of tTrucks='..table.getn(tTrucks)) end
                                for iCurTruck = table.getn(tTrucks), 1, -1 do
                                    local oTruck = tTrucks[iCurTruck]
                                    if oTruck.Dead then
                                        table.remove(tTrucks, iCurTruck)
                                    else
                                        if AiBotUnitInfo.IsUnitValid(oTruck) and AiBotUnitInfo.GetUnitSpeed(oTruck) == 0 then
                                            oTruck[refiCyclesWhereNotMovingWithoutOrder] = (oTruck[refiCyclesWhereNotMovingWithoutOrder] or 0) + 1
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': iCyclesWhereNotMovingWithoutOrder='..oTruck[refiCyclesWhereNotMovingWithoutOrder]..'; Is oTruck valid='..tostring(AiBotUnitInfo.IsUnitValid(oTruck))..'; oTruck='..oTruck.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTruck)..'; refiTimeLastGivenTruckMoveOrder='..(oTruck[refiTimeLastGivenTruckMoveOrder] or 'nil')..'; Time='..GetGameTimeSeconds()) end
                                        if (oTruck[refiCyclesWhereNotMovingWithoutOrder] or 0) > 1 and ((not(oTruck[refiTimeLastGivenTruckMoveOrder]) and oTruck[refiCyclesWhereNotMovingWithoutOrder] >= 60) or oTruck.AiBotActive or (oTruck:GetAIBrain().AiBotAI and oTruck:GetAIBrain().BrainType == 'AI') or (oTruck[refiCyclesWhereNotMovingWithoutOrder] >= 180 and AiBotUtilities.GetDistanceBetweenPositions(oTruck:GetPosition(), tTargetMidpoint) <= 70)) then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will give order to truck if not dead, oTruck='..oTruck.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTruck)) end
                                            if not(oTruck.Dead) and ((not(oTruck:IsUnitState('Attached')) and (AiBotUnitInfo.GetUnitSpeed(oTruck) < 0.1 or (oTruck.AiBotActive and (not(oTruck[AiBotUnitInfo.refiGameTimeToResetMicroActive]) or GetGameTimeSeconds() - oTruck[AiBotUnitInfo.refiGameTimeToResetMicroActive] <= 10)))) or (oTruck[refiTimeLastGivenTruckMoveOrder] and GetGameTimeSeconds() - oTruck[refiTimeLastGivenTruckMoveOrder] >= iDelayBeforeReissuingIfNoSpeed and AiBotUnitInfo.GetUnitSpeed(oTruck) == 0)) then
                                                oTruck[refiCyclesWhereNotMovingWithoutOrder] = 0
                                                --Temporarily set AiBotActive to true
                                                if oFirstPlayer == oAiBotBrain and not(oTruck.AiBotActive) and not(AiBotOrders.bDontConsiderCombinedArmy) then
                                                    bResetAiBotActiveFlag = true
                                                    oTruck.AiBotActive = true
                                                end
                                                AiBotOrders.IssueTrackedMove(oTruck, tTargetMidpoint, 5, false, 'CampObjMTr', true)
                                                oTruck[AiBotUnitInfo.refiGameTimeToResetMicroActive] = GetGameTimeSeconds() + 120
                                                oTruck[AiBotUnitInfo.refbSpecialMicroActive] = true
                                                oTruck[refiTimeLastGivenTruckMoveOrder] = GetGameTimeSeconds()
                                                if bDebugMessages == true then LOG(sFunctionRef..': Given move order to truck') end
                                                if bResetAiBotActiveFlag then
                                                    oTruck.AiBotActive = false
                                                end
                                                bTruckIncludedInPriorityDefence = false
                                                if not(AiBotTeam.tAirSubteamData[oAiBotBrain.AiBotAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam]) then
                                                    AiBotTeam.tAirSubteamData[oAiBotBrain.AiBotAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam] = {}
                                                else
                                                    for iRecordedTruck, oRecordedTruck in AiBotTeam.tAirSubteamData[oAiBotBrain.AiBotAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam] do
                                                        if oTruck == oRecordedTruck then
                                                            bTruckIncludedInPriorityDefence = true
                                                            break
                                                        end
                                                    end
                                                end
                                                if not(bTruckIncludedInPriorityDefence) then
                                                    table.insert(oTruck, AiBotTeam.tAirSubteamData[oAiBotBrain.AiBotAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam])
                                                end
                                            end
                                        end
                                    end
                                end
                                WaitSeconds(1)
                            end
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UEFBlackSunComponentCheckForTransport()       
    --Looks to load a transport with the component and send the transport to black sun periodically, including ordering an air factory to build a transport if we have none
    local sFunctionRef = 'UEFBlackSunComponentCheckForTransport'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local oAiBotBrain, oFirstPlayer = GetAiBotBrainForCampaignObjective()
    local refbUEFM6Monitor = 'AiBotUEFM6TruckMonitor'
    if oAiBotBrain and not(oAiBotBrain[refbUEFM6Monitor]) and AiBotUnitInfo.IsUnitValid(ScenarioInfo.BlackSunComponent) then
        oAiBotBrain[refbUEFM6Monitor] = true
        local oTransportToGiveOrder
        local oComponent = ScenarioInfo.BlackSunComponent
        local tComponentStartingPosition = { oComponent:GetPosition()[1], oComponent:GetPosition()[2], oComponent:GetPosition()[3] }
        local oAeonBrain
        for iBrain, oBrain in ArmyBrains do
            if oBrain.Nickname == 'Aeon' then
                oAeonBrain = oBrain
                break
            end
        end
        if not(oAeonBrain) then
            for iBrain, oBrain in ArmyBrains do
                if oBrain:GetArmyIndex() == ScenarioInfo.Aeon then
                    oAeonBrain = oBrain
                    break
                end
            end
        end
        if oAeonBrain then
            --First wait at least 10 minutes
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(600)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            local bDontRequireAiBotActive = true
            if oAiBotBrain == oFirstPlayer and not(AiBotOrders.bDontConsiderCombinedArmy) then
                bDontRequireAiBotActive = false
            end
            local toFactoriesGivenOverride

            local rTargetRect = import("/lua/sim/scenarioutilities.lua").AreaToRect('Black_Sun_Component_Area')
            local tTargetMidpoint = {(rTargetRect['x0'] + rTargetRect['x1'])*0.5 , 0, (rTargetRect['y0'] + rTargetRect['y1'])*0.5}
            tTargetMidpoint[2] = GetTerrainHeight(tTargetMidpoint[1], tTargetMidpoint[3])
            if bDebugMessages == true then LOG(sFunctionRef..': About to start the main loop, black sun drop location='..repru(tTargetMidpoint)..'; tComponentStartingPosition='..repru(tComponentStartingPosition)..'; Time='..GetGameTimeSeconds()..'; Dist from oComponent to tTargetMidpoint='..AiBotUtilities.GetDistanceBetweenPositions(oComponent:GetPosition(), tTargetMidpoint)) end
            while AiBotUnitInfo.IsUnitValid(oComponent) and (ScenarioInfo.M1P2.Active or ScenarioInfo.MissionNumber == 1) do
                if bDebugMessages == true then LOG(sFunctionRef..': Start of loop, oComponent unit state='..AiBotUnitInfo.GetUnitState(oComponent)..'; is oTransportToGiveOrder valid='..tostring(AiBotUnitInfo.IsUnitValid(oTransportToGiveOrder))..'; Time='..GetGameTimeSeconds()) end
                if not(oComponent:IsUnitState('Attached')) and not(AiBotUnitInfo.IsUnitValid(oTransportToGiveOrder)) then
                    --If component has moved significantly then abort
                    if bDebugMessages == true then LOG(sFunctionRef..': Copmonent dist from original position='..AiBotUtilities.GetDistanceBetweenPositions(oComponent:GetPosition(), tComponentStartingPosition)..'; Dist from component to black sun target='..AiBotUtilities.GetDistanceBetweenPositions(oComponent:GetPosition(), tTargetMidpoint)) end
                    if AiBotUtilities.GetDistanceBetweenPositions(oComponent:GetPosition(), tComponentStartingPosition) >= 100 then
                        if bDebugMessages == true then LOG(sFunctionRef..': Component has moved from start so presumably landed near black sun') end
                    else
                        --Is the area around the component safe from enemy ground to air? (ignore air to air) and also no nearby battleships or destroyers?
                        local tEnemyGroundAA = oAeonBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryGroundAA + AiBotUnitInfo.refCategoryBattleship + AiBotUnitInfo.refCategoryDestroyer, tComponentStartingPosition, 120, 'Ally') --180 catches off-map enemies
                        if bDebugMessages == true then LOG(sFunctionRef..': Is tEnemyGroundAA empty='..tostring(AiBotUtilities.IsTableEmpty( tEnemyGroundAA))) end
                        if AiBotUtilities.IsTableEmpty( tEnemyGroundAA) then
                            --Find a transport to give an order to
                            local tTransports = oAiBotBrain:GetListOfUnits(AiBotUnitInfo.refCategoryTransport, false, true)
                            if AiBotUtilities.IsTableEmpty(tTransports) == false then
                                for iTransport, oTransport in tTransports do
                                    if oTransport:GetFractionComplete() == 1 and (bDontRequireAiBotActive or oTransport.AiBotActive) and not(oTransport[AiBotUnitInfo.refbSpecialMicroActive]) then
                                        oTransportToGiveOrder = oTransport
                                        break
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': oTransportToGiveOrder='..(oTransportToGiveOrder.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oTransportToGiveOrder) or 'nil')..'; bDontRequireAiBotActive='..tostring(bDontRequireAiBotActive)..'; oTransport.AiBotActive='..tostring(oTransportToGiveOrder.AiBotActive or false)) end
                            if not(oTransportToGiveOrder) then
                                --Find an air fac and tell it to build a transport
                                local toAirFactories = oAiBotBrain:GetListOfUnits(AiBotUnitInfo.refCategoryAirFactory, false, true)
                                if AiBotUtilities.IsTableEmpty(toAirFactories) == false then
                                    local oFirstFactory
                                    local oFactoryToGiveOverride
                                    for iFactory, oFactory in toAirFactories do
                                        if bDontRequireAiBotActive or oFactory.AiBotActive then
                                            oFactoryToGiveOverride = oFactory
                                            break
                                        elseif not(oFirstFactory) then
                                            oFirstFactory = oFactory
                                        end
                                    end
                                    if not(oFactoryToGiveOverride) and oFirstFactory then oFactoryToGiveOverride = oFirstFactory end
                                    if oFactoryToGiveOverride then
                                        local bAlreadyRecorded = false
                                        if not(toFactoriesGivenOverride) then toFactoriesGivenOverride = {}
                                        else
                                            for iRecordedFactory, oRecordedFactory in toFactoriesGivenOverride do
                                                if oRecordedFactory == oFactoryToGiveOverride then
                                                    bAlreadyRecorded = true
                                                end
                                            end
                                        end
                                        if not(bAlreadyRecorded) then table.insert(toFactoriesGivenOverride, oFactoryToGiveOverride) end
                                        oFactoryToGiveOverride[AiBotFactory.refsFactoryNextBlueprintOverride] = AiBotFactory.GetBlueprintThatCanBuildOfCategory(oAiBotBrain, AiBotUnitInfo.refCategoryTransport, oFactoryToGiveOverride, false, false, false, nil, false, nil, true)
                                    end
                                end
                            else
                                --We have a transport we can give an order to, clear any factory overrides
                                if AiBotUtilities.IsTableEmpty(toFactoriesGivenOverride) == false then
                                    for iFactory, oFactory in toFactoriesGivenOverride do
                                        oFactory[AiBotFactory.refsFactoryNextBlueprintOverride] = nil
                                    end
                                    toFactoriesGivenOverride = nil
                                end

                                --Tell the transport to pickup the component, and queue up an order to unload at black sun
                                oTransportToGiveOrder[AiBotUnitInfo.refbSpecialMicroActive] = true
                                oTransportToGiveOrder[AiBotUnitInfo.refiGameTimeToResetMicroActive] = GetGameTimeSeconds() + 120
                                local iTimeGivenLoadOrder
                                if bDebugMessages == true then LOG(sFunctionRef..': Will start loop to get tarnsport into position near component, oTransportToGiveOrder[AiBotUnitInfo.refbSpecialMicroActive]='..tostring(oTransportToGiveOrder[AiBotUnitInfo.refbSpecialMicroActive] or false)) end
                                while AiBotUnitInfo.IsUnitValid(oTransportToGiveOrder) and AiBotUnitInfo.IsUnitValid(oComponent) and not(oComponent:IsUnitState('Attached')) do
                                    --Move transport to component
                                    if AiBotUtilities.GetDistanceBetweenPositions(oTransportToGiveOrder:GetPosition(), oComponent:GetPosition()) >= 15 then
                                        --IssueTrackedMove(oUnit,                 tOrderPosition, iDistanceToReissueOrder, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder)
                                        AiBotOrders.IssueTrackedMove(oTransportToGiveOrder, oComponent:GetPosition(), 5,                  false, 'MoveToComp', true)
                                        oTransportToGiveOrder[AiBotUnitInfo.refbSpecialMicroActive] = true
                                        oTransportToGiveOrder[AiBotUnitInfo.refiGameTimeToResetMicroActive] = GetGameTimeSeconds() + 120
                                        if bDebugMessages == true then LOG(sFunctionRef..': Told transport to move to the component oComponent='..oComponent.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oComponent)..', time='..GetGameTimeSeconds()..'; Transport unit state='..AiBotUnitInfo.GetUnitState(oTransportToGiveOrder)..'; Dist to component='..AiBotUtilities.GetDistanceBetweenPositions(oTransportToGiveOrder:GetPosition(), oComponent:GetPosition())..'; oTransportToGiveOrder[AiBotUnitInfo.refbSpecialMicroActive]='..tostring(oTransportToGiveOrder[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; Component position='..repru(oComponent:GetPosition())..'; Is this in playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(oComponent:GetPosition()))) end
                                    else
                                        if bDebugMessages == true then LOG(sFunctionRef..': Told component to load onto transport, Time='..GetGameTimeSeconds()) end
                                        IssueTransportLoad({oComponent}, oTransportToGiveOrder)
                                        iTimeGivenLoadOrder = GetGameTimeSeconds()
                                        oTransportToGiveOrder[AiBotUnitInfo.refbSpecialMicroActive] = true
                                        oTransportToGiveOrder[AiBotUnitInfo.refiGameTimeToResetMicroActive] = GetGameTimeSeconds() + 120
                                        break
                                    end
                                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                    WaitSeconds(1)
                                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                                end
                                if iTimeGivenLoadOrder then
                                    while AiBotUnitInfo.IsUnitValid(oTransportToGiveOrder) and AiBotUnitInfo.IsUnitValid(oComponent) and not(oComponent:IsUnitState('Attached')) do
                                        if GetGameTimeSeconds() - iTimeGivenLoadOrder >= 30 then
                                            IssueTransportLoad({oComponent}, oTransportToGiveOrder)
                                            iTimeGivenLoadOrder = GetGameTimeSeconds()
                                            oTransportToGiveOrder[AiBotUnitInfo.refbSpecialMicroActive] = true
                                            oTransportToGiveOrder[AiBotUnitInfo.refiGameTimeToResetMicroActive] = GetGameTimeSeconds() + 120
                                            if bDebugMessages == true then LOG(sFunctionRef..': Given new load component order') end
                                        end
                                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                        WaitSeconds(1)
                                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                                    end
                                    if AiBotUnitInfo.IsUnitValid(oTransportToGiveOrder) and AiBotUnitInfo.IsUnitValid(oComponent) and oComponent:IsUnitState('Attached') then
                                        AiBotOrders.IssueTrackedTransportUnload(oTransportToGiveOrder, tTargetMidpoint, 5, false, 'ObjUnl', true)
                                        oTransportToGiveOrder[AiBotUnitInfo.refbSpecialMicroActive] = true
                                        oTransportToGiveOrder[AiBotUnitInfo.refiGameTimeToResetMicroActive] = GetGameTimeSeconds() + 300
                                        if bDebugMessages == true then LOG(sFunctionRef..': Given unload order, refbSpecialMicroActive='..tostring(oTransportToGiveOrder[AiBotUnitInfo.refbSpecialMicroActive] or false)) end
                                        --Check the component, once it is no longer attached, and is still valid, give it a move order
                                        local iTimeBetweenOrders = 2
                                        local bResetActiveFlag = false
                                        while AiBotUnitInfo.IsUnitValid(oComponent) and (ScenarioInfo.M1P2.Active or ScenarioInfo.MissionNumber == 1) do
                                            if not(oComponent:IsUnitState('Attached')) then
                                                local iAngleToBlackSun = AiBotUtilities.GetAngleFromAToB(oComponent:GetPosition(), tTargetMidpoint)
                                                local tMoveDirection = AiBotUtilities.MoveInDirection(oComponent:GetPosition(), iAngleToBlackSun, math.random(3,6), true, false, true)
                                                if not(bDontRequireAiBotActive) and not(oComponent.AiBotActve) then
                                                    oComponent.AiBotActive = true
                                                    bResetActiveFlag = true
                                                    iTimeBetweenOrders = 60
                                                end
                                                AiBotOrders.IssueTrackedMove(oComponent, tMoveDirection, 3, false, 'ObjMvBlckSn', true)
                                                if bResetActiveFlag then oComponent.AiBotActive = false end
                                                if bDebugMessages == true then LOG(sFunctionRef..': Telling component to move, iAngleToBlackSun='..iAngleToBlackSun..'; Dist='..AiBotUtilities.GetDistanceBetweenPositions(oComponent:GetPosition(), tTargetMidpoint)..'; oComponent'..oComponent.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oComponent)..'; tMoveDirection='..repru(tMoveDirection))
                                                    if AiBotUtilities.IsTableEmpty(tMoveDirection) == false then
                                                        AiBotUtilities.DrawLocation(tMoveDirection)
                                                    end
                                                end
                                            end
                                            WaitSeconds(iTimeBetweenOrders)
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': About to exit main loop') end
                                        break
                                    end
                                end

                            end
                        elseif bDebugMessages == true then
                            LOG(sFunctionRef..': GroundAA threat='..AiBotUnitInfo.GetAirThreatLevel(tEnemyGroundAA, true, false, true, false, false, false))
                            for iUnit, oUnit in tEnemyGroundAA do
                                LOG(sFunctionRef..': oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Dist to tComponentStartingPosition'..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tComponentStartingPosition)..'; refiAARange='..(oUnit[AiBotUnitInfo.refiAARange] or 'nil'))
                            end
                        end
                    end
                elseif oTransportToGiveOrder then
                    --Maintain micro tracking
                    oTransportToGiveOrder[AiBotUnitInfo.refbSpecialMicroActive] = true
                    oTransportToGiveOrder[AiBotUnitInfo.refiGameTimeToResetMicroActive] = GetGameTimeSeconds() + 120
                    if bDebugMessages == true then LOG(sFunctionRef..': Transport unit state='..AiBotUnitInfo.GetUnitState(oTransportToGiveOrder)..'; Dist to component='..AiBotUtilities.GetDistanceBetweenPositions(oTransportToGiveOrder:GetPosition(), oComponent:GetPosition())) end
                end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitSeconds(20)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            end
            if AiBotUtilities.IsTableEmpty(toFactoriesGivenOverride) == false then
                for iFactory, oFactory in toFactoriesGivenOverride do
                    oFactory[AiBotFactory.refsFactoryNextBlueprintOverride] = nil
                end
            end
            --Reset micro flag once no cargo
            while AiBotUnitInfo.IsUnitValid(oTransportToGiveOrder) and oTransportToGiveOrder[AiBotUnitInfo.refbSpecialMicroActive] do
                local tCargo = oTransportToGiveOrder:GetCargo()
                if AiBotUtilities.IsTableEmpty(tCargo) then
                    oTransportToGiveOrder[AiBotUnitInfo.refbSpecialMicroActive] = false
                    oTransportToGiveOrder[AiBotUnitInfo.refiGameTimeToResetMicroActive] = GetGameTimeSeconds()
                end
                WaitSeconds(1)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetAiBotBrainForCampaignObjective(bAlsoGetFirstPlayer)
    local sFunctionRef = 'GetAiBotBrainForCampaignObjective'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local oFirstPlayer
    local oAiBotBrain
    for iBrain, oBrain in ArmyBrains do
        if oBrain.AiBotAI then
            if bDebugMessages == true then LOG(sFunctionRef..': Considering oBrain='..oBrain.Nickname..'; .BrainType='..(oBrain.BrainType or 'nil')..'; .AiBotTeam='..(oBrain.AiBotTeam or 'nil')..'; Does nickname contain AiBot='..tostring(AiBotConditions.DoesAINicknameContainAiBot(oBrain.Nickname))..'; oBrain.AiBotAI='..tostring(oBrain.AiBotAI or false)..'; oFirstPlayer.AiBotTeam='..(oFirstPlayer.AiBotTeam or 'nil')) end
            if not(oFirstPlayer) and oBrain.BrainType == 'Human' then
                oFirstPlayer = oBrain
                if bDebugMessages == true then LOG(sFunctionRef..': Recording as oFirstPlayer') end
                if oAiBotBrain then break end
            end
            if oBrain.AiBotAI and oBrain.BrainType == 'AI' and AiBotConditions.DoesAINicknameContainAiBot(oBrain.Nickname) and oBrain.AiBotTeam == oFirstPlayer.AiBotTeam then
                oAiBotBrain = oBrain
                if bDebugMessages == true then LOG(sFunctionRef..': Recording as oAiBotBrain') end
                if oFirstPlayer then break end
            end
        elseif not(oFirstPlayer) and oBrain.BrainType == 'Human' then
            oFirstPlayer = oBrain
            if oAiBotBrain then break end
        end
    end
    if not(oAiBotBrain) and oFirstPlayer.AiBotAI then oAiBotBrain = oFirstPlayer end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    if bAlsoGetFirstPlayer then
        return oAiBotBrain, oFirstPlayer
    else
        return oAiBotBrain
    end
end

function TellFactoryToBuildSpecificUnitInCampaignMission(iTeam, iFactoryCategory, iUnitsWanted, iCategoryWanted, iSecondUnitsWanted, iSecondCategoryWanted, iThirdUnitsWanted, iThirdCategoryWanted, sOptionalUniqueReference)
    --Will first get iCategoryWanted, then ocne have iUnitsWanted will move on to iSecondCategoryWnated if it is specified, and then third unitswanted and thirdcategorywanted
    local sFunctionRef = 'TellFactoryToBuildSpecificUnitInCampaignMission'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local oAiBotBrain = GetAiBotBrainForCampaignObjective()
    if oAiBotBrain and oAiBotBrain.AiBotTeam == iTeam then
        local refbFactorySpecificUnitCheckActive = 'AiBotCampFacOvrd'
        if sOptionalUniqueReference then refbFactorySpecificUnitCheckActive = refbFactorySpecificUnitCheckActive..sOptionalUniqueReference end
        if not(oAiBotBrain[refbFactorySpecificUnitCheckActive]) then
            oAiBotBrain[refbFactorySpecificUnitCheckActive] = true
            local iCategoryCycle = 0

            function GetUnitsOfCategory(iCurNumberWanted, iCurCategoryWanted)
                local iLifetimeCountThreshold = iCurNumberWanted * 2
                local iCurUnitsOfCategory = oAiBotBrain:GetCurrentUnits(iCurCategoryWanted)
                local oPrimaryFactory
                local bWantNavalFac = false
                if iFactoryCategory == AiBotUnitInfo.refCategoryNavalFactory then bWantNavalFac = true end
                local iUnderConstructionCount = 0
                iCategoryCycle = iCategoryCycle + 1
                if bDebugMessages == true then LOG(sFunctionRef..': About to start new loop, iCategoryCycle='..iCategoryCycle..'; iCurUnitsOfCategory='..iCurUnitsOfCategory..'; Time='..GetGameTimeSeconds()) end
                local bAddOverrides = false

                while iCurUnitsOfCategory < iCurNumberWanted and AiBotConditions.GetLifetimeBuildCount(oAiBotBrain, iCurCategoryWanted) < iLifetimeCountThreshold do
                    bAddOverrides = iCurUnitsOfCategory + iUnderConstructionCount < iCurNumberWanted
                    local toFactories = oAiBotBrain:GetListOfUnits(iFactoryCategory, false, false)
                    if bDebugMessages == true then LOG(sFunctionRef..': bAddOverrides='..tostring(bAddOverrides)..'; is toFactories empty='..tostring(AiBotUtilities.IsTableEmpty(toFactories))) end
                    if AiBotUtilities.IsTableEmpty(toFactories) == false then
                        for iUnit, oUnit in toFactories do
                            if bAddOverrides then
                            --if not(oUnit[AiBotFactory.refsFactoryNextBlueprintOverride]) then
                                bWantNavalFac = EntityCategoryContains(AiBotUnitInfo.refCategoryNavalFactory, oUnit.UnitId)
                                oUnit[AiBotFactory.refsFactoryNextBlueprintOverride] =  AiBotFactory.GetBlueprintThatCanBuildOfCategory(oAiBotBrain, iCurCategoryWanted, oUnit, false, false, false, nil, false, nil, true)
                                if AiBotUnitInfo.GetUnitLifetimeCount(oUnit) == 1 then oUnit[AiBotFactory.refbPrimaryFactoryForIslandOrPond] = true oPrimaryFactory = oUnit end
                                if bDebugMessages == true then LOG(sFunctionRef..': Set factory '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to build iCurCategoryWanted blueprint='..(oUnit[AiBotFactory.refsFactoryNextBlueprintOverride] or 'nil')) end
                            elseif oUnit[AiBotFactory.refsFactoryNextBlueprintOverride] and EntityCategoryContains(iCurCategoryWanted, oUnit[AiBotFactory.refsFactoryNextBlueprintOverride]) and ((oUnit[AiBotFactory.refsLastBlueprintBuilt] and oUnit[AiBotFactory.refsFactoryNextBlueprintOverride] == oUnit[AiBotFactory.refsLastBlueprintBuilt]) or EntityCategoryContains(AiBotUnitInfo.refCategoryFactory, oUnit[AiBotFactory.refsFactoryNextBlueprintOverride])) then
                                iUnderConstructionCount = iUnderConstructionCount + 1
                            end
                        end
                    end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    if bWantNavalFac then WaitSeconds(3) else WaitSeconds(1) end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                    iCurUnitsOfCategory = oAiBotBrain:GetCurrentUnits(iCurCategoryWanted)
                    if iUnderConstructionCount == 0 and AiBotUnitInfo.IsUnitValid(oPrimaryFactory) and oPrimaryFactory:GetWorkProgress() >= 0.05 then
                        if bDebugMessages == true then LOG(sFunctionRef..': Primary override Will increase iCurUnitsOfCategory if primary factory is almost complete, workprogress='..oPrimaryFactory:GetWorkProgress()..'; oPrimaryFactory[AiBotFactory.refsLastBlueprintBuilt]='..(oPrimaryFactory[AiBotFactory.refsLastBlueprintBuilt] or 'nil')) end
                        if oPrimaryFactory[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefsOrderBlueprint] == oPrimaryFactory[AiBotFactory.refsFactoryNextBlueprintOverride] and oPrimaryFactory[AiBotFactory.refsFactoryNextBlueprintOverride] and EntityCategoryContains(iCurCategoryWanted, oPrimaryFactory[AiBotFactory.refsFactoryNextBlueprintOverride]) then
                            iUnderConstructionCount = iUnderConstructionCount + 1
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering starting primary loop again, time='..GetGameTimeSeconds()..'; iCurUnitsOfCategory='..iCurUnitsOfCategory..'; iUnderConstructionCount='..iUnderConstructionCount..'; bAddOverrides='..tostring(bAddOverrides)) end
                end
            end
            GetUnitsOfCategory(iUnitsWanted, iCategoryWanted)

            if bDebugMessages == true then LOG(sFunctionRef..': Got all the primary category we want, iSecondUnitsWanted='..(iSecondUnitsWanted or 'nil')) end
            if iSecondUnitsWanted then
                GetUnitsOfCategory(iSecondUnitsWanted, iSecondCategoryWanted)
                if bDebugMessages == true then LOG(sFunctionRef..': Got all secondary category we want, moving onto third cateogry, iThirdUnitsWanted='..(iThirdUnitsWanted or 'nil')) end
                if iThirdUnitsWanted then
                    GetUnitsOfCategory(iThirdUnitsWanted, iThirdCategoryWanted)
                end
            end

            if bDebugMessages == true then LOG(sFunctionRef..': Finished building all the units we want') end
            local toFactories = oAiBotBrain:GetListOfUnits(iFactoryCategory, false, false)
            if AiBotUtilities.IsTableEmpty(toFactories) == false then
                for iUnit, oUnit in toFactories do
                    oUnit[AiBotFactory.refsFactoryNextBlueprintOverride] = nil
                end
            end
        end
    end
end

function SendACUsToCampaignObjective(sArea)
    local sFunctionRef = 'SendACUsToCampaignObjective'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local tRect = import("/lua/sim/scenarioutilities.lua").AreaToRect(sArea)
    local rRect = {tRect['x0'], tRect['y0'], tRect['x1'], tRect['y1']}
    if bDebugMessages == true then LOG(sFunctionRef..': rRect='..repru(rRect)..'; AreaToRect='..repru(import("/lua/sim/scenarioutilities.lua").AreaToRect(sArea))) end
    if rRect then
        local tMidpoint = {(rRect[1] + rRect[3])*0.5, 0, (rRect[2] + rRect[4])*0.5}
        tMidpoint[2] = GetTerrainHeight(tMidpoint[1], tMidpoint[3])
        local tAiBotACUs = ScenarioInfo.PlayerCDRs
        if AiBotUtilities.IsTableEmpty(tAiBotACUs) then
            local oAiBotBrain = GetAiBotBrainForCampaignObjective()
            if oAiBotBrain then
                tAiBotACUs = AiBotTeam.tTeamData[oAiBotBrain.AiBotTeam][AiBotTeam.reftAiBotACUs]
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Is tAiBotACUs empty='..tostring(AiBotUtilities.IsTableEmpty(tAiBotACUs))) end
        if AiBotUtilities.IsTableEmpty(tAiBotACUs) == false then
            for iUnit, oUnit in tAiBotACUs do
                if AiBotUnitInfo.IsUnitValid(oUnit) then
                    LOG(sFunctionRef..': Considering ACU owned by brain '..oUnit:GetAIBrain().Nickname..'; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; if AiBot then will set objective to tMidpoint='..repru(tMidpoint))
                    if oUnit:GetAIBrain().AiBotAI and not(oUnit:GetAIBrain().CampaignAI) then
                        oUnit[AiBotACU.reftSpecialObjectiveMoveLocation] = {tMidpoint[1], tMidpoint[2], tMidpoint[3]}
                    end
                end
            end
        end

    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function CybranM6SendCampaignACUToNearestGateway()
    local sFunctionRef = 'SendACUsToCampaignObjective'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local tAiBotACUs = ScenarioInfo.PlayerCDRs
    if AiBotUtilities.IsTableEmpty(tAiBotACUs) then
        local oAiBotBrain = GetAiBotBrainForCampaignObjective()
        if oAiBotBrain then
            tAiBotACUs = AiBotTeam.tTeamData[oAiBotBrain.AiBotTeam][AiBotTeam.reftAiBotACUs]
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Is tAiBotACUs empty='..tostring(AiBotUtilities.IsTableEmpty(tAiBotACUs))) end
    if AiBotUtilities.IsTableEmpty(tAiBotACUs) == false then
        while AiBotConditions.IsTableOfUnitsStillValid(tAiBotACUs) do
            --Do we have a gateway?
            for iUnit, oUnit in tAiBotACUs do
                LOG(sFunctionRef..': Considering ACU owned by brain '..oUnit:GetAIBrain().Nickname..'; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; if AiBot then will send to gateway we own if if ScenarioInfo.M2P2.Active is true, if ScenarioInfo.M2P2.Active='..tostring(ScenarioInfo.M2P2.Active or false))
                if ScenarioInfo.M2P2.Active then
                    if oUnit:GetAIBrain().AiBotAI and not(oUnit:GetAIBrain().CampaignAI) and (oUnit.AiBotActive or AiBotOrders.bDontConsiderCombinedArmy) then
                        local tFriendlyGateways = oUnit:GetAIBrain():GetListOfUnits(AiBotUnitInfo.refCategoryQuantumGateway, false, true)
                        if tFriendlyGateways[1] then
                            local tMidpoint = tFriendlyGateways[1]:GetPosition()
                            oUnit[AiBotACU.reftSpecialObjectiveMoveLocation] = {tMidpoint[1], tMidpoint[2], tMidpoint[3]}
                            if bDebugMessages == true then LOG(sFunctionRef..': Set ACU owned by '..oUnit:GetAIBrain().Nickname..' to have reftSpecialObjectiveMoveLocation to be the friendly gateway at time='..GetGameTimeSeconds()) end
                        end
                    end
                else
                    oUnit[AiBotACU.reftSpecialObjectiveMoveLocation] = nil
                end
            end
            if not(ScenarioInfo.M2P2.Active) then
                if bDebugMessages == true then LOG(sFunctionRef..': M2P2 no longer active so aborting loop') end
                break
            end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(60)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function PeriodicallySendEngineerToCaptureTarget(oCaptureTarget, sOptionalObjectiveRef, iOptionalStartingWait)
    local sFunctionRef = 'PeriodicallySendEngineerToCaptureTarget'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local oAiBotBrain = GetAiBotBrainForCampaignObjective()
    if oAiBotBrain then
        local iTeam = oAiBotBrain.Team
        local iTargetPlateau = oCaptureTarget[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]
        local iTimeWaitedWithLastEngineer
        --Wait 10 minutes first to give a chance to control the area
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(iOptionalStartingWait or 600)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        local toEngineersGivenOrderTo = {}
        local iTimeToWait
        while AiBotUnitInfo.IsUnitValid(oCaptureTarget) and ((sOptionalObjectiveRef and ScenarioInfo[sOptionalObjectiveRef].Active) or not(sOptionalObjectiveRef)) do
            --Is the target free from significant enemy fortifications?
            local tNearbyEnemies = oAiBotBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryFirebaseSuitable + categories.EXPERIMENTAL, oCaptureTarget:GetPosition(), 60, 'Enemy')
            if bDebugMessages == true then LOG(sFunctionRef..': Is tNearbyEnemies empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyEnemies))..'; time='..GetGameTimeSeconds()) end
            if AiBotUtilities.IsTableEmpty(tNearbyEnemies) then
                iTimeWaitedWithLastEngineer = 0
                local tFriendlyEngineers = oAiBotBrain:GetListOfUnits(AiBotUnitInfo.refCategoryEngineer, false, true)
                if AiBotUtilities.IsTableEmpty(tFriendlyEngineers) == false then
                    for iEngineer, oEngineer in tFriendlyEngineers do
                        if not(oEngineer.Dead) and oEngineer:GetFractionComplete() == 1 and oEngineer[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iTargetPlateau and (oEngineer.AiBotActive or AiBotOrders.bDontConsiderCombinedArmy) and not(oEngineer[AiBotUnitInfo.refbSpecialMicroActive]) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Have an engineer which we will send a capture order to, oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; Time='..GetGameTimeSeconds()) end
                            AiBotOrders.IssueTrackedCapture(oEngineer, oCaptureTarget, false, 'CamOCapt', true)
                            AiBotEngineer.TrackEngineerAction(oEngineer, AiBotEngineer.refActionCaptureUnit, true, 1, nil, nil, false)
                            table.insert(toEngineersGivenOrderTo, oEngineer)
                            while AiBotUnitInfo.IsUnitValid(oEngineer) and AiBotUnitInfo.IsUnitValid(oCaptureTarget) do
                                if bDebugMessages == true then LOG(sFunctionRef..': Dist from engineer to capture target='..AiBotUtilities.GetDistanceBetweenPositions(oEngineer:GetPosition(), oCaptureTarget:GetPosition())..'; Time='..GetGameTimeSeconds()) end
                                oEngineer[AiBotUnitInfo.refbSpecialMicroActive] = true
                                oEngineer[AiBotUnitInfo.refiGameTimeToResetMicroActive] = GetGameTimeSeconds() + 15
                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                WaitSeconds(10)
                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                                iTimeWaitedWithLastEngineer = iTimeWaitedWithLastEngineer + 10
                                if iTimeWaitedWithLastEngineer >= 180 then
                                    if AiBotConditions.IsTableOfUnitsStillValid(toEngineersGivenOrderTo) and table.getn(toEngineersGivenOrderTo) >= 10 then --redundancy, cant see this scenario happening
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will stick with this engineer as we have 10 with active orders') end
                                    else
                                        if bDebugMessages == true then LOG(sFunctionRef..': Been more than 3 minutes so will start a new cycle') end
                                        break
                                    end --send another incase the first dies
                                end
                            end
                            iTimeToWait = math.max(10, 180 - iTimeWaitedWithLastEngineer)
                            break
                        end
                    end
                else
                    iTimeToWait = 10
                end
            else
                iTimeToWait = 10
            end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(iTimeToWait)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end
        if AiBotConditions.IsTableOfUnitsStillValid(toEngineersGivenOrderTo) then
            for iEngineer, oEngineer in toEngineersGivenOrderTo do
                oEngineer[AiBotUnitInfo.refbSpecialMicroActive] = false
                AiBotOrders.IssueTrackedClearCommands(oEngineer)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DelayedKillUnits(toUnits, iSecondsToWait)
    WaitSeconds(iSecondsToWait)
    if AiBotConditions.IsTableOfUnitsStillValid(toUnits) then
        for iUnit, oUnit in toUnits do
            AiBotOrders.IssueTrackedKillUnit(oUnit)
        end
    end
end
